  echo "export const x = 1;" > metrics-bridge/src/existing.ts
  git add package.json pnpm-lock.yaml metrics-bridge/src/existing.ts
  git commit -qm init
  cat > pnpm-lock.yaml <<'YAML'
lockfileVersion: '9.0'
settings:
  autoInstallPeers: true
overrides: {}
importers:
  .:
    dependencies: {}
