# family: stamps-freshness
# The fresh-run stamp: what busts it (content, file mode, index state,
# command plan, base OID, gate implementation) and what may reuse it.
run_stamps_freshness_family() {
arm_suite_abort_trap

# Focused freshness runs do not execute the coordinator family's cleanup
# helpers. Bind each cleanup signal to the metadata PID and start time here.
gate_test_process_start() {
  local pid="$1"
  [[ "$pid" =~ ^[0-9]+$ ]] || return 1
  TZ=UTC LC_ALL=C LANG=C ps -p "$pid" -o lstart= 2>/dev/null |
    head -n1 |
    sed 's/^[[:space:]]*//; s/[[:space:]]*$//' || true
}

gate_test_process_parent() {
  local pid="$1"
  [[ "$pid" =~ ^[0-9]+$ ]] || return 1
  TZ=UTC LC_ALL=C LANG=C ps -p "$pid" -o ppid= 2>/dev/null |
    awk 'NF { print $1; exit }' || true
}

gate_test_process_state() {
  local pid="$1"
  [[ "$pid" =~ ^[0-9]+$ ]] || return 1
  TZ=UTC LC_ALL=C LANG=C ps -p "$pid" -o stat= 2>/dev/null |
    awk 'NF { print $1; exit }' || true
}

gate_test_process_has_live_start() {
  local pid="$1"
  local expected_start="$2"
  local current_start current_state
  [[ "$pid" =~ ^[0-9]+$ && -n "$expected_start" ]] || return 1
  current_start="$(gate_test_process_start "$pid")"
  [[ -n "$current_start" && "$current_start" == "$expected_start" ]] ||
    return 1
  current_state="$(gate_test_process_state "$pid")"
  [[ -z "$current_state" || "$current_state" != Z* ]]
}

gate_test_process_identity_is_settled() {
  local pid="$1"
  local expected_start="$2"
  local current_start current_state signal_probe
  [[ "$pid" =~ ^[1-9][0-9]*$ && -n "$expected_start" ]] || return 2
  current_start="$(gate_test_process_start "$pid")"
  if [[ -n "$current_start" ]]; then
    [[ "$current_start" != "$expected_start" ]] && return 0
    current_state="$(gate_test_process_state "$pid")"
    [[ "$current_state" == Z* ]] && return 0
    [[ -n "$current_state" ]] && return 1
  fi
  signal_probe="$(node -e '
    try {
      process.kill(Number(process.argv[1]), 0);
      process.stdout.write("live");
    } catch (error) {
      process.stdout.write(error?.code === "ESRCH" ? "gone" : "unsettled");
    }
  ' "$pid" 2>/dev/null)" || return 1
  [[ "$signal_probe" == "gone" ]]
}

gate_test_wait_for_process_exit() {
  local pid="$1"
  local expected_start="$2"
  local attempts="$3"
  local attempt=0
  [[ "$pid" =~ ^[1-9][0-9]*$ && -n "$expected_start" &&
    "$attempts" =~ ^[1-9][0-9]*$ ]] || return 2
  while ! gate_test_process_identity_is_settled "$pid" "$expected_start"; do
    [[ "$attempt" -lt "$attempts" ]] || return 1
    sleep 0.05
    attempt=$((attempt + 1))
  done
}

gate_test_signal_with_current_parent() {
  local _label="$1"
  local signal="$2"
  local pid="$3"
  local expected_start="$4"
  local current_start current_parent verified_parent
  case "$signal" in
    TERM|KILL) ;;
    *) return 2 ;;
  esac
  [[ "$pid" =~ ^[1-9][0-9]*$ && "$pid" != "$$" && "$pid" != "$PPID" &&
    -n "$expected_start" ]] || return 2
  current_parent="$(gate_test_process_parent "$pid")"
  current_start="$(gate_test_process_start "$pid")"
  verified_parent="$(gate_test_process_parent "$pid")"
  [[ -n "$current_start" && "$current_start" == "$expected_start" &&
    "$current_parent" =~ ^[0-9]+$ &&
    "$current_parent" == "$verified_parent" ]] || return 2
  kill "-$signal" "$pid" 2>/dev/null || return 1
}

gate_test_stop_coordinators_in_root() {
  local label="$1"
  local lock_root="$2"
  local metadata metadata_paths metadata_record
  local coordinator_pid coordinator_start stop_failed=0
  [[ -d "$lock_root" ]] || return 0
  metadata_paths="$(
    find "$lock_root" -type f -name coordinator.json -print 2>/dev/null
  )" || {
    printf 'error: cannot enumerate %s metadata under %s.\n' \
      "$label" "$lock_root" >&2
    return 1
  }
  while IFS= read -r metadata; do
    [[ -n "$metadata" && -f "$metadata" ]] || continue
    if ! metadata_record="$(node -e '
      const value = JSON.parse(require("node:fs").readFileSync(process.argv[1], "utf8"));
      process.stdout.write([
        String(value.coordinatorIdentity?.pid ?? ""),
        value.coordinatorIdentity?.startUtc ?? "",
      ].join("\t"));
    ' "$metadata" 2>/dev/null)"; then
      printf 'error: cannot read %s metadata: %s.\n' \
        "$label" "$metadata" >&2
      stop_failed=1
      continue
    fi
    IFS=$'\t' read -r coordinator_pid coordinator_start <<< "$metadata_record"
    if [[ ! "$coordinator_pid" =~ ^[1-9][0-9]*$ ||
      -z "$coordinator_start" ]]; then
      printf 'error: %s metadata has no exact process identity: %s.\n' \
        "$label" "$metadata" >&2
      stop_failed=1
      continue
    fi
    if ! gate_test_process_has_live_start \
      "$coordinator_pid" "$coordinator_start"; then
      if gate_test_process_identity_is_settled \
        "$coordinator_pid" "$coordinator_start"; then
        continue
      fi
    fi
    gate_test_signal_with_current_parent "$label" TERM \
      "$coordinator_pid" "$coordinator_start" || true
    if gate_test_wait_for_process_exit \
      "$coordinator_pid" "$coordinator_start" 200; then
      continue
    fi
    gate_test_signal_with_current_parent "$label" KILL \
      "$coordinator_pid" "$coordinator_start" || true
    if ! gate_test_wait_for_process_exit \
      "$coordinator_pid" "$coordinator_start" 100; then
      printf 'error: %s %s did not stop after TERM and KILL.\n' \
        "$label" "$coordinator_pid" >&2
      stop_failed=1
    fi
  done <<< "$metadata_paths"
  [[ "$stop_failed" -eq 0 ]]
}

# The debug formatter mirrors the active stamp instead of maintaining a
# second field list. Cover both current schemas without starting a gate.
stamp_debug_function="$(mktemp)"
stamp_debug_stdout="$(mktemp)"
stamp_debug_stderr="$(mktemp)"
if ! node --input-type=module - \
  "$repo_root/scripts/agent-quality-gate.sh" \
  "$repo_root/scripts/sentry/ci-wiring/check-sentry-suites-in-ci-gate-extract.mjs" \
  > "$stamp_debug_function" <<'NODE'
import { readFileSync } from "node:fs";
import { pathToFileURL } from "node:url";

const [gatePath, extractorPath] = process.argv.slice(2);
const { bashFunctionSource } = await import(pathToFileURL(extractorPath).href);
process.stdout.write(
  bashFunctionSource(
    readFileSync(gatePath, "utf8"),
    "gate_print_freshness_stamp_debug",
    gatePath,
  ),
);
NODE
then
  rm -f "$stamp_debug_function" "$stamp_debug_stdout" "$stamp_debug_stderr"
  fail "could not extract the freshness-stamp debug formatter"
fi
if ! /bin/bash -c '
  set -euo pipefail
  source "$1"
  gate_print_freshness_stamp_debug "$2"
  gate_print_freshness_stamp_debug "$3"
' stamp-debug "$stamp_debug_function" \
  $'v3\tbase=base\tpaths=paths\tplan=plan\timplementation=implementation\tcontent=content\tpackageRisk=false\tallowPackageScripts=n/a\tscrubPolicy=scrub' \
  $'v4\tbase=base\tpaths=paths\tplan=plan\timplementation=implementation\tcontent=content\tpackageRisk=false\tallowPackageScripts=n/a\tscrubPolicy=scrub\tcoordinatorContext=context' \
  > "$stamp_debug_stdout" 2> "$stamp_debug_stderr"; then
  rm -f "$stamp_debug_function" "$stamp_debug_stdout" "$stamp_debug_stderr"
  fail "freshness-stamp debug formatter rejected a current schema"
fi
[[ ! -s "$stamp_debug_stdout" ]] ||
  fail "freshness-stamp debug formatter wrote to stdout"
[[ "$(grep -c '^agent-quality-gate stamp ' "$stamp_debug_stderr")" == "19" ]] ||
  fail "freshness-stamp debug formatter did not mirror both current schemas"
grep -Fxq 'agent-quality-gate stamp schema=v3' "$stamp_debug_stderr" ||
  fail "freshness-stamp debug formatter omitted the v3 schema"
grep -Fxq 'agent-quality-gate stamp schema=v4' "$stamp_debug_stderr" ||
  fail "freshness-stamp debug formatter omitted the v4 schema"
[[ "$(grep -c '^agent-quality-gate stamp coordinatorContext=' "$stamp_debug_stderr")" == "1" ]] ||
  fail "freshness-stamp debug formatter did not preserve the v4-only field"
: > "$stamp_debug_stdout"
: > "$stamp_debug_stderr"
if /bin/bash -c '
  set -euo pipefail
  source "$1"
  gate_print_freshness_stamp_debug "$2"
' stamp-debug-invalid "$stamp_debug_function" \
  $'v4\tbase=base\tbroken-field\tcontent=content' \
  > "$stamp_debug_stdout" 2> "$stamp_debug_stderr"; then
  rm -f "$stamp_debug_function" "$stamp_debug_stdout" "$stamp_debug_stderr"
  fail "freshness-stamp debug formatter accepted a malformed field"
fi
[[ ! -s "$stamp_debug_stdout" && ! -s "$stamp_debug_stderr" ]] ||
  fail "freshness-stamp debug formatter emitted a partial malformed record"
rm -f "$stamp_debug_function" "$stamp_debug_stdout" "$stamp_debug_stderr"
unset stamp_debug_function stamp_debug_stderr stamp_debug_stdout

# Both freshness callers place the recomputation inside an assignment followed
# by `||`. Bash therefore disables implicit errexit inside the substituted
# function. Extract the production function and make every load-bearing probe
# return bytes before failure. Each explicit guard must still reach the caller's
# failure branch with inherit_errexit both disabled and enabled when supported.
recomputed_stamp_function="$(mktemp)"
recomputed_stamp_scratch="$(mktemp -d)"
if ! node --input-type=module - \
  "$repo_root/scripts/agent-quality-gate.sh" \
  "$repo_root/scripts/sentry/ci-wiring/check-sentry-suites-in-ci-gate-extract.mjs" \
  > "$recomputed_stamp_function" <<'NODE'
import { readFileSync } from "node:fs";
import { pathToFileURL } from "node:url";

const [gatePath, extractorPath] = process.argv.slice(2);
const { bashFunctionSource } = await import(pathToFileURL(extractorPath).href);
process.stdout.write(
  bashFunctionSource(
    readFileSync(gatePath, "utf8"),
    "recomputed_stamp_line",
    gatePath,
  ),
);
NODE
then
  rm -f "$recomputed_stamp_function"
  rm -rf "$recomputed_stamp_scratch"
  fail "could not extract recomputed_stamp_line for failure propagation tests"
fi
recomputed_stamp_inherit_modes=(off)
if /bin/bash -c 'shopt -s inherit_errexit' 2>/dev/null; then
  recomputed_stamp_inherit_modes+=(on)
fi
for recomputed_stamp_inherit_mode in "${recomputed_stamp_inherit_modes[@]}"; do
  for recomputed_stamp_caller in initial post-wait; do
    for recomputed_stamp_failure in \
      write-plan ref-oid base-binding hash-paths hash-plan implementation \
      content coordinator-context; do
      if ! /bin/bash -c '
        set -euo pipefail
        inherit_mode="$1"
        function_source="$2"
        scratch_dir="$3"
        caller="$4"
        failure_mode="$5"
        if [[ "$inherit_mode" == on ]]; then
          shopt -s inherit_errexit
          shopt -q inherit_errexit
        else
          shopt -u inherit_errexit 2>/dev/null || true
        fi
        source "$function_source"
        base_ref=HEAD
        gate_coordinator_freshness_context=fixture-context
        package_script_risk_changed=false
        stamp_allow_package_scripts=n/a
        gate_mapped_child_scrub_policy_hash="$(printf "%064d" 0)"
        collect_current_changed_paths() {
          printf "fixture.txt\n"
        }
        write_command_plan() {
          printf "fixture plan\n" > "$1"
          [[ "$failure_mode" != write-plan ]] || return 91
        }
        ref_oid() {
          printf "%040d\n" 1
          [[ "$failure_mode" != ref-oid ]] || return 91
        }
        gate_stamp_base_binding() {
          printf "merge-base:%040d\n" 6
          [[ "$failure_mode" != base-binding ]] || return 91
        }
        hash_file() {
          local probe
          case "$1" in
            *fresh-paths.*) probe=hash-paths ;;
            *fresh-plan.*) probe=hash-plan ;;
            *) return 98 ;;
          esac
          printf "%064d\n" 2
          [[ "$failure_mode" != "$probe" ]] || return 91
        }
        implementation_hash_value() {
          printf "%064d\n" 3
          [[ "$failure_mode" != implementation ]] || return 91
        }
        validation_content_signature() {
          printf "%064d\n" 4
          [[ "$failure_mode" != content ]] || return 91
        }
        gate_coordinator_freshness_context_hash() {
          printf "%064d\n" 5
          [[ "$failure_mode" != coordinator-context ]] || return 91
        }
        caller_failure_seen=0
        case "$caller" in
          initial)
            verified_freshness_stamp="$(recomputed_stamp_line)" ||
              caller_failure_seen=1
            ;;
          post-wait)
            post_wait_stamp="$(recomputed_stamp_line)" ||
              caller_failure_seen=1
            ;;
          *) exit 99 ;;
        esac
        [[ "$caller_failure_seen" -eq 1 ]]
      ' recomputed-stamp-failure \
        "$recomputed_stamp_inherit_mode" \
        "$recomputed_stamp_function" \
        "$recomputed_stamp_scratch" \
        "$recomputed_stamp_caller" \
        "$recomputed_stamp_failure"; then
        rm -f "$recomputed_stamp_function"
        rm -rf "$recomputed_stamp_scratch"
        fail "${recomputed_stamp_caller}/${recomputed_stamp_inherit_mode}: ${recomputed_stamp_failure} was masked during freshness recomputation"
      fi
    done
  done
done
rm -f "$recomputed_stamp_function"
rm -rf "$recomputed_stamp_scratch"
unset recomputed_stamp_caller recomputed_stamp_failure
unset recomputed_stamp_function recomputed_stamp_inherit_mode
unset recomputed_stamp_inherit_modes recomputed_stamp_scratch

fresh_stamp_repo="$(mktemp -d)"
(
  cd "$fresh_stamp_repo"
  git init -q
  git config user.email test@example.invalid
  git config user.name "Quality Gate Test"
  printf 'fixture\n' > fixture.txt
  mkdir -p tools
  cat > tools/trunk <<'STUB'
#!/usr/bin/env bash
if [[ "${1:-} ${2:-}" == "daemon status" ]]; then
  echo "✖ Daemon stopped"
  exit 1
fi
counter_file="${COUNTER_FILE:?}"
count=0
if [[ -f "$counter_file" ]]; then
  count="$(cat "$counter_file")"
fi
count=$((count + 1))
printf '%s\n' "$count" > "$counter_file"
STUB
  chmod +x tools/trunk
  git add .
  git commit -qm init
  git config agent.qualityGate.cloudPrePushRequireFresh true
  base_ref="$(git rev-parse --verify HEAD)"
  printf 'changed\n' >> fixture.txt
  # Warm WITH --allow-package-script-changes; the skip run below passes NO such
  # flag (like the pre-push hook). With no package-script risk they must still
  # share a freshness stamp, so the flag-less run skips (allowPackageScripts is
  # folded out of the stamp when packageRisk is false).
  COUNTER_FILE="$fresh_stamp_repo/.tmp/agent-quality-gate/trunk-count" \
    "$repo_root/scripts/agent-quality-gate.sh" \
      --base "$base_ref" --run --parallel 3 --allow-package-script-changes \
      > "$output_file" 2>&1
  git add fixture.txt
  git commit -qm "commit validated content"
  stamp_file="$fresh_stamp_repo/.tmp/agent-quality-gate/last-success.stamp"
  stamp_value="$(sed -n '2s/^stamp=//p' "$stamp_file")"
  printf 'created_at=%s\nstamp=%s\n' \
    "$(( $(date +%s) - 60 * 60 ))" \
    "$stamp_value" \
    > "$stamp_file"
  : > "$output_file"
  COUNTER_FILE="$fresh_stamp_repo/.tmp/agent-quality-gate/trunk-count" \
    "$repo_root/scripts/agent-quality-gate.sh" \
      --base "$base_ref" --run --parallel 3 --skip-if-fresh --pre-push \
      > "$output_file" 2>&1
  [[ "$(cat "$fresh_stamp_repo/.tmp/agent-quality-gate/trunk-count")" == "1" ]] ||
    fail "warm hosted pre-push executed a mapped command"
  grep -Fq -- "Previous successful agent quality gate run is still fresh; skipping mapped commands." "$output_file" ||
    fail "warm hosted pre-push did not report a freshness skip"

  printf 'created_at=%s\nstamp=%s\n' \
    "$(( $(date +%s) - 2 * 60 * 60 - 1 ))" \
    "$stamp_value" \
    > "$stamp_file"
  : > "$output_file"
  cold_pre_push_exit=0
  COUNTER_FILE="$fresh_stamp_repo/.tmp/agent-quality-gate/trunk-count" \
    "$repo_root/scripts/agent-quality-gate.sh" \
      --base "$base_ref" --run --parallel 3 --skip-if-fresh --pre-push \
      > "$output_file" 2>&1 || cold_pre_push_exit=$?
  [[ "$cold_pre_push_exit" -eq 2 ]] ||
    fail "cold hosted pre-push exited ${cold_pre_push_exit} instead of 2"
  [[ "$(cat "$fresh_stamp_repo/.tmp/agent-quality-gate/trunk-count")" == "1" ]] ||
    fail "cold hosted pre-push executed a mapped command"
  grep -Fq -- "Hosted pre-push requires a fresh quality-gate stamp; no mapped command ran." "$output_file" ||
    fail "cold hosted pre-push did not explain its refusal"

  printf '{"name":"quality-gate-fixture","private":true}\n' > package.json
  git add package.json
  git commit -qm "add package-risk fixture"
  : > "$output_file"
  hosted_package_risk_exit=0
  COUNTER_FILE="$fresh_stamp_repo/.tmp/agent-quality-gate/trunk-count" \
    "$repo_root/scripts/agent-quality-gate.sh" \
      --base "$base_ref" --run --parallel 3 \
      > "$output_file" 2>&1 || hosted_package_risk_exit=$?
  [[ "$hosted_package_risk_exit" -eq 2 ]] ||
    fail "cold hosted package-risk run exited ${hosted_package_risk_exit} instead of 2"
  grep -Fq -- "git config agent.qualityGate.allowPackageScriptChanges true" "$output_file" ||
    fail "cold hosted package-risk run did not explain the reusable acknowledgement"

  git config --unset agent.qualityGate.cloudPrePushRequireFresh
  : > "$output_file"
  local_pre_push_exit=0
  COUNTER_FILE="$fresh_stamp_repo/.tmp/agent-quality-gate/trunk-count" \
    "$repo_root/scripts/agent-quality-gate.sh" \
      --base "$base_ref" --run --parallel 3 --skip-if-fresh --pre-push \
      > "$output_file" 2>&1 || local_pre_push_exit=$?
  [[ "$local_pre_push_exit" -eq 2 ]] ||
    fail "cold local pre-push exited ${local_pre_push_exit} instead of 2"
  [[ "$(cat "$fresh_stamp_repo/.tmp/agent-quality-gate/trunk-count")" == "1" ]] ||
    fail "cold local pre-push executed a mapped command before package-risk refusal"
  grep -Fq -- "Refusing to run because package manifests, patches, or lockfile changed." "$output_file" ||
    fail "cold local pre-push did not reach the normal package-risk refusal"
  if grep -Fq -- "Hosted pre-push requires a fresh quality-gate stamp" "$output_file"; then
    fail "cold local pre-push used the hosted refusal"
  fi
)
rm -rf "$fresh_stamp_repo"
assert_not_contains "Previous successful agent quality gate run is still fresh; skipping mapped commands."

# Coordinated fast-path reuse binds every execution input except HEAD. The HEAD
# exception preserves warm-then-push when a commit records the same validated
# bytes. Exact repeats and that commit-only transition skip; a material
# environment or tool-version change must execute the mapped command again.
coordinated_fresh_stamp_repo="$(mktemp -d)"
coordinated_fresh_stamp_lock="$(mktemp -d /tmp/qgf.XXXXXX)"
coordinated_fresh_tool_version="$(mktemp /tmp/qgv.XXXXXX)"
(
  cd "$coordinated_fresh_stamp_repo"
  git init -q
  git config user.email test@example.invalid
  git config user.name "Quality Gate Test"
  printf 'fixture\n' > fixture.txt
  mkdir -p bin tools
  cat > tools/trunk <<'STUB'
#!/usr/bin/env bash
if [[ "${1:-} ${2:-}" == "daemon status" ]]; then
  echo "✖ Daemon stopped"
  exit 1
fi
counter_file="${COUNTER_FILE:?}"
count=0
if [[ -f "$counter_file" ]]; then
  count="$(cat "$counter_file")"
fi
printf '%s\n' "$((count + 1))" > "$counter_file"
STUB
  cat > bin/pnpm <<'STUB'
#!/usr/bin/env bash
if [[ "${1:-}" == "--version" ]]; then
  cat "${QG_TOOL_VERSION_FILE:?}"
  exit 0
fi
exit 0
STUB
  chmod +x bin/pnpm tools/trunk
  write_installed_dependency_fixture "$PWD"
  git add .
  git commit -qm init
  base_ref="$(git rev-parse --verify HEAD)"
  printf 'changed\n' >> fixture.txt
  printf '9.0.0\n' > "$coordinated_fresh_tool_version"
  counter="$coordinated_fresh_stamp_repo/.tmp/agent-quality-gate/trunk-count"
  stamp_file="$coordinated_fresh_stamp_repo/.tmp/agent-quality-gate/last-success.stamp"

  cleanup_coordinated_fresh_stamp_fixture() {
    gate_test_stop_coordinators_in_root \
      "fresh-stamp fixture coordinator" "$coordinated_fresh_stamp_lock"
  }
  trap cleanup_coordinated_fresh_stamp_fixture EXIT

  coordinated_fresh_gate() {
    local rustflags="$1"
    shift
    AGENT_QUALITY_GATE_LOCK=1 \
      AGENT_QUALITY_GATE_LOCK_HELD='' \
      AGENT_QUALITY_GATE_LOCK_DIR="$coordinated_fresh_stamp_lock" \
      AGENT_QUALITY_GATE_COORDINATOR=1 \
      AGENT_QUALITY_GATE_CAPACITY=3 \
      COUNTER_FILE="$counter" \
      QG_TOOL_VERSION_FILE="$coordinated_fresh_tool_version" \
      RUSTFLAGS="$rustflags" \
      PATH="$coordinated_fresh_stamp_repo/bin:$PATH" \
      "$repo_root/scripts/agent-quality-gate.sh" \
        --base "$base_ref" --run --lock-wait 30 "$@" \
        > "$output_file" 2>&1
  }

  coordinated_fresh_gate '-C debuginfo=0'
  grep -q '^stamp=v4.*scrubPolicy=[a-f0-9]\{64\}.*coordinatorContext=[a-f0-9]\{64\}$' \
    "$stamp_file" ||
    fail "coordinated success did not write the strengthened freshness stamp"
  grep -q '^execution_fingerprint=[a-f0-9]\{64\}$' \
    "$stamp_file" ||
    fail "coordinated success did not record its exact execution fingerprint"
  grep -q '^execution_head=[a-f0-9]\{40\}\([a-f0-9]\{24\}\)\?$' \
    "$stamp_file" ||
    fail "coordinated success did not record its exact execution HEAD"

  coordinated_fresh_gate '-C debuginfo=0' --skip-if-fresh
  [[ "$(cat "$counter")" == "1" ]] ||
    fail "an exact coordinated repeat did not reuse its fresh success"
  grep -Fq -- "Previous successful agent quality gate run is still fresh; skipping mapped commands." \
    "$output_file" ||
    fail "an exact coordinated repeat did not report its freshness skip"
  if grep -q '^agent-quality-gate stamp ' "$output_file"; then
    fail "freshness-stamp debug output was enabled by default"
  fi

  cp "$stamp_file" "${stamp_file}.before-debug"
  debug_stdout="${output_file}.debug.stdout"
  debug_stderr="${output_file}.debug.stderr"
  AGENT_QUALITY_GATE_DEBUG_STAMP=1 \
    AGENT_QUALITY_GATE_LOCK=1 \
    AGENT_QUALITY_GATE_LOCK_HELD='' \
    AGENT_QUALITY_GATE_LOCK_DIR="$coordinated_fresh_stamp_lock" \
    AGENT_QUALITY_GATE_COORDINATOR=1 \
    AGENT_QUALITY_GATE_CAPACITY=3 \
    COUNTER_FILE="$counter" \
    QG_TOOL_VERSION_FILE="$coordinated_fresh_tool_version" \
    RUSTFLAGS='-C debuginfo=0' \
    PATH="$coordinated_fresh_stamp_repo/bin:$PATH" \
    "$repo_root/scripts/agent-quality-gate.sh" \
      --base "$base_ref" --run --lock-wait 30 --skip-if-fresh \
      > "$debug_stdout" 2> "$debug_stderr"
  [[ "$(cat "$counter")" == "1" ]] ||
    fail "enabling freshness-stamp debug output invalidated exact reuse"
  cmp -s "$stamp_file" "${stamp_file}.before-debug" ||
    fail "enabling freshness-stamp debug output changed the durable stamp"
  grep -Fq -- "Previous successful agent quality gate run is still fresh; skipping mapped commands." \
    "$debug_stdout" ||
    fail "the debug run did not preserve the normal freshness result on stdout"
  if grep -q '^agent-quality-gate stamp ' "$debug_stdout"; then
    fail "freshness-stamp debug output leaked onto stdout"
  fi
  [[ "$(grep -c '^agent-quality-gate stamp ' "$debug_stderr")" == "10" ]] ||
    fail "coordinated freshness debug output did not report the complete v4 schema"
  for field in schema base paths plan implementation content packageRisk \
    allowPackageScripts scrubPolicy coordinatorContext; do
    grep -q "^agent-quality-gate stamp ${field}=" "$debug_stderr" ||
      fail "coordinated freshness debug output omitted ${field}"
  done
  grep -Fxq 'agent-quality-gate stamp schema=v4' "$debug_stderr" ||
    fail "coordinated freshness debug output reported the wrong schema"
  rm -f "$debug_stdout" "$debug_stderr" "${stamp_file}.before-debug"

  grep -q '^execution_base_tip=[a-f0-9]\{40\}\([a-f0-9]\{24\}\)\?$' \
    "$stamp_file" ||
    fail "coordinated success did not record its exact base tip"

  cp "$stamp_file" "${stamp_file}.valid"
  # Keep every line the reader validates except the fingerprint itself. Dropping
  # the recorded base tip would make the stamp unreadable and the gate would
  # re-run for that reason instead of the mismatch this case is testing.
  {
    sed -n '1,2p' "${stamp_file}.valid"
    printf 'execution_fingerprint=%064d\n' 0
    sed -n '4,5p' "${stamp_file}.valid"
  } > "$stamp_file"
  coordinated_fresh_gate '-C debuginfo=0' --skip-if-fresh
  if grep -Fq -- "Previous successful agent quality gate run is still fresh; skipping mapped commands." \
    "$output_file"; then
    fail "a mismatched exact fingerprint was accepted for an unchanged HEAD"
  fi
  grep -Fq -- "Shared coordinator execution passed; no mapped command ran in this request." \
    "$output_file" ||
    fail "an unchanged-HEAD fingerprint mismatch did not fall through to exact retained-result reuse"
  [[ "$(cat "$counter")" == "1" ]] ||
    fail "exact retained-result reuse re-executed the mapped command"
  mv "${stamp_file}.valid" "$stamp_file"

  git add fixture.txt
  git commit -qm "commit validated content"
  coordinated_fresh_gate '-C debuginfo=0' --skip-if-fresh
  [[ "$(cat "$counter")" == "1" ]] ||
    fail "committing identical validated bytes invalidated coordinated warm-then-push reuse"

  coordinated_fresh_gate '-C debuginfo=1' --skip-if-fresh
  [[ "$(cat "$counter")" == "2" ]] ||
    fail "a material environment change reused the coordinated freshness stamp"
  if grep -Fq -- "Previous successful agent quality gate run is still fresh; skipping mapped commands." \
    "$output_file"; then
    fail "a material environment change reported a coordinated freshness skip"
  fi

  printf '9.0.1\n' > "$coordinated_fresh_tool_version"
  coordinated_fresh_gate '-C debuginfo=1' --skip-if-fresh
  [[ "$(cat "$counter")" == "3" ]] ||
    fail "a pnpm version change reused the coordinated freshness stamp"

  cleanup_coordinated_fresh_stamp_fixture
  for _ in {1..100}; do
    [[ ! -e "$coordinated_fresh_stamp_lock/run.lock" ]] && break
    sleep 0.05
  done
  [[ ! -e "$coordinated_fresh_stamp_lock/run.lock" ]] ||
    fail "coordinated freshness fixture did not release its legacy lock"
  trap - EXIT
)
rm -rf "$coordinated_fresh_stamp_repo" "$coordinated_fresh_stamp_lock"
rm -f "$coordinated_fresh_tool_version"

# The stamp binds the MERGE-BASE of the base ref and the head, not the base
# ref's tip. `origin/main` advances many times a day, and under tip binding
# every advance invalidated every warm stamp on the machine even when the
# branch's own bytes and its merge-base had not moved. The base ref here is a
# NAME whose tip is advanced underneath it, exactly as `git fetch origin main`
# does in the pre-push hook, so the command plan stays byte-identical and the
# base binding is the only input under test. HEAD is unchanged across the
# advance, which is the path where the coordinator's exact-fingerprint check
# would otherwise re-impose tip binding on its own.
mergebase_stamp_repo="$(mktemp -d)"
mergebase_stamp_lock="$(mktemp -d /tmp/qgm.XXXXXX)"
(
  cd "$mergebase_stamp_repo"
  git init -q
  git config user.email test@example.invalid
  git config user.name "Quality Gate Test"
  printf 'fixture\n' > fixture.txt
  mkdir -p bin tools
  # `scripts/gate/trunk-check-once.sh` asks the launcher for its daemon state
  # before it runs the check and refuses to classify an unrecognized answer, so
  # a stub that treats `daemon status` as a check never reaches the check at
  # all. The branch returns before the counter, so every count below keeps its
  # meaning.
  cat > tools/trunk <<'STUB'
#!/usr/bin/env bash
if [[ "${1:-} ${2:-}" == "daemon status" ]]; then
  echo "✖ Daemon stopped"
  exit 1
fi
counter_file="${COUNTER_FILE:?}"
count=0
if [[ -f "$counter_file" ]]; then
  count="$(cat "$counter_file")"
fi
printf '%s\n' "$((count + 1))" > "$counter_file"
STUB
  cat > bin/pnpm <<'STUB'
#!/usr/bin/env bash
exit 0
STUB
  chmod +x bin/pnpm tools/trunk
  write_installed_dependency_fixture "$PWD"
  git add .
  git commit -qm init
  mergebase_one="$(git rev-parse --verify HEAD)"
  git update-ref refs/remotes/origin/main "$mergebase_one"
  printf 'changed\n' >> fixture.txt
  counter="$mergebase_stamp_repo/.tmp/agent-quality-gate/trunk-count"
  stamp_file="$mergebase_stamp_repo/.tmp/agent-quality-gate/last-success.stamp"

  cleanup_mergebase_stamp_fixture() {
    gate_test_stop_coordinators_in_root \
      "merge-base stamp fixture coordinator" "$mergebase_stamp_lock"
  }
  trap cleanup_mergebase_stamp_fixture EXIT

  mergebase_gate() {
    AGENT_QUALITY_GATE_LOCK=1 \
      AGENT_QUALITY_GATE_LOCK_HELD='' \
      AGENT_QUALITY_GATE_LOCK_DIR="$mergebase_stamp_lock" \
      AGENT_QUALITY_GATE_COORDINATOR=1 \
      AGENT_QUALITY_GATE_CAPACITY=3 \
      COUNTER_FILE="$counter" \
      PATH="$mergebase_stamp_repo/bin:$PATH" \
      "$repo_root/scripts/agent-quality-gate.sh" \
        --base origin/main --run --lock-wait 30 "$@" \
        > "$output_file" 2>&1
  }

  mergebase_gate
  grep -q '^stamp=v4.*base=merge-base:[a-f0-9]\{40\}' "$stamp_file" ||
    fail "a plan that cannot observe the base tip did not bind the merge-base"
  grep -Fq "execution_base_tip=${mergebase_one}" "$stamp_file" ||
    fail "the stamp did not record the base tip it was warmed against"

  # Negative control: without moving anything, the fixture must already be able
  # to reuse. An exact repeat that re-executed would make every counter check
  # below meaningless.
  mergebase_gate --skip-if-fresh
  [[ "$(cat "$counter")" == "1" ]] ||
    fail "an exact repeat did not reuse the merge-base fixture's fresh success"

  # Advance the base tip onto a same-tree child. The merge-base with HEAD stays
  # at the original commit, so the warm stamp must survive.
  mergebase_two="$(git commit-tree \
    "$(git rev-parse --verify "${mergebase_one}^{tree}")" \
    -p "$mergebase_one" -m "base advance")"
  git update-ref refs/remotes/origin/main "$mergebase_two"
  [[ "$(git merge-base origin/main HEAD)" == "$mergebase_one" ]] ||
    fail "the base advance fixture moved the merge-base it meant to hold still"
  mergebase_gate --skip-if-fresh
  [[ "$(cat "$counter")" == "1" ]] ||
    fail "a base-tip advance that left the merge-base alone busted the stamp"
  grep -Fq -- "Previous successful agent quality gate run is still fresh; skipping mapped commands." \
    "$output_file" ||
    fail "a merge-base-preserving base advance did not report its freshness skip"

  # Rebasing onto the advanced base moves the merge-base itself. The same
  # validated bytes are no longer validated against the same history, so the
  # stamp must not survive it.
  git reset -q --hard "$mergebase_two"
  printf 'changed\n' >> fixture.txt
  [[ "$(git merge-base origin/main HEAD)" == "$mergebase_two" ]] ||
    fail "the rebase fixture did not move the merge-base"
  mergebase_gate --skip-if-fresh
  [[ "$(cat "$counter")" == "2" ]] ||
    fail "a stamp warmed before a rebase was reused after the merge-base moved"
  if grep -Fq -- "Previous successful agent quality gate run is still fresh; skipping mapped commands." \
    "$output_file"; then
    fail "a moved merge-base reported a freshness skip"
  fi

  cleanup_mergebase_stamp_fixture
  for _ in {1..100}; do
    [[ ! -e "$mergebase_stamp_lock/run.lock" ]] && break
    sleep 0.05
  done
  trap - EXIT
)
rm -rf "$mergebase_stamp_repo" "$mergebase_stamp_lock"

# A command plan that can OBSERVE the base tip keeps tip binding. Workflow
# changes add the ADR reminder, which receives `--base <ref>` and resolves that
# ref when it runs, so its answer moves with the tip while its command text does
# not. The base ref is a name here for exactly that reason: the plan hash is
# byte-identical across the advance, so only the binding predicate can bust the
# stamp. `react-doctor:diff` is the other tip reader and bakes the resolved base
# OID into its Turbo cache key; `scripts/gate/mapping/engine.test.mjs` covers
# that its command text moves with the OID.
tipbound_stamp_repo="$(mktemp -d)"
(
  cd "$tipbound_stamp_repo"
  git init -q
  git config user.email test@example.invalid
  git config user.name "Quality Gate Test"
  mkdir -p .github/workflows bin tools
  printf 'name: Metrics Bridge\n' > .github/workflows/metrics-bridge.yml
  cat > tools/trunk <<'STUB'
#!/usr/bin/env bash
if [[ "${1:-} ${2:-}" == "daemon status" ]]; then
  echo "✖ Daemon stopped"
  exit 1
fi
counter_file="${COUNTER_FILE:?}"
count=0
if [[ -f "$counter_file" ]]; then
  count="$(cat "$counter_file")"
fi
printf '%s\n' "$((count + 1))" > "$counter_file"
STUB
  # The stub makes mapped commands free. It must still delegate every inline
  # Node helper and gate module used to build and execute the plan. `-p`
  # carries the Darwin broker's `node -p 'process.execPath'` runtime probe:
  # stub it out and the broker reads an empty runtime path and refuses to bind
  # before first dispatch.
  cat > bin/node <<'STUB'
#!/usr/bin/env bash
if [[ "${1:-}" == "--input-type=module" ||
  "${1:-}" == -e ||
  "${1:-}" == -p ||
  "${1:-}" == */quality-gate-coordinator.mjs ||
  "${1:-}" == */quality-gate-coordinator-environment.mjs ]]; then
  exec "${REAL_NODE:?}" "$@"
fi
case "${1:-}" in
  *"/scripts/gate/mapping.mjs") exec "${REAL_NODE:?}" "$@" ;;
esac
exit 0
STUB
  cat > bin/pnpm <<'STUB'
#!/usr/bin/env bash
exit 0
STUB
  chmod +x bin/node bin/pnpm tools/trunk
  git add .
  git commit -qm init
  tipbound_one="$(git rev-parse --verify HEAD)"
  git update-ref refs/remotes/origin/main "$tipbound_one"
  printf '# changed\n' >> .github/workflows/metrics-bridge.yml
  counter="$tipbound_stamp_repo/.tmp/agent-quality-gate/trunk-count"
  stamp_file="$tipbound_stamp_repo/.tmp/agent-quality-gate/last-success.stamp"

  tipbound_gate() {
    REAL_NODE="$(command -v node)" \
      AGENT_QUALITY_GATE_COORDINATOR=0 \
      COUNTER_FILE="$counter" \
      PATH="$tipbound_stamp_repo/bin:$PATH" \
      "$repo_root/scripts/agent-quality-gate.sh" \
        --base origin/main --run "$@" \
        > "$output_file" 2>&1
  }

  tipbound_gate
  grep -Fq -- "check-adr-reminder.mjs" "$output_file" ||
    fail "the tip-binding fixture did not schedule a base-reading command"
  grep -q '^stamp=v3.*base=tip:[a-f0-9]\{40\}' "$stamp_file" ||
    fail "a plan that reads the base tip did not keep tip binding"

  # Negative control: the plan's randomized changed-paths scratch path is
  # normalized out, so an exact repeat must reuse. Without this the counter
  # check below could pass on a fixture that can never reuse at all.
  tipbound_gate --skip-if-fresh
  [[ "$(cat "$counter")" == "1" ]] ||
    fail "an exact repeat did not reuse the tip-binding fixture's fresh success"

  tipbound_two="$(git commit-tree \
    "$(git rev-parse --verify "${tipbound_one}^{tree}")" \
    -p "$tipbound_one" -m "base advance")"
  git update-ref refs/remotes/origin/main "$tipbound_two"
  [[ "$(git merge-base origin/main HEAD)" == "$tipbound_one" ]] ||
    fail "the tip-binding fixture moved the merge-base it meant to hold still"
  tipbound_gate --skip-if-fresh
  [[ "$(cat "$counter")" == "2" ]] ||
    fail "a plan that reads the base tip reused its stamp across a tip advance"
)
rm -rf "$tipbound_stamp_repo"

# The plan carries the `printf %q` SPELLING of the base, not its raw text, so a
# base ref that needs escaping is not the string the predicate searches for.
# Git permits `'` in a ref name, and `origin/qu'ote` reaches the plan as
# `origin/qu\'ote`. Before the predicate quoted its needles, the ADR reminder
# below was invisible to it and this plan bound the merge-base while reading
# the tip.
quoteref_stamp_repo="$(mktemp -d)"
(
  cd "$quoteref_stamp_repo"
  git init -q
  git config user.email test@example.invalid
  git config user.name "Quality Gate Test"
  mkdir -p .github/workflows bin tools
  printf 'name: Metrics Bridge\n' > .github/workflows/metrics-bridge.yml
  cat > tools/trunk <<'STUB'
#!/usr/bin/env bash
if [[ "${1:-} ${2:-}" == "daemon status" ]]; then
  echo "✖ Daemon stopped"
  exit 1
fi
counter_file="${COUNTER_FILE:?}"
count=0
if [[ -f "$counter_file" ]]; then
  count="$(cat "$counter_file")"
fi
printf '%s\n' "$((count + 1))" > "$counter_file"
STUB
  cat > bin/node <<'STUB'
#!/usr/bin/env bash
if [[ "${1:-}" == "--input-type=module" ||
  "${1:-}" == -e ||
  "${1:-}" == -p ||
  "${1:-}" == */quality-gate-coordinator.mjs ||
  "${1:-}" == */quality-gate-coordinator-environment.mjs ]]; then
  exec "${REAL_NODE:?}" "$@"
fi
case "${1:-}" in
  *"/scripts/gate/mapping.mjs") exec "${REAL_NODE:?}" "$@" ;;
esac
exit 0
STUB
  cat > bin/pnpm <<'STUB'
#!/usr/bin/env bash
exit 0
STUB
  chmod +x bin/node bin/pnpm tools/trunk
  git add .
  git commit -qm init
  quoteref_one="$(git rev-parse --verify HEAD)"
  # A ref name git accepts and `printf %q` must escape.
  quoteref_name="origin/qu'ote"
  git update-ref "refs/remotes/$quoteref_name" "$quoteref_one"
  printf '# changed\n' >> .github/workflows/metrics-bridge.yml
  counter="$quoteref_stamp_repo/.tmp/agent-quality-gate/trunk-count"
  stamp_file="$quoteref_stamp_repo/.tmp/agent-quality-gate/last-success.stamp"

  quoteref_gate() {
    REAL_NODE="$(command -v node)" \
      AGENT_QUALITY_GATE_COORDINATOR=0 \
      COUNTER_FILE="$counter" \
      PATH="$quoteref_stamp_repo/bin:$PATH" \
      "$repo_root/scripts/agent-quality-gate.sh" \
        --base "$quoteref_name" --run "$@" \
        > "$output_file" 2>&1
  }

  quoteref_gate
  # The escaped spelling is written out rather than recomputed, so a change in
  # how the base is quoted fails here instead of passing vacuously.
  grep -Fq -- "--base origin/qu\\'ote --head HEAD" "$output_file" ||
    fail "the quoted-ref fixture did not emit the %q spelling it means to test"
  grep -q '^stamp=v3.*base=tip:[a-f0-9]\{40\}' "$stamp_file" ||
    fail "a base ref needing shell escaping did not keep tip binding"

  # Negative control: the fixture must be able to reuse before the advance.
  quoteref_gate --skip-if-fresh
  [[ "$(cat "$counter")" == "1" ]] ||
    fail "an exact repeat did not reuse the quoted-ref fixture's fresh success"

  quoteref_two="$(git commit-tree \
