run_gate "scripts/gate/mapping/post-passes.mjs"
assert_contains "- pnpm code-health:deps"
run_gate "pnpm-lock.yaml"
assert_contains "- pnpm code-health:deps"

# Any path inside a scanned root keeps the command, whatever its file type.
