  retained_state="$darwin_retry_fixture/lineage.fixture-worker-1.json"
  printf 'retained exact lineage evidence\n' > "$retained_state"
  # shellcheck disable=SC2329 # Called by the extracted settlement functions.
  gate_lock_token_is_wellformed() {
    [[ "${1:-}" =~ ^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$ ]]
  }
  # shellcheck disable=SC2329 # Called by the extracted settlement functions.
  gate_darwin_lineage_settle() {
    settle_attempts=$((settle_attempts + 1))
    return 2
  }
  # shellcheck disable=SC2329 # Called by the extracted settlement functions.
  gate_report_coordinated_no_work_failure() { return 0; }
  # shellcheck disable=SC2329 # Called by the extracted settlement functions.
  gate_drain_fail_for_context() { return 2; }
  # shellcheck disable=SC1090 # extracted functions are the code under test
  source "$darwin_retry_functions"
  set +e
  gate_drain_settle_darwin_lineage \
    fixture-worker-1 active-command failure phase verdict \
    > "$darwin_retry_fixture/first-output" 2>&1
  first_status=$?
  gate_drain_settle_darwin_lineage \
    fixture-worker-1 active-command failure phase verdict \
    > "$darwin_retry_fixture/second-output" 2>&1
  second_status=$?
  set -e
  [[ "$first_status" -eq 2 && "$second_status" -eq 2 ]]
  [[ "$settle_attempts" -eq 1 ]]
  [[ "$(cat "$retained_state")" == "retained exact lineage evidence" ]]
  grep -Fq \
    "The retained lineage state is reserved for successor recovery." \
    "$darwin_retry_fixture/second-output"
)
rm -rf "$darwin_retry_fixture"

# A failed single-state cohort must not block a later request-level cohort.
# The sibling state can supply exact ownership evidence that the first state
# could not establish alone. The same canonical cohort still gets one bounded
# attempt in this process, regardless of token order.
darwin_cohort_retry_fixture="$(mktemp -d)"
darwin_cohort_retry_functions="$darwin_cohort_retry_fixture/functions.sh"
for darwin_cohort_retry_function in \
  gate_darwin_lineage_cohort_signature \
  gate_darwin_cohort_settlement_failed_in_process \
  gate_darwin_remember_failed_cohort_settlement \
  gate_drain_settle_darwin_lineage_cohort; do
  sed -n "/^${darwin_cohort_retry_function}() {$/,/^}$/p" \
    scripts/agent-quality-gate.sh >> "$darwin_cohort_retry_functions"
done
(
  set -euo pipefail
  # shellcheck disable=SC2034 # Read by the extracted cohort helpers.
  gate_darwin_failed_settlement_cohorts=""
  settle_attempts=0
  # shellcheck disable=SC2329 # Called by the extracted cohort helpers.
  gate_lock_token_is_wellformed() {
    [[ "${1:-}" =~ ^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$ ]]
  }
  # shellcheck disable=SC2329 # Called by the extracted cohort helper.
  gate_darwin_lineage_state_exists() { return 0; }
  # shellcheck disable=SC2329 # Called by the extracted cohort helper.
  gate_darwin_lineage_settle_cohort() {
    settle_attempts=$((settle_attempts + 1))
    printf '%s\n' "$*" >> "$darwin_cohort_retry_fixture/attempts"
    return 2
  }
  # shellcheck disable=SC2329 # Called by the extracted cohort helper.
  gate_report_coordinated_no_work_failure() { return 0; }
  # shellcheck disable=SC2329 # Called by the extracted cohort helper.
  gate_drain_fail_for_context() { return 2; }
  # shellcheck disable=SC2329 # The failing settle path does not reach this.
  gate_drain_finish_exact_darwin_lineage() { return 0; }
  # shellcheck disable=SC1090 # extracted functions are the code under test
  source "$darwin_cohort_retry_functions"
  set +e
  gate_drain_settle_darwin_lineage_cohort \
    active-command fixture-worker-a \
    > "$darwin_cohort_retry_fixture/a-first-output" 2>&1
  a_first_status=$?
  gate_drain_settle_darwin_lineage_cohort \
    active-command fixture-worker-a \
    > "$darwin_cohort_retry_fixture/a-second-output" 2>&1
  a_second_status=$?
  gate_drain_settle_darwin_lineage_cohort \
    active-command fixture-worker-a fixture-worker-b \
    > "$darwin_cohort_retry_fixture/ab-first-output" 2>&1
  ab_first_status=$?
  gate_drain_settle_darwin_lineage_cohort \
    active-command fixture-worker-b fixture-worker-a \
    > "$darwin_cohort_retry_fixture/ab-second-output" 2>&1
  ab_second_status=$?
  set -e
  [[ "$a_first_status" -eq 2 && "$a_second_status" -eq 2 ]]
  [[ "$ab_first_status" -eq 2 && "$ab_second_status" -eq 2 ]]
  [[ "$settle_attempts" -eq 2 ]]
  [[ "$(cat "$darwin_cohort_retry_fixture/attempts")" == \
    $'1 fixture-worker-a\n1 fixture-worker-a fixture-worker-b' ]]
  grep -Fq \
    "The retained lineage state is reserved for successor recovery." \
    "$darwin_cohort_retry_fixture/a-second-output"
  grep -Fq \
    "fixture-worker-a,fixture-worker-b" \
    "$darwin_cohort_retry_fixture/ab-second-output"
)
rm -rf "$darwin_cohort_retry_fixture"
# GitHub issue #1522: every parallel mapped command must be registered as a
# dedicated process group before INT/TERM teardown can run. Cover both sides of
# the original race:
# - registration: INT lands after launch but before the parent records the PGID;
# - execution: the worker leader dies first, so only its still-live process
#   group can reach the reparented TERM-ignoring descendants.
run_parallel_interrupt_regression() {
  local phase="$1"
  local signal="$2"
  local expected_exit="$3"
  local parallel_interrupt_repo
  parallel_interrupt_group_has_live_member() {
    local snapshot
    snapshot="$(TZ=UTC LC_ALL=C ps -axo pgid=,stat= 2>/dev/null)" ||
      return 0
    awk -v target="$1" '
      $1 == target && $2 !~ /^Z/ { found = 1 }
      END { exit(found ? 0 : 1) }
    ' <<< "$snapshot"
  }
  parallel_interrupt_pid_is_live() {
    local pid="$1"
    local expected_start="$2"
    local current_start state
    current_start="$(normalized_process_start "$pid")"
    [[ -n "$current_start" && "$current_start" == "$expected_start" ]] ||
      return 1
    state="$(TZ=UTC LC_ALL=C ps -o stat= -p "$pid" 2>/dev/null |
      awk 'NF { print $1; exit }' || true)"
    [[ -n "$state" && "$state" != Z* ]]
  }
  parallel_interrupt_repo="$(mktemp -d)"
  (
    cd "$parallel_interrupt_repo"
    git init -q
    git config user.email test@example.invalid
    git config user.name "Quality Gate Test"
    mkdir -p bin scripts/gate tools
    printf 'console.log("fixture");\n' > scripts/gate/agent-prewarm.mjs
    mkdir -p scripts/context
    printf 'console.log("fixture");\n' > scripts/context/agent-context-budget.mjs
    cat > tools/trunk <<'STUB'
#!/usr/bin/env bash
if [ "${1:-} ${2:-}" = "daemon status" ]; then
  printf 'x Daemon stopped\n'
  exit 1
fi
if [[ "${QG_FAST_RUN:-0}" == "1" ]]; then
  exit 0
fi
exec qg-par-victim
STUB
    cat > bin/qg-par-descendant <<'STUB'
#!/usr/bin/env bash
trap '' TERM
printf '%s\n' "$$" > "${QG_DESCENDANT_PID_FILE:?}"
while :; do sleep 1; done
STUB
    cat > bin/qg-par-victim <<'STUB'
#!/usr/bin/env bash
trap '' TERM
printf '%s\n' "$$" > "${QG_VICTIM_PID_FILE:?}"
qg-par-descendant &
wait
STUB
    cat > bin/pnpm <<'STUB'
#!/usr/bin/env bash
if [[ "${QG_FAST_RUN:-0}" == "1" ]]; then
  exit 0
fi
exec sleep 45
STUB
    chmod +x bin/pnpm bin/qg-par-victim bin/qg-par-descendant tools/trunk
    git add .
    git commit -qm init
    printf 'scripts/gate/agent-prewarm.mjs\nscripts/context/agent-context-budget.mjs\n' > changed-paths.txt

    local barrier="$parallel_interrupt_repo/registration"
    local gate_output="$parallel_interrupt_repo/gate-output"
    local next_gate_output="$parallel_interrupt_repo/next-gate-output"
    local victim_pid_file="$parallel_interrupt_repo/victim.pid"
    local descendant_pid_file="$parallel_interrupt_repo/descendant.pid"
    local interrupt_jobs_file="$parallel_interrupt_repo/jobs-$phase"
    local gate_pid=""
    local next_gate_pid=""
    local worker_pgid=""
    local victim_pid=""
    local victim_start=""
    local descendant_pid=""
    local descendant_start=""
    local launched=0
    local settled=0
    local attempt
    local interrupt_exit
    local next_gate_exit
    local settle_started_at=""
    # Both waits below are sized from the gate's own drain contract rather than
    # from how fast this machine happens to settle, so the fixture and the gate
    # cannot drift apart.
    #
    # Teardown drains every registered worker group serially before it re-raises
    # the deferred signal, and each of those drains may legitimately run for
    # AGENT_QUALITY_GATE_LOCK_ORPHAN_DRAIN_SECONDS before the gate gives up and
    # fails closed. Read that same variable, with the same default the gate's
    # gate_lock_seconds_knob call applies, instead of restating the window here.
    #
    # The parent registers at most one worker group per parallel slot, and its
    # own timeout drain identity stays empty for the whole pool because
    # run_with_timeout runs inside the workers rather than the parent, so the
    # pool's parallelism is the number of drains teardown can queue.
    local interrupt_parallelism=2
    local orphan_drain_seconds="${AGENT_QUALITY_GATE_LOCK_ORPHAN_DRAIN_SECONDS:-120}"
    # The drain window bounds the drains only. This covers what follows them:
    # the TERM-then-KILL grace, the process-tree walk, and the lock release.
    local interrupt_settlement_margin_seconds=60
    # A whole-gate deadline guessed from observed settlement is what expired on
    # permitted behaviour in Linux CI. This is the permitted worst case plus
    # room to settle; a gate that never terminates still fails here, and the
    # deadline only decides how long that takes to report.
    local settle_deadline_seconds=$((
      interrupt_parallelism * orphan_drain_seconds +
        interrupt_settlement_margin_seconds
    ))
    # The unobstructed follow-up run is a whole gate rather than a teardown, but
    # it settles each mapped command it completes through the same per-drain
    # window, so it takes the same derived budget rather than a second guessed
    # constant. It measured 35-36s here; the budget only decides how long a run
    # genuinely blocked by the interrupted one's leftovers takes to report.
    local followup_deadline_seconds="$settle_deadline_seconds"

    # Invoked indirectly by the EXIT trap below.
    # shellcheck disable=SC2329
    cleanup_parallel_interrupt_fixture() {
      if [[ "$worker_pgid" =~ ^[1-9][0-9]*$ ]]; then
        kill -KILL -- "-$worker_pgid" 2>/dev/null || true
      fi
      if [[ "$gate_pid" =~ ^[1-9][0-9]*$ ]]; then
        kill -CONT "$gate_pid" 2>/dev/null || true
        kill -KILL "$gate_pid" 2>/dev/null || true
        wait "$gate_pid" 2>/dev/null || true
      fi
      if [[ "$next_gate_pid" =~ ^[1-9][0-9]*$ ]]; then
        kill -KILL "$next_gate_pid" 2>/dev/null || true
        wait "$next_gate_pid" 2>/dev/null || true
      fi
    }
    fail_parallel_interrupt_fixture() {
      local message="$1"
      local diagnostic_output="${2:-$gate_output}"
      cp "$diagnostic_output" "$output_file" 2>/dev/null || true
      fail "$message"
    }
    trap cleanup_parallel_interrupt_fixture EXIT

    if [[ "$phase" == "execution" ]]; then
      : > "${barrier}.release"
    fi

    QG_VICTIM_PID_FILE="$victim_pid_file" \
      QG_DESCENDANT_PID_FILE="$descendant_pid_file" \
      NODE_ENV=test \
      AGENT_QUALITY_GATE_TEST_WORKER_REGISTRATION_BARRIER="$barrier" \
      PATH="$parallel_interrupt_repo/bin:$PATH" \
      /usr/bin/perl -e \
        '$SIG{INT} = "DEFAULT"; $SIG{TERM} = "DEFAULT"; exec @ARGV; die "exec failed: $!\n";' \
        /bin/bash "$repo_root/scripts/agent-quality-gate.sh" \
          --changed-paths-file changed-paths.txt \
          --base HEAD \
          --run \
          --parallel "$interrupt_parallelism" \
          > "$gate_output" 2>&1 &
    gate_pid=$!

    for ((attempt = 0; attempt < 200; attempt++)); do
      if [[
        -s "${barrier}.ready" &&
          -s "$victim_pid_file" &&
          -s "$descendant_pid_file"
      ]]; then
        launched=1
        break
      fi
      if ! kill -0 "$gate_pid" 2>/dev/null; then
        break
      fi
      sleep 0.05
    done
    [[ "$launched" -eq 1 ]] ||
      fail_parallel_interrupt_fixture \
        "parallel $phase interrupt fixture never reached its worker"

    worker_pgid="$(cat "${barrier}.ready")"
    victim_pid="$(cat "$victim_pid_file")"
    victim_start="$(normalized_process_start "$victim_pid")"
    descendant_pid="$(cat "$descendant_pid_file")"
    descendant_start="$(normalized_process_start "$descendant_pid")"
    [[ "$worker_pgid" =~ ^[1-9][0-9]*$ ]] ||
      fail_parallel_interrupt_fixture \
        "parallel $phase interrupt fixture recorded an invalid worker PGID"
    kill -0 -- "-$worker_pgid" 2>/dev/null ||
      fail_parallel_interrupt_fixture \
        "parallel $phase worker did not launch in a dedicated process group"

    if [[ "$phase" == "registration" ]]; then
      # The gate is blocked after worker launch and before registry insertion.
      # The signal must remain pending until the PGID is registered.
      kill "-$signal" "$gate_pid"
      sleep 0.2 || true
      : > "${barrier}.release"
    else
      # Freeze the parent with the group registered, remove only the group
      # leader, then interrupt the parent. A PID-tree snapshot rooted at the
      # dead leader cannot find the surviving group members.
      sleep 0.2
      kill -STOP "$gate_pid"
      kill -KILL "$worker_pgid"
      sleep 0.1
      kill "-$signal" "$gate_pid"
      kill -CONT "$gate_pid"
    fi

    # Measure the wait on the clock rather than by counting sleeps. The builtin
    # job observer avoids adding repeated process-table queries while the
    # interrupted gate settles its Darwin lineage.
    #
    # A swallowed interrupt still fails here: the gate would keep running its
    # mapped commands, and the trunk fixture's worker never exits on its own, so
    # no amount of waiting produces the exit this asserts. The deadline only
    # decides how long that failure takes to report (issue 2108).
    settle_started_at="$SECONDS"
    while ((SECONDS - settle_started_at < settle_deadline_seconds)); do
      if ! parallel_execution_job_active \
        "$gate_pid" "$interrupt_jobs_file"; then
        settled=1
        break
      fi
      sleep 0.25
    done
    if [[ "$settled" -eq 0 ]] &&
      ! parallel_execution_job_active \
        "$gate_pid" "$interrupt_jobs_file"; then
      settled=1
    fi
    [[ "$settled" -eq 1 ]] ||
      fail_parallel_interrupt_fixture \
        "parallel $phase interrupt did not terminate the gate within ${settle_deadline_seconds}s"

    set +e
    wait "$gate_pid"
    interrupt_exit=$?
    set -e
    gate_pid=""
    [[ "$interrupt_exit" -eq "$expected_exit" ]] ||
      fail_parallel_interrupt_fixture \
        "parallel $phase interrupt exited $interrupt_exit, expected $expected_exit"

    for ((attempt = 0; attempt < 100; attempt++)); do
      if ! parallel_interrupt_group_has_live_member "$worker_pgid"; then
        break
      fi
      sleep 0.05
    done
    if parallel_interrupt_group_has_live_member "$worker_pgid"; then
      fail_parallel_interrupt_fixture \
        "parallel $phase interrupt left a live registered worker-group member"
    fi
    if parallel_interrupt_pid_is_live "$victim_pid" "$victim_start" ||
      parallel_interrupt_pid_is_live "$descendant_pid" "$descendant_start"; then
      fail_parallel_interrupt_fixture \
        "parallel $phase interrupt left a TERM-ignoring descendant running"
    fi
    worker_pgid=""

    # The interrupted run must leave no process that a later gate can inherit
    # or join. Run the same plan with fast fixtures and bound its completion.
    QG_FAST_RUN=1 \
      PATH="$parallel_interrupt_repo/bin:$PATH" \
      /bin/bash "$repo_root/scripts/agent-quality-gate.sh" \
        --changed-paths-file changed-paths.txt \
        --base HEAD \
        --run \
        --parallel "$interrupt_parallelism" \
        > "$next_gate_output" 2>&1 &
    next_gate_pid=$!
    settled=0
    # Use the same clock and low-churn observer for the follow-up gate. The
    # budget comes from the drain contract, not from machine timings. Only a
    # run blocked by interrupted work should reach it (issue 2108).
    settle_started_at="$SECONDS"
    while ((SECONDS - settle_started_at < followup_deadline_seconds)); do
      if ! parallel_execution_job_active \
        "$next_gate_pid" "$interrupt_jobs_file"; then
        settled=1
        break
      fi
      sleep 0.25
    done
    if [[ "$settled" -eq 0 ]] &&
      ! parallel_execution_job_active \
        "$next_gate_pid" "$interrupt_jobs_file"; then
      settled=1
    fi
    [[ "$settled" -eq 1 ]] ||
      fail_parallel_interrupt_fixture \
        "gate after parallel $phase interrupt did not finish cleanly within ${followup_deadline_seconds}s" \
        "$next_gate_output"
    set +e
    wait "$next_gate_pid"
    next_gate_exit=$?
    set -e
    next_gate_pid=""
    [[ "$next_gate_exit" -eq 0 ]] ||
      fail_parallel_interrupt_fixture \
        "gate after parallel $phase interrupt exited $next_gate_exit" \
        "$next_gate_output"
    ! grep -Fq \
      "A completed mapped command left descendants running; stopping them before releasing its scheduler lease." \
      "$next_gate_output" ||
      fail_parallel_interrupt_fixture \
        "normal parallel completion reported its intentional worker sentinel as a leaked descendant" \
        "$next_gate_output"

    trap - EXIT
  )
  rm -rf "$parallel_interrupt_repo"
}

if [[ "$execution_parallel_case" == all ]]; then
  run_parallel_interrupt_regression registration INT 130
  run_parallel_interrupt_regression execution TERM 143
fi

# A no-lock run has no coordinator or legacy owner that can recover its live
# parallel sentinel. Once the mapped command has published its result, killing
# the parent must let every sentinel exit instead of leaving a permanent Bash
# process behind.
run_parallel_nolock_parent_death_regression() {
  local fixture_repo
  fixture_repo="$(mktemp -d)"
  (
    cd "$fixture_repo"
    git init -q
    git config user.email test@example.invalid
    git config user.name "Quality Gate Test"
    mkdir -p bin scripts/context scripts/gate tools
    printf 'console.log("fixture");\n' > scripts/gate/agent-prewarm.mjs
    printf 'console.log("fixture");\n' > scripts/context/agent-context-budget.mjs
    cat > tools/trunk <<'STUB'
#!/usr/bin/env bash
if [ "${1:-} ${2:-}" = "daemon status" ]; then
  printf 'x Daemon stopped\n'
  exit 1
fi
exit 0
STUB
    cat > bin/pnpm <<'STUB'
#!/usr/bin/env bash
if [[ "${1:-}" == "--version" ]]; then
  printf '9.0.0\n'
fi
exit 0
STUB
    chmod +x bin/pnpm tools/trunk
    git add .
    git commit -qm init
    printf 'scripts/gate/agent-prewarm.mjs\nscripts/context/agent-context-budget.mjs\n' \
      > changed-paths.txt

    local registration_barrier="$fixture_repo/registration"
    local drain_barrier="$fixture_repo/drain"
    local gate_output="$fixture_repo/gate-output"
    local gate_pid=""
    local gate_start=""
    local worker_pid worker_start
    local attempt all_gone
    local -a worker_pids=()
    local -a worker_starts=()

    nolock_fixture_process_live() {
      local pid="$1"
      local expected_start="$2"
      local observed_start observed_state
      observed_start="$(normalized_process_start "$pid")"
      [[ -n "$observed_start" && "$observed_start" == "$expected_start" ]] ||
        return 1
      observed_state="$(TZ=UTC LC_ALL=C ps -o stat= -p "$pid" 2>/dev/null |
        awk 'NF { print $1; exit }' || true)"
      [[ -n "$observed_state" && "$observed_state" != Z* ]]
    }
    # shellcheck disable=SC2329 # invoked by the EXIT trap below
    cleanup_parallel_nolock_fixture() {
      local cleanup_index cleanup_pid cleanup_start cleanup_attempt
      local candidate_start verified_start candidate_parent already_recorded
      : > "${registration_barrier}.release"
      : > "${drain_barrier}.release"
      if [[ "$gate_pid" =~ ^[1-9][0-9]*$ && -z "$gate_start" ]] &&
        jobs -pr | grep -Fxq "$gate_pid"; then
        candidate_start="$(normalized_process_start "$gate_pid")"
        verified_start="$(normalized_process_start "$gate_pid")"
        if [[ -n "$candidate_start" && "$candidate_start" == "$verified_start" ]]; then
          gate_start="$candidate_start"
        fi
      fi
      # Recover workers published before an early assertion failure. Require
      # the exact live gate parent before trusting a PID from the fixture file.
      if [[ -s "${registration_barrier}.workers" &&
        "$gate_pid" =~ ^[1-9][0-9]*$ && -n "$gate_start" &&
        "$(normalized_process_start "$gate_pid")" == "$gate_start" ]]; then
        while IFS= read -r cleanup_pid; do
          [[ "$cleanup_pid" =~ ^[1-9][0-9]*$ ]] || continue
          already_recorded=0
          for cleanup_index in "${!worker_pids[@]}"; do
            if [[ "${worker_pids[$cleanup_index]}" == "$cleanup_pid" ]]; then
              already_recorded=1
              break
            fi
          done
          [[ "$already_recorded" -eq 0 ]] || continue
          candidate_parent="$(TZ=UTC LC_ALL=C ps -o ppid= -p "$cleanup_pid" 2>/dev/null |
            awk 'NF { print $1; exit }' || true)"
          [[ "$candidate_parent" == "$gate_pid" ]] || continue
          candidate_start="$(normalized_process_start "$cleanup_pid")"
          verified_start="$(normalized_process_start "$cleanup_pid")"
          [[ -n "$candidate_start" && "$candidate_start" == "$verified_start" ]] ||
            continue
          worker_pids+=("$cleanup_pid")
          worker_starts+=("$candidate_start")
        done < "${registration_barrier}.workers"
      fi
      if [[ "$gate_pid" =~ ^[1-9][0-9]*$ && -n "$gate_start" ]] &&
        jobs -pr | grep -Fxq "$gate_pid" &&
        [[ "$(normalized_process_start "$gate_pid")" == "$gate_start" ]]; then
        kill -KILL "$gate_pid" 2>/dev/null || true
        wait "$gate_pid" 2>/dev/null || true
      fi
      for cleanup_index in "${!worker_pids[@]}"; do
        cleanup_pid="${worker_pids[$cleanup_index]}"
        cleanup_start="${worker_starts[$cleanup_index]}"
        nolock_fixture_process_live "$cleanup_pid" "$cleanup_start" || continue
        kill -TERM "$cleanup_pid" 2>/dev/null || true
        for ((cleanup_attempt = 0; cleanup_attempt < 40; cleanup_attempt++)); do
          nolock_fixture_process_live "$cleanup_pid" "$cleanup_start" || break
          sleep 0.05
        done
        if nolock_fixture_process_live "$cleanup_pid" "$cleanup_start"; then
          [[ "$(normalized_process_start "$cleanup_pid")" == "$cleanup_start" ]] &&
            kill -KILL "$cleanup_pid" 2>/dev/null || true
        fi
      done
      rm -rf "$fixture_repo"
    }
    fail_parallel_nolock_fixture() {
      cp "$gate_output" "$output_file" 2>/dev/null || true
      fail "$*"
    }
    trap cleanup_parallel_nolock_fixture EXIT

    : > "${registration_barrier}.release"
    NODE_ENV=test \
      AGENT_QUALITY_GATE_TEST_WORKER_REGISTRATION_BARRIER="$registration_barrier" \
      AGENT_QUALITY_GATE_TEST_DRAIN_REFRESH_BARRIER="$drain_barrier" \
      PATH="$fixture_repo/bin:$PATH" \
      /bin/bash "$repo_root/scripts/agent-quality-gate.sh" \
        --changed-paths-file changed-paths.txt \
        --base HEAD --run --parallel 2 --no-lock \
        > "$gate_output" 2>&1 &
    gate_pid=$!
    for ((attempt = 0; attempt < 100; attempt++)); do
      gate_start="$(normalized_process_start "$gate_pid")"
      [[ -n "$gate_start" ]] && break
      kill -0 "$gate_pid" 2>/dev/null || break
      sleep 0.02
    done
    [[ -n "$gate_start" ]] ||
      fail_parallel_nolock_fixture "could not bind the no-lock gate identity"

    for ((attempt = 0; attempt < 500; attempt++)); do
      [[ -s "${registration_barrier}.workers" && -e "${drain_barrier}.ready" ]] &&
        break
      nolock_fixture_process_live "$gate_pid" "$gate_start" || break
      sleep 0.02
    done
    [[ -s "${registration_barrier}.workers" && -e "${drain_barrier}.ready" ]] ||
      fail_parallel_nolock_fixture \
        "no-lock parallel fixture never reached completed-worker drain"

    while IFS= read -r worker_pid; do
      [[ "$worker_pid" =~ ^[1-9][0-9]*$ ]] || continue
      worker_start="$(normalized_process_start "$worker_pid")"
      [[ -n "$worker_start" ]] ||
        fail_parallel_nolock_fixture "could not bind a no-lock worker identity"
      worker_pids+=("$worker_pid")
      worker_starts+=("$worker_start")
    done < <(awk '!seen[$0]++' "${registration_barrier}.workers")
    [[ "${#worker_pids[@]}" -ge 2 ]] ||
      fail_parallel_nolock_fixture \
        "no-lock fixture did not register both parallel workers"
    for attempt in "${!worker_pids[@]}"; do
      nolock_fixture_process_live \
        "${worker_pids[$attempt]}" "${worker_starts[$attempt]}" ||
        fail_parallel_nolock_fixture \
          "no-lock worker was not a live sentinel at the drain barrier"
    done

    [[ "$(normalized_process_start "$gate_pid")" == "$gate_start" ]] ||
      fail_parallel_nolock_fixture "no-lock gate identity changed before crash"
    kill -KILL "$gate_pid"
    wait "$gate_pid" 2>/dev/null || true
    gate_pid=""
    : > "${drain_barrier}.release"

    for ((attempt = 0; attempt < 200; attempt++)); do
      all_gone=1
      for worker_pid in "${!worker_pids[@]}"; do
        if nolock_fixture_process_live \
          "${worker_pids[$worker_pid]}" "${worker_starts[$worker_pid]}"; then
          all_gone=0
          break
        fi
      done
      [[ "$all_gone" -eq 0 ]] || break
      sleep 0.05
    done
    [[ "$all_gone" -eq 1 ]] ||
      fail_parallel_nolock_fixture \
        "no-lock parent crash left a parallel worker sentinel running"

    trap - EXIT
  )
  rm -rf "$fixture_repo"
}

if [[ "$execution_parallel_case" == all ]]; then
  run_parallel_nolock_parent_death_regression
fi

# Recovery can see more than one process that holds a command token. Preserve
# word boundaries across the newline-delimited scan, and retain a scan failure
# even when another backend still reports PIDs. The tagged group leader must
# remain eligible so its handleless same-group member enters the capture.
(
  gate_group_function="$(awk '
    /^gate_drain_capture_seed_group\(\)/ { capture = 1 }
    capture { print }
    capture && /^}$/ { exit }
  ' "$repo_root/scripts/agent-quality-gate.sh")"
  [[ -n "$gate_group_function" ]] ||
    fail "could not load the parallel group-capture helper for its focused regression"
  eval "$gate_group_function"

