      if [[ "$(uname -s)" == Darwin ]]; then
        case "$darwin_exact_identity" in
          agentqg-darwin-exact-v1:pid1-*":${pid}:"*) ;;
          *) return 2 ;;
        esac
        status="$(node "$repo_root/scripts/gate/darwin-process-lineage.mjs" \
          status-exact --scratch "$darwin_scratch" \
          --identity "$darwin_exact_identity")" || return 2
        [[ "$status" == live ]]
        return $?
      fi
      [[ "$darwin_exact_identity" == portable ]] || return 2
      parallel_detached_worker_runtime_live "$pid" "$expected_start"
    }
    parallel_detached_targets_are_owned() {
      local state_search_root="$1"
      local first_pid="$2"
      local second_pid="$3"
      node -e '
        const fs = require("node:fs");
        const path = require("node:path");
        const [root, firstPid, secondPid] = process.argv.slice(1);
        const states = [];
        const visit = (directory) => {
          for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
            const candidate = path.join(directory, entry.name);
            if (entry.isDirectory()) visit(candidate);
            else if (/^lineage\..+\.json$/u.test(entry.name)) states.push(candidate);
          }
        };
        visit(root);
        for (const statePath of states) {
          let state;
          try {
            state = JSON.parse(fs.readFileSync(statePath, "utf8"));
          } catch {
            continue;
          }
          const byPid = new Map(
            (state.tombstones ?? []).map((item) => [String(item.pid), item]),
          );
          if (
            byPid.get(firstPid)?.classification === "owned" &&
            byPid.get(secondPid)?.classification === "owned"
          ) process.exit(0);
        }
        process.exit(1);
      ' "$state_search_root" "$first_pid" "$second_pid"
    }
    parallel_detached_stop_exact() {
      local label="$1"
      local pid="$2"
      local expected_start="$3"
      local darwin_exact_identity="${4:-}"
      local darwin_scratch="${5:-$fixture_repo/.tmp/agent-quality-gate}"
      local stop_attempt
      [[ "$pid" =~ ^[1-9][0-9]*$ && -n "$expected_start" ]] || return 0
      if [[ -n "$darwin_exact_identity" ]]; then
        parallel_detached_worker_live \
          "$pid" "$expected_start" "$darwin_exact_identity" \
          "$darwin_scratch" || return 0
      else
        parallel_detached_process_live "$pid" "$expected_start" || return 0
      fi
      parallel_detached_signal_exact \
        TERM "$pid" "$expected_start" "$darwin_exact_identity" \
        "$darwin_scratch" || true
      for ((stop_attempt = 0; stop_attempt < 120; stop_attempt++)); do
        if [[ -n "$darwin_exact_identity" ]]; then
          parallel_detached_worker_live \
            "$pid" "$expected_start" "$darwin_exact_identity" \
            "$darwin_scratch" || return 0
        else
          parallel_detached_process_live "$pid" "$expected_start" || return 0
        fi
        sleep 0.05
      done
      parallel_detached_signal_exact \
        KILL "$pid" "$expected_start" "$darwin_exact_identity" \
        "$darwin_scratch" || true
      for ((stop_attempt = 0; stop_attempt < 100; stop_attempt++)); do
        if [[ -n "$darwin_exact_identity" ]]; then
          parallel_detached_worker_live \
            "$pid" "$expected_start" "$darwin_exact_identity" \
            "$darwin_scratch" || return 0
        else
          parallel_detached_process_live "$pid" "$expected_start" || return 0
        fi
        sleep 0.05
      done
      printf 'cleanup could not stop %s at exact pid/start identity %s\n' \
        "$label" "$pid" >&2
      return 1
    }
    parallel_detached_stop_worker_records() {
      local records_file="$1"
      local label="$2"
      local darwin_scratch="$3"
      local version entry_pid entry_start entry_drain entry_contract entry_exact extra
      [[ -f "$records_file" ]] || return 0
      while IFS='|' read -r version entry_pid entry_start entry_drain \
        entry_contract entry_exact extra; do
        [[ "$version" == agentqg-worker-v1 && -z "$extra" &&
          "$entry_pid" =~ ^[1-9][0-9]*$ && -n "$entry_start" &&
          "$entry_drain" =~ ^[A-Za-z0-9][A-Za-z0-9._-]{0,180}-[0-9]{1,10}-[0-9]{1,12}$ &&
          "$entry_contract" =~ ^(portable-marker-v1|darwin-coherent-lineage-v2)$ ]] ||
          return 1
        parallel_detached_stop_exact \
          "$label" "$entry_pid" "$entry_start" "$entry_exact" \
          "$darwin_scratch" || return 1
      done < "$records_file"
    }
    parallel_detached_validate_worker_records() {
      local records_file="$1"
      local version entry_pid entry_start entry_drain entry_contract entry_exact extra
      local count=0 seen=" "
      [[ -s "$records_file" ]] || return 1
      while IFS='|' read -r version entry_pid entry_start entry_drain \
        entry_contract entry_exact extra; do
        [[ "$version" == agentqg-worker-v1 && -z "$extra" &&
          "$entry_pid" =~ ^[1-9][0-9]*$ && -n "$entry_start" &&
          "$entry_drain" =~ ^[A-Za-z0-9][A-Za-z0-9._-]{0,180}-[0-9]{1,10}-[0-9]{1,12}$ ]] || return 1
        case "$seen" in *" ${entry_pid} "*) return 1 ;; esac
        seen="${seen}${entry_pid} "
        if [[ "$(uname -s)" == Darwin ]]; then
          [[ "$entry_contract" == darwin-coherent-lineage-v2 ]] || return 1
          case "$entry_exact" in
            agentqg-darwin-exact-v1:pid1-*":${entry_pid}:"*) ;;
            *) return 1 ;;
          esac
        else
          [[ "$entry_contract" == portable-marker-v1 &&
            "$entry_exact" == portable ]] || return 1
        fi
        count=$((count + 1))
      done < "$records_file"
      [[ "$count" -gt 0 ]]
    }
    parallel_detached_worker_records_settled() {
      local records_file="$1"
      local darwin_scratch="$2"
      local version entry_pid entry_start entry_drain entry_contract entry_exact extra
      local live_status
      parallel_detached_validate_worker_records "$records_file" || return 2
      while IFS='|' read -r version entry_pid entry_start entry_drain \
        entry_contract entry_exact extra; do
        if parallel_detached_worker_live \
          "$entry_pid" "$entry_start" "$entry_exact" "$darwin_scratch"; then
          return 1
        else
          live_status=$?
          [[ "$live_status" -eq 1 ]] || return 2
        fi
      done < "$records_file"
      return 0
    }
    parallel_detached_worker_markers_absent() {
      local records_file="$1"
      local version entry_pid entry_start entry_drain entry_contract entry_exact extra
      parallel_detached_validate_worker_records "$records_file" || return 2
      while IFS='|' read -r version entry_pid entry_start entry_drain \
        entry_contract entry_exact extra; do
        [[ ! -e "${fixture_lock_root}/holder.${entry_drain}" &&
          ! -L "${fixture_lock_root}/holder.${entry_drain}" ]] || return 1
      done < "$records_file"
    }
    # shellcheck disable=SC2329 # invoked by the EXIT trap below
    cleanup_parallel_detached_fixture() {
      local metadata coordinator_pid coordinator_start captured entry_pid entry_start
      local candidate_start verified_start
      [[ -z "$launcher_release_file" ]] || : > "$launcher_release_file"
      [[ -z "$drain_refresh_barrier" ]] || : > "${drain_refresh_barrier}.release"
      if [[ (! "$detached_pid" =~ ^[1-9][0-9]*$ || -z "$detached_start") &&
        -s "$ready_file" ]]; then
        IFS='|' read -r detached_pid detached_start detached_pgid < "$ready_file" || true
      fi
      if [[ (! "$handleless_pid" =~ ^[1-9][0-9]*$ || -z "$handleless_start") &&
        -s "$handleless_ready_file" ]]; then
        IFS='|' read -r handleless_pid handleless_start handleless_pgid \
          < "$handleless_ready_file" || true
      fi
      if [[ (! "$launcher_pid" =~ ^[1-9][0-9]*$ || -z "$launcher_start") &&
        -s "$launcher_ready_file" ]]; then
        IFS='|' read -r launcher_pid launcher_start launcher_pgid \
          < "$launcher_ready_file" || true
      fi
      if [[ ! "$worker_pid" =~ ^[1-9][0-9]*$ &&
        "$launcher_pgid" =~ ^[1-9][0-9]*$ ]]; then
        worker_pid="$launcher_pgid"
      fi
      # A first start-identity read can race immediate process launch. Recover
      # it only while Bash still reports this PID as our live background job,
      # then require two equal snapshots before an exact cleanup signal.
      if [[ "$gate_pid" =~ ^[1-9][0-9]*$ && -z "$gate_start" ]] &&
        jobs -pr | grep -Fxq "$gate_pid"; then
        candidate_start="$(parallel_detached_process_start "$gate_pid")"
        verified_start="$(parallel_detached_process_start "$gate_pid")"
        if [[ -n "$candidate_start" && "$candidate_start" == "$verified_start" ]]; then
          gate_start="$candidate_start"
        fi
      fi
      if [[ "$contender_pid" =~ ^[1-9][0-9]*$ && -z "$contender_start" ]] &&
        jobs -pr | grep -Fxq "$contender_pid"; then
        candidate_start="$(parallel_detached_process_start "$contender_pid")"
        verified_start="$(parallel_detached_process_start "$contender_pid")"
        if [[ -n "$candidate_start" && "$candidate_start" == "$verified_start" ]]; then
          contender_start="$candidate_start"
        fi
      fi
      # The worker is a child of the exact-live fixture gate and the launcher
      # records its dedicated PGID. Bind that leader before cleanup signals it.
      if [[ "$worker_pid" =~ ^[1-9][0-9]*$ && -z "$worker_start" &&
        "$gate_pid" =~ ^[1-9][0-9]*$ && -n "$gate_start" ]] &&
        parallel_detached_process_live "$gate_pid" "$gate_start"; then
        candidate_start="$(parallel_detached_process_start "$worker_pid")"
        verified_start="$(parallel_detached_process_start "$worker_pid")"
        if [[ -n "$candidate_start" && "$candidate_start" == "$verified_start" &&
          "$(TZ=UTC LC_ALL=C LANG=C ps -p "$worker_pid" -o pgid= 2>/dev/null |
            tr -d '[:space:]' || true)" == "$worker_pid" ]]; then
          worker_start="$candidate_start"
        fi
      fi
      if [[ "$gate_pid" =~ ^[1-9][0-9]*$ && -n "$gate_start" ]]; then
        if parallel_detached_stop_exact \
          "detached-drain holder gate" "$gate_pid" "$gate_start"; then
          wait "$gate_pid" 2>/dev/null || true
        else
          cleanup_failed=1
        fi
      fi
      if [[ "$contender_pid" =~ ^[1-9][0-9]*$ && -n "$contender_start" ]]; then
        if parallel_detached_stop_exact \
          "detached-drain contender gate" "$contender_pid" "$contender_start"; then
          wait "$contender_pid" 2>/dev/null || true
        else
          cleanup_failed=1
        fi
      fi
      parallel_detached_stop_worker_records \
        "${holder_worker_barrier}.identities" \
        "detached-drain holder worker sentinel" \
        "$fixture_repo/.tmp/agent-quality-gate" || cleanup_failed=1
      parallel_detached_stop_worker_records \
        "${contender_worker_barrier}.identities" \
        "detached-drain contender worker sentinel" \
        "$contender_repo/.tmp/agent-quality-gate" || cleanup_failed=1
      if [[ ! -s "${holder_worker_barrier}.identities" &&
        "$worker_pid" =~ ^[1-9][0-9]*$ && -n "$worker_start" ]]; then
        parallel_detached_stop_exact \
          "detached-drain parallel worker sentinel" \
          "$worker_pid" "$worker_start" || cleanup_failed=1
      fi
      if [[ "$detached_pid" =~ ^[1-9][0-9]*$ && -n "$detached_start" ]]; then
        parallel_detached_stop_exact \
          "detached mapped-command child" "$detached_pid" "$detached_start" ||
          cleanup_failed=1
      fi
      if [[ "$handleless_pid" =~ ^[1-9][0-9]*$ && -n "$handleless_start" ]]; then
        parallel_detached_stop_exact \
          "handleless same-group mapped-command child" \
          "$handleless_pid" "$handleless_start" || cleanup_failed=1
      fi
      if [[ "$launcher_pid" =~ ^[1-9][0-9]*$ && -n "$launcher_start" ]]; then
        parallel_detached_stop_exact \
          "detached-drain launcher" "$launcher_pid" "$launcher_start" ||
          cleanup_failed=1
      fi
      while IFS= read -r captured; do
        [[ -f "$captured" ]] || continue
        while IFS='|' read -r entry_pid entry_start; do
          entry_start="$(printf '%s\n' "$entry_start" |
            sed 's/^[[:space:]]*//; s/[[:space:]]*$//')"
          [[ "$entry_pid" =~ ^[1-9][0-9]*$ && -n "$entry_start" ]] || continue
          parallel_detached_stop_exact \
            "captured detached-drain process" "$entry_pid" "$entry_start" ||
            cleanup_failed=1
        done < "$captured"
      done < <(find "$fixture_lock_root" -type f \
        -name 'captured.*' -print 2>/dev/null)
      while IFS= read -r metadata; do
        [[ -f "$metadata" ]] || continue
        IFS=$'\t' read -r coordinator_pid coordinator_start <<< "$(node -e '
          const value = JSON.parse(require("node:fs").readFileSync(process.argv[1], "utf8"));
          process.stdout.write([
            String(value.coordinatorIdentity?.pid ?? ""),
            value.coordinatorIdentity?.startUtc ?? "",
          ].join("\t"));
        ' "$metadata" 2>/dev/null || true)"
        if [[ "$coordinator_pid" =~ ^[1-9][0-9]*$ &&
          -n "$coordinator_start" ]]; then
          parallel_detached_stop_exact \
            "detached-drain coordinator" \
            "$coordinator_pid" "$coordinator_start" || cleanup_failed=1
        fi
      done < <(find "$fixture_lock_root" -type f \
        -name coordinator.json -print 2>/dev/null)
      rm -rf "$fixture_repo" "$contender_repo" "$fixture_lock_root"
    }
    parallel_detached_append_ambiguous_diagnostics() {
      local state_file boot_id candidate_pid unique_id parent_unique_id
      local exact_identity status status_exit
      [[ "$(uname -s)" == Darwin ]] || return 0
      {
        printf '%s\n' 'Darwin ambiguous lineage diagnostics before fixture cleanup:'
        while IFS= read -r state_file; do
          [[ -f "$state_file" ]] || continue
          while IFS='|' read -r boot_id candidate_pid unique_id \
            parent_unique_id; do
            [[ "$candidate_pid" =~ ^[1-9][0-9]*$ &&
              "$unique_id" =~ ^[0-9]+$ &&
              "$parent_unique_id" =~ ^[0-9]+$ ]] || continue
            exact_identity="agentqg-darwin-exact-v1:${boot_id}:${candidate_pid}:${unique_id}:${parent_unique_id}"
            status_exit=0
            status="$(node "$repo_root/scripts/gate/darwin-process-lineage.mjs" \
              status-exact --scratch "$fixture_repo/.tmp/agent-quality-gate" \
              --identity "$exact_identity" 2>&1)" || status_exit=$?
            printf 'state=%s exactIdentity=%s statusExit=%s status=%s\n' \
              "$state_file" "$exact_identity" "$status_exit" "$status"
            [[ "$status_exit" -eq 0 && "$status" == live ]] || continue
            /bin/ps -o pid=,ppid=,pgid=,sess=,stat=,etime=,lstart=,command= \
              -p "$candidate_pid" 2>&1 || true
            if command -v lsof >/dev/null 2>&1; then
              lsof -nP -a -p "$candidate_pid" -d cwd 2>&1 || true
              lsof -nP -a -p "$candidate_pid" 2>/dev/null |
                awk -v root="$fixture_lock_root" '
                  NR == 1 || index($0, root) > 0 ||
                    $0 ~ /(holder\.|wait\.(fifo|request)|gate-output|lineage\.)/
                ' || true
            fi
          done < <(node -e '
            const fs = require("node:fs");
            const { execFileSync } = require("node:child_process");
            const state = JSON.parse(fs.readFileSync(process.argv[1], "utf8"));
            const livePids = new Set(
              execFileSync("/bin/ps", ["-axo", "pid="], { encoding: "utf8" })
                .trim()
                .split(/\s+/u),
            );
            for (const item of state.tombstones ?? []) {
              if (
                item.classification !== "ambiguous" ||
                !livePids.has(String(item.pid ?? ""))
              ) continue;
              process.stdout.write([
                state.bootId ?? "",
                String(item.pid ?? ""),
                item.uniqueId ?? "",
                item.parentUniqueId ?? "",
              ].join("|") + "\n");
            }
          ' "$state_file" 2>/dev/null || true)
        done < <(find "$fixture_lock_root" -type f \
          -name 'lineage.*.json' -print 2>/dev/null)
      } >> "$output_file"
    }
    fail_parallel_detached_fixture() {
      {
        sed 's/^/holder: /' "$gate_output" 2>/dev/null || true
        sed 's/^/contender: /' "$contender_output" 2>/dev/null || true
        sed 's/^/holder worker: /' \
          "${holder_worker_barrier}.identities" 2>/dev/null || true
        sed 's/^/contender worker: /' \
          "${contender_worker_barrier}.identities" 2>/dev/null || true
        sed 's/^/launcher ready: /' "$launcher_ready_file" 2>/dev/null || true
        sed 's/^/holder dispatch: /' "$holder_dispatch_log" 2>/dev/null || true
      } > "$output_file"
      parallel_detached_append_ambiguous_diagnostics
      fail "$*"
    }
    trap cleanup_parallel_detached_fixture EXIT

    AGENT_QUALITY_GATE_LOCK=1 \
      AGENT_QUALITY_GATE_LOCK_HELD='' \
      AGENT_QUALITY_GATE_LOCK_DIR="$fixture_lock_root" \
      AGENT_QUALITY_GATE_COORDINATOR=1 \
      AGENT_QUALITY_GATE_CAPACITY=1 \
      AGENT_QUALITY_GATE_TEST_DRAIN_REFRESH_BARRIER="$drain_refresh_barrier" \
      AGENT_QUALITY_GATE_TEST_WORKER_REGISTRATION_BARRIER="$holder_worker_barrier" \
      NODE_ENV=test \
      QG_DETACHED_CHILD="$fixture_repo/detached-child.mjs" \
      QG_DETACHED_CHILD_SELF_EXIT_MS="$detached_child_self_exit_ms" \
      QG_HANDLELESS_CHILD="$fixture_repo/handleless-child.mjs" \
      QG_DETACHED_LAUNCHER="$fixture_repo/detached-launcher.mjs" \
      QG_DETACHED_LAUNCHER_RELEASE="$launcher_release_file" \
      QG_DETACHED_CHECK="$fixture_repo/bin/qg-detached-check" \
      QG_HOLDER_DISPATCH_LOG="$holder_dispatch_log" \
      QG_DETACHED_READY="$ready_file" \
      QG_HANDLELESS_READY="$handleless_ready_file" \
      QG_LAUNCHER_READY="$launcher_ready_file" \
      QG_DETACHED_OVERLAP="$overlap_file" \
      QG_DETACHED_STARTED="$holder_started_file" \
      PATH="$fixture_repo/bin:$PATH" \
      /bin/bash "$repo_root/scripts/agent-quality-gate.sh" \
        --changed-paths-file changed-paths.txt \
        --base HEAD --run --parallel "$detached_drain_parallelism" \
        --lock-wait "$detached_drain_lock_wait_seconds" \
        > "$gate_output" 2>&1 &
    gate_pid=$!
    gate_start="$(parallel_detached_process_start "$gate_pid")"
    [[ -n "$gate_start" ]] ||
      fail_parallel_detached_fixture "could not bind the detached-drain gate identity"

    for ((attempt = 0; attempt < 900; attempt++)); do
      [[ -s "$ready_file" && -s "$handleless_ready_file" &&
        -s "$launcher_ready_file" ]] && break
      parallel_detached_process_live "$gate_pid" "$gate_start" || break
      sleep 0.05
    done
    [[ -s "$ready_file" && -s "$handleless_ready_file" &&
      -s "$launcher_ready_file" ]] ||
      fail_parallel_detached_fixture \
        "parallel command never launched both descendant fixtures"
    IFS='|' read -r \
      detached_pid detached_start detached_pgid \
      detached_self_exit_deadline_ms < "$ready_file"
    IFS='|' read -r \
      handleless_pid handleless_start handleless_pgid \
      handleless_self_exit_deadline_ms \
      < "$handleless_ready_file"
    IFS='|' read -r launcher_pid launcher_start launcher_pgid \
      < "$launcher_ready_file"
    worker_pid="$launcher_pgid"
    worker_start="$(parallel_detached_process_start "$worker_pid")"
    worker_runtime_start="$(runtime_process_start "$worker_pid")"
    [[ "$detached_pid" =~ ^[1-9][0-9]*$ && -n "$detached_start" &&
      "$detached_pgid" =~ ^[1-9][0-9]*$ ]] ||
      fail_parallel_detached_fixture "detached child identity is invalid"
    [[ "$handleless_pid" =~ ^[1-9][0-9]*$ && -n "$handleless_start" &&
      "$handleless_pgid" =~ ^[1-9][0-9]*$ ]] ||
      fail_parallel_detached_fixture "handleless child identity is invalid"
    ready_records_observed_at_ms="$(node -e \
      'process.stdout.write(String(Date.now()))')"
    [[ "$ready_records_observed_at_ms" =~ ^[1-9][0-9]*$ ]] ||
      fail_parallel_detached_fixture \
        "could not read the detached fixture ready-record time"
    if [[ ! "$detached_self_exit_deadline_ms" =~ ^[1-9][0-9]*$ ]] ||
      ((detached_self_exit_deadline_ms <= ready_records_observed_at_ms)) ||
      ((
        detached_self_exit_deadline_ms >
          ready_records_observed_at_ms + detached_child_self_exit_ms
      )); then
      fail_parallel_detached_fixture \
        "detached child ready record has an invalid self-exit deadline"
    fi
    if [[ ! "$handleless_self_exit_deadline_ms" =~ ^[1-9][0-9]*$ ]] ||
      ((handleless_self_exit_deadline_ms <= ready_records_observed_at_ms)) ||
      ((
        handleless_self_exit_deadline_ms >
          ready_records_observed_at_ms + detached_child_self_exit_ms
      )); then
      fail_parallel_detached_fixture \
        "marker-free child ready record has an invalid self-exit deadline"
    fi
    [[ "$launcher_pid" =~ ^[1-9][0-9]*$ && -n "$launcher_start" &&
      "$launcher_pgid" =~ ^[1-9][0-9]*$ ]] ||
      fail_parallel_detached_fixture "launcher identity is invalid"
    [[ "$worker_pid" =~ ^[1-9][0-9]*$ && -n "$worker_start" &&
      -n "$worker_runtime_start" &&
      "$worker_pid" != "$launcher_pid" &&
      "$(parallel_detached_process_start "$worker_pid")" == "$worker_start" &&
      "$(runtime_process_start "$worker_pid")" == "$worker_runtime_start" &&
      "$(TZ=UTC LC_ALL=C LANG=C ps -p "$worker_pid" -o pgid= 2>/dev/null |
        tr -d '[:space:]' || true)" == "$worker_pid" ]] ||
      fail_parallel_detached_fixture "parallel worker sentinel identity is invalid"
    for ((attempt = 0; attempt < 200; attempt++)); do
      if parallel_detached_validate_worker_records \
        "${holder_worker_barrier}.identities" &&
        [[ "$(wc -l < "${holder_worker_barrier}.identities" | tr -d '[:space:]')" -ge 2 ]]; then
        break
      fi
      parallel_detached_process_live "$gate_pid" "$gate_start" || break
      sleep 0.05
    done
    parallel_detached_validate_worker_records \
      "${holder_worker_barrier}.identities" ||
      fail_parallel_detached_fixture \
        "holder worker sentinels have incomplete lifecycle identities"
    [[ "$(wc -l < "${holder_worker_barrier}.identities" | tr -d '[:space:]')" -ge 2 ]] ||
      fail_parallel_detached_fixture \
        "holder did not register both capacity-one worker sentinels"
    awk -F '|' -v pid="$worker_pid" -v start="$worker_runtime_start" '
      $1 == "agentqg-worker-v1" && $2 == pid && $3 == start { found = 1 }
      END { exit(found ? 0 : 1) }
    ' "${holder_worker_barrier}.identities" ||
      fail_parallel_detached_fixture \
        "mapped-command worker is absent from the holder sentinel registry"
    parallel_detached_process_live "$detached_pid" "$detached_start" ||
      fail_parallel_detached_fixture "detached child was not live after launch"
    parallel_detached_process_live "$handleless_pid" "$handleless_start" ||
      fail_parallel_detached_fixture "handleless child was not live after launch"
    [[ "$detached_pgid" == "$detached_pid" ]] ||
      fail_parallel_detached_fixture "detached child did not leave the worker process group"
    if [[ "$(uname -s)" == Darwin ]]; then
      [[ "$handleless_pgid" == "$handleless_pid" ]] ||
        fail_parallel_detached_fixture \
          "marker-free Darwin child did not enter a new session"
    else
      [[ "$handleless_pgid" == "$launcher_pgid" &&
        "$handleless_pgid" != "$handleless_pid" ]] ||
        fail_parallel_detached_fixture \
          "handleless child did not remain in the launcher process group"
    fi

    coordinator_metadata="$({
      find "$fixture_lock_root" -type f -name coordinator.json -print 2>/dev/null
    } | head -n1)"
    [[ -f "$coordinator_metadata" ]] ||
      fail_parallel_detached_fixture "detached-drain coordinator metadata is missing"
    IFS=$'\t' read -r state_root coordinator_generation_token \
      coordinator_generation_marker <<< "$(node -e '
      const value = JSON.parse(require("node:fs").readFileSync(process.argv[1], "utf8"));
      process.stdout.write([
        value.stateRoot ?? "",
        value.generationToken ?? "",
        value.markerPath ?? "",
      ].join("\t"));
    ' "$coordinator_metadata")"
    journal_path="${state_root}/journal.json"
    [[ -n "$state_root" && -f "$journal_path" &&
      -n "$coordinator_generation_token" &&
      -f "$coordinator_generation_marker" ]] ||
      fail_parallel_detached_fixture "detached-drain coordinator journal is missing"
    [[ "$(cat "$coordinator_generation_marker")" == "$coordinator_generation_token" ]] ||
      fail_parallel_detached_fixture \
        "detached-drain coordinator generation marker is invalid"
    holder_worktree="$(pwd -P)"
    contender_worktree="$(cd "$contender_repo" && pwd -P)"

    (
      cd "$contender_repo"
      exec env \
        AGENT_QUALITY_GATE_LOCK=1 \
        AGENT_QUALITY_GATE_LOCK_HELD='' \
        AGENT_QUALITY_GATE_LOCK_DIR="$fixture_lock_root" \
        AGENT_QUALITY_GATE_COORDINATOR=1 \
        AGENT_QUALITY_GATE_CAPACITY=1 \
        AGENT_QUALITY_GATE_TEST_WORKER_REGISTRATION_BARRIER="$contender_worker_barrier" \
        NODE_ENV=test \
        QG_DETACHED_CHECK="$fixture_repo/bin/qg-detached-check" \
        QG_DETACHED_READY="$ready_file" \
        QG_HANDLELESS_READY="$handleless_ready_file" \
        QG_DETACHED_OVERLAP="$overlap_file" \
        QG_DETACHED_STARTED="$contender_started_file" \
        PATH="$contender_repo/bin:$PATH" \
        /bin/bash "$repo_root/scripts/agent-quality-gate.sh" \
        --changed-paths-file changed-paths.txt \
        --base HEAD --run --parallel "$detached_drain_parallelism" \
        --lock-wait "$detached_drain_lock_wait_seconds"
    ) > "$contender_output" 2>&1 &
    contender_pid=$!
    contender_start="$(parallel_detached_process_start "$contender_pid")"
    [[ -n "$contender_start" ]] ||
      fail_parallel_detached_fixture "could not bind the detached-drain contender identity"

    # Hold the launcher open until a different worktree owns a queued command
    # lease behind the detached command's granted capacity-one lease.
    for ((attempt = 0; attempt < 900; attempt++)); do
      if node -e '
        const value = JSON.parse(require("node:fs").readFileSync(process.argv[1], "utf8"));
        const [holderRoot, contenderRoot] = process.argv.slice(2);
        const requests = Object.values(value.requests ?? {});
        const leases = Object.values(value.leases ?? {});
        const holder = requests.find((item) => item.worktreeKey === holderRoot);
        const contender = requests.find((item) => item.worktreeKey === contenderRoot);
        const holderGranted = holder && leases.some((item) =>
          item.requestId === holder.requestId && item.status === "granted");
        const contenderQueued = contender && contender.role === "leader" &&
          contender.admission === "held" && leases.some((item) =>
            item.requestId === contender.requestId && item.status === "queued");
        process.exit(holderGranted && contenderQueued ? 0 : 1);
      ' "$journal_path" "$holder_worktree" "$contender_worktree" 2>/dev/null; then
        queued=1
        break
      fi
      parallel_detached_process_live "$gate_pid" "$gate_start" || break
      parallel_detached_process_live "$contender_pid" "$contender_start" || break
      sleep 0.05
    done
    [[ "$queued" -eq 1 ]] ||
      fail_parallel_detached_fixture \
        "external contender did not queue behind the detached command lease"
    for ((attempt = 0; attempt < 200; attempt++)); do
      if parallel_detached_validate_worker_records \
        "${contender_worker_barrier}.identities" &&
        [[ "$(wc -l < "${contender_worker_barrier}.identities" | tr -d '[:space:]')" -ge 2 ]]; then
        break
      fi
      parallel_detached_process_live "$contender_pid" "$contender_start" || break
      sleep 0.05
    done
    parallel_detached_validate_worker_records \
      "${contender_worker_barrier}.identities" ||
      fail_parallel_detached_fixture \
        "contender worker sentinels have incomplete lifecycle identities"
    [[ "$(wc -l < "${contender_worker_barrier}.identities" | tr -d '[:space:]')" -ge 2 ]] ||
      fail_parallel_detached_fixture \
        "contender did not register both capacity-one worker sentinels"
    if [[ "$(uname -s)" == Darwin ]]; then
      for ((attempt = 0; attempt < 40; attempt++)); do
        if parallel_detached_targets_are_owned \
          "$fixture_lock_root" "$detached_pid" "$handleless_pid"; then
          break
        fi
        parallel_detached_process_live "$gate_pid" "$gate_start" || break
        sleep 0.25
      done
      parallel_detached_targets_are_owned \
        "$fixture_lock_root" "$detached_pid" "$handleless_pid" ||
        fail_parallel_detached_fixture \
          "Darwin watcher did not persist both descendants as owned before launcher exit"
    fi
    : > "$launcher_release_file"

    # Pause the holder after the drain has refreshed and durably captured its
    # descendants. The successor must inherit this exact mid-drain state.
    for ((attempt = 0; attempt < 900; attempt++)); do
      if [[ -e "${drain_refresh_barrier}.ready" ]]; then
        barrier_ready=1
        break
      fi
      parallel_detached_process_live "$gate_pid" "$gate_start" || break
      sleep 0.05
    done
    [[ "$barrier_ready" -eq 1 ]] ||
      fail_parallel_detached_fixture \
        "parallel command drain did not reach its refresh barrier"
    if [[ "$(uname -s)" == Darwin ]]; then
      parallel_detached_targets_are_owned \
        "$fixture_lock_root" "$detached_pid" "$handleless_pid" ||
        fail_parallel_detached_fixture \
          "Darwin watcher lost owned descendants after their parent chain broke"
    fi
    [[ "$(wc -l < "$holder_dispatch_log" | tr -d '[:space:]')" -eq 1 ]] ||
      fail_parallel_detached_fixture \
        "capacity-one holder dispatched more than its granted command"
    parallel_detached_process_live "$detached_pid" "$detached_start" ||
      fail_parallel_detached_fixture \
        "detached child exited before the crash-at-drain barrier"
    parallel_detached_process_live "$handleless_pid" "$handleless_start" ||
      fail_parallel_detached_fixture \
        "marker-free child exited before the crash-at-drain barrier"
    parallel_detached_process_holds_path \
      "$worker_pid" "$coordinator_generation_marker" ||
      fail_parallel_detached_fixture \
        "parallel worker sentinel did not retain the coordinator generation handle"
    [[ ! -e "$contender_started_file" ]] ||
      fail_parallel_detached_fixture \
        "external contender started while the holder drain was paused"
    node -e '
      const value = JSON.parse(require("node:fs").readFileSync(process.argv[1], "utf8"));
      const [holderRoot, contenderRoot] = process.argv.slice(2);
      const requests = Object.values(value.requests ?? {});
      const leases = Object.values(value.leases ?? {});
      const holder = requests.find((item) => item.worktreeKey === holderRoot);
      const contender = requests.find((item) => item.worktreeKey === contenderRoot);
      const holderReserved = holder && leases.some((item) =>
        item.requestId === holder.requestId &&
        ["granted", "settling"].includes(item.status));
      const contenderQueued = contender && leases.some((item) =>
        item.requestId === contender.requestId && item.status === "queued");
      process.exit(holderReserved && contenderQueued ? 0 : 1);
    ' "$journal_path" "$holder_worktree" "$contender_worktree" ||
      fail_parallel_detached_fixture \
        "contender lease was not queued while the holder drain was paused"

    parallel_detached_signal_exact KILL "$gate_pid" "$gate_start" ||
      fail_parallel_detached_fixture \
        "could not crash the holder at its exact drain identity"
    set +e
    wait "$gate_pid"
    gate_exit=$?
    set -e
    gate_pid=""
    [[ "$gate_exit" -eq 137 ]] ||
      fail_parallel_detached_fixture \
        "detached-drain holder exited ${gate_exit}, expected SIGKILL status 137"

    # Observe the whole successor by wall clock. A fixed iteration count is not
    # a time bound when every iteration inspects the process table. It also
    # creates transient processes that can make a coherent Darwin snapshot
    # report unrelated incomplete parent chains under load.
    contender_observer_started_at="$SECONDS"
    while ((
      SECONDS - contender_observer_started_at <
        detached_drain_observer_deadline_seconds
    )); do
      if ! parallel_execution_job_active \
        "$contender_pid" "$contender_jobs_file"; then
        settled=1
        break
      fi
      sleep 0.25
    done
    if [[ "$settled" -eq 0 ]] &&
      ! parallel_execution_job_active \
        "$contender_pid" "$contender_jobs_file"; then
      settled=1
    fi
    [[ "$settled" -eq 1 ]] ||
      fail_parallel_detached_fixture \
        "detached-drain successor did not settle within ${detached_drain_observer_deadline_seconds}s"
    set +e
    wait "$contender_pid"
    contender_exit=$?
    set -e
    contender_pid=""
    [[ "$contender_exit" -eq 0 ]] ||
      fail_parallel_detached_fixture \
        "detached-drain contender exited ${contender_exit}"
    [[ "$(wc -l < "$holder_dispatch_log" | tr -d '[:space:]')" -eq 1 ]] ||
      fail_parallel_detached_fixture \
        "a queued holder worker dispatched after its exact parent died"
    [[ -s "$contender_started_file" ]] ||
      fail_parallel_detached_fixture "queued external contender never started"
    [[ ! -s "$overlap_file" ]] ||
      fail_parallel_detached_fixture "scheduler released capacity while the detached child was alive"
    ! parallel_detached_process_live "$detached_pid" "$detached_start" ||
      fail_parallel_detached_fixture "detached child survived command drain"
    ! parallel_detached_process_live "$handleless_pid" "$handleless_start" ||
      fail_parallel_detached_fixture \
        "marker-free child survived successor recovery"
    recovery_completed_at_ms="$(node -e \
      'process.stdout.write(String(Date.now()))')"
    [[ "$recovery_completed_at_ms" =~ ^[1-9][0-9]*$ ]] ||
      fail_parallel_detached_fixture \
        "could not read the detached-drain recovery completion time"
    ((recovery_completed_at_ms < detached_self_exit_deadline_ms)) ||
      fail_parallel_detached_fixture \
        "successor recovery exceeded the detached child's self-exit deadline"
    ((recovery_completed_at_ms < handleless_self_exit_deadline_ms)) ||
      fail_parallel_detached_fixture \
        "successor recovery exceeded the marker-free child's self-exit deadline"
    for ((attempt = 0; attempt < 200; attempt++)); do
      if parallel_detached_worker_records_settled \
        "${holder_worker_barrier}.identities" \
        "$fixture_repo/.tmp/agent-quality-gate" &&
        parallel_detached_worker_records_settled \
          "${contender_worker_barrier}.identities" \
          "$contender_repo/.tmp/agent-quality-gate"; then
        break
      fi
      sleep 0.05
    done
    parallel_detached_worker_records_settled \
      "${holder_worker_barrier}.identities" \
      "$fixture_repo/.tmp/agent-quality-gate" ||
      fail_parallel_detached_fixture \
        "holder crash left a registered worker sentinel running"
    parallel_detached_worker_records_settled \
      "${contender_worker_barrier}.identities" \
      "$contender_repo/.tmp/agent-quality-gate" ||
      fail_parallel_detached_fixture \
        "contender completion left a registered worker sentinel running"
    parallel_detached_worker_markers_absent \
      "${holder_worker_barrier}.identities" ||
      fail_parallel_detached_fixture \
        "holder recovery left a worker command marker behind"
    parallel_detached_worker_markers_absent \
      "${contender_worker_barrier}.identities" ||
      fail_parallel_detached_fixture \
        "contender completion left a worker command marker behind"
    if [[ "$(uname -s)" == Darwin ]]; then
      grep -Fq "Darwin lineage recovery found" "$contender_output" ||
        fail_parallel_detached_fixture \
          "successor did not report exact Darwin watcher recovery"
    else
      grep -Fq \
        "A completed mapped command left descendants running; stopping them before releasing its scheduler lease." \
        "$gate_output" ||
        fail_parallel_detached_fixture \
          "parallel command did not report its detached-child drain"
    fi
    [[ -z "$(find "$fixture_lock_root" -type f \
      \( -name 'holder.cmd*' -o -name 'holder.lp1.*.cmd*' \) \
      -print 2>/dev/null)" ]] ||
      fail_parallel_detached_fixture "parallel command left its drain marker behind"
    detached_pid=""
    detached_start=""
    handleless_pid=""
    handleless_start=""
    cleanup_parallel_detached_fixture
    trap - EXIT
    [[ "$cleanup_failed" -eq 0 ]] ||
      fail_parallel_detached_fixture "detached-drain fixture cleanup did not settle"
  )
  rm -rf "$fixture_repo" "$contender_repo" "$fixture_lock_root"
}

run_parallel_detached_drain_regression

if [[ "$execution_parallel_case" == detached-drain ]]; then
  return 0
fi

# Keep the production identity contract reachable from every protected source
# in CI and from the local changed-path router.
node scripts/production-infra-identity-contract/routing.test.mjs

# PR 1492 review: prerequisite commands (install/codegen/setup) produce outputs
# the source fingerprint cannot see, so they must never be stamped or reused —
# two identical successful runs execute the preflight install twice, while a
# stampable quality command is reused on the second run.
prereq_reuse_repo="$(mktemp -d)"
(
  cd "$prereq_reuse_repo"
  git init -q
  git config user.email test@example.invalid
  git config user.name "Quality Gate Test"
  mkdir -p bin scripts/pr shared-config/src sub tools
  printf '{"name":"sub"}\n' > sub/package.json
  printf 'export const x = 1;\n' > shared-config/src/x.ts
  printf 'process.exit(0);\n' > scripts/pr/check-adr-reminder.mjs
  cat > tools/trunk <<'STUB'
#!/usr/bin/env bash
if [ "${1:-} ${2:-}" = "daemon status" ]; then
  printf 'x Daemon stopped\n'
  exit 1
fi
exit 0
STUB
  cat > bin/pnpm <<'STUB'
#!/usr/bin/env bash
if [[ "$*" == "install --frozen-lockfile" ]]; then
  echo run >> "$INSTALL_SIDE_EFFECT"
  exit 0
fi
if [[ "$*" == "--filter @mento-protocol/config build" ]]; then
  echo run >> "$BUILD_SIDE_EFFECT"
  exit 0
fi
if [[ "$*" == "skew:check" ]]; then
  echo run >> "$SKEW_SIDE_EFFECT"
  exit 0
fi
exit 0
STUB
  chmod +x bin/pnpm tools/trunk
  git add .
  git commit -qm init
  printf 'sub/package.json\nshared-config/src/x.ts\n' > changed-paths.txt
  for _ in 1 2; do
    INSTALL_SIDE_EFFECT="$prereq_reuse_repo/install-side-effect" \
      BUILD_SIDE_EFFECT="$prereq_reuse_repo/build-side-effect" \
      SKEW_SIDE_EFFECT="$prereq_reuse_repo/skew-side-effect" \
      PATH="$prereq_reuse_repo/bin:$PATH" \
      "$repo_root/scripts/agent-quality-gate.sh" \
        --changed-paths-file changed-paths.txt \
        --base HEAD \
        --run \
        --parallel 1 \
        --allow-package-script-changes \
        > "$output_file" 2>&1 ||
      fail "prerequisite-reuse fixture run failed unexpectedly"
  done
  [[ "$(wc -l < "$prereq_reuse_repo/install-side-effect" | tr -d ' ')" == "2" ]] ||
    fail "expected the preflight install to run on BOTH runs (prerequisites are never reused)"
  # The shared-config build is a quality-setup command whose dist/ output the
  # fingerprint cannot see. Phase handling and command classification both
  # keep it outside stamp reuse, so it must run on BOTH runs.
  [[ "$(wc -l < "$prereq_reuse_repo/build-side-effect" | tr -d ' ')" == "2" ]] ||
    fail "expected the quality-setup config build to run on BOTH runs (setup commands are never reused)"
  [[ "$(wc -l < "$prereq_reuse_repo/skew-side-effect" | tr -d ' ')" == "1" ]] ||
    fail "expected the quality command to be reused on the second run"
)
rm -rf "$prereq_reuse_repo"
} # end family: execution-parallel

# family: lock-drain
# Cross-run mutual exclusion: lock acquisition, stale-holder reclaim, drain
# obligations, and crash-point recovery.
run_lock_drain_family() {
arm_suite_abort_trap
# A versioned obligation carries its explicit lifecycle contract. Old
# token-only records use the verified host classifier. They never inspect a
# Darwin state path to choose a contract.
legacy_contract_fixture="$(mktemp -d)"
legacy_contract_functions="$legacy_contract_fixture/functions.sh"
for legacy_contract_function in \
  gate_lifecycle_contract_is_supported \
  gate_recovery_lifecycle_contract_is_supported \
  gate_read_condemned_record; do
  sed -n "/^${legacy_contract_function}() {$/,/^}$/p" \
    scripts/agent-quality-gate.sh >> "$legacy_contract_functions"
done
(
  set -euo pipefail
  # shellcheck disable=SC2329 # Called by the extracted record parser.
  gate_lock_token_is_wellformed() {
    [[ "${1:-}" =~ ^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$ ]]
  }
  # shellcheck disable=SC2329 # Called by the extracted record parser.
  gate_lifecycle_contract_for_host() {
    printf '%s\n' "${LEGACY_FIXTURE_HOST_CONTRACT:?}"
  }
  # shellcheck disable=SC1090 # extracted functions are the code under test
  source "$legacy_contract_functions"
  gate_condemned_record_token=""
  gate_condemned_record_lifecycle_contract=""

  old_record="$legacy_contract_fixture/old"
  printf 'fixture-old-token-1\n' > "$old_record"
  LEGACY_FIXTURE_HOST_CONTRACT=darwin-coherent-lineage-v2
  export LEGACY_FIXTURE_HOST_CONTRACT
  gate_read_condemned_record "$old_record"
  [[ "$gate_condemned_record_token" == fixture-old-token-1 ]]
  [[ "$gate_condemned_record_lifecycle_contract" == darwin-coherent-lineage-v2 ]]

  legacy_record="$legacy_contract_fixture/legacy"
  printf 'agentqg-condemned-v2|fixture-legacy-token-1|darwin-unique-lineage-v1\n' \
    > "$legacy_record"
  gate_read_condemned_record "$legacy_record"
  [[ "$gate_condemned_record_token" == fixture-legacy-token-1 ]]
  [[ "$gate_condemned_record_lifecycle_contract" == darwin-unique-lineage-v1 ]]
  gate_recovery_lifecycle_contract_is_supported darwin-unique-lineage-v1
  if gate_lifecycle_contract_is_supported darwin-unique-lineage-v1; then
    exit 1
  fi

  new_record="$legacy_contract_fixture/new"
  printf 'agentqg-condemned-v2|fixture-new-token-1|portable-marker-v1\n' \
    > "$new_record"
  gate_read_condemned_record "$new_record"
  [[ "$gate_condemned_record_token" == fixture-new-token-1 ]]
  [[ "$gate_condemned_record_lifecycle_contract" == portable-marker-v1 ]]

  request_record="$legacy_contract_fixture/request"
  printf 'agentqg-condemned-v2|fixture-request-token-1|request-marker-empty-v1\n' \
    > "$request_record"
  gate_read_condemned_record "$request_record"
  [[ "$gate_condemned_record_token" == fixture-request-token-1 ]]
  [[ "$gate_condemned_record_lifecycle_contract" == request-marker-empty-v1 ]]
  gate_recovery_lifecycle_contract_is_supported request-marker-empty-v1
  if gate_lifecycle_contract_is_supported request-marker-empty-v1; then
    exit 1
  fi

  malformed_record="$legacy_contract_fixture/malformed"
  printf 'agentqg-condemned-v2|fixture-token-1|unknown-v1\n' \
    > "$malformed_record"
  ! gate_read_condemned_record "$malformed_record"
)
rm -rf "$legacy_contract_fixture"

# A reclaimed coordinator owner names only its aggregate generation marker.
# Darwin rejects owner-record-only recovery because a descriptor-closing,
# untagged descendant can make that marker look empty without exact
# per-command lineage.
# Portable hosts retain their marker recovery contract so the recovering gate
# can stop holders from the crashed generation. Ordinary owner records retain
# the current host contract.
coordinator_owner_contract_fixture="$(mktemp -d)"
coordinator_owner_contract_functions="$coordinator_owner_contract_fixture/functions.sh"
for coordinator_owner_contract_function in \
  gate_lock_field_from_text \
  gate_lock_current_user_authority_token_from_snapshot \
  gate_lock_recovery_contract_from_owner_snapshot \
  gate_lock_current_user_authority_and_recovery_contract_from_snapshot; do
  sed -n "/^${coordinator_owner_contract_function}() {$/,/^}$/p" \
    scripts/agent-quality-gate.sh >> "$coordinator_owner_contract_functions"
done
if ! /bin/bash -c '
  set -euo pipefail
  source "$1"
  current_uid="$(id -u)"
  coordinator_snapshot="pid=123
uid=${current_uid}
coordinator_start_utc=coordinator-start
coordinator_token=fixture-coordinator-1-1
token=coordinator-owner-v1"
  gate_host_lifecycle_contract=portable-marker-v1
  pair="$(
    gate_lock_current_user_authority_and_recovery_contract_from_snapshot \
      "$coordinator_snapshot"
  )"
  [[ "$pair" == $'"'"'fixture-coordinator-1-1\nportable-marker-v1'"'"' ]]

  gate_host_lifecycle_contract=darwin-coherent-lineage-v2
  if pair="$(
    gate_lock_current_user_authority_and_recovery_contract_from_snapshot \
      "$coordinator_snapshot" 2> "$2"
  )"; then
    pair_status=0
  else
    pair_status=$?
  fi
  [[ "$pair_status" -eq 2 ]]
  [[ -z "$pair" ]]
  grep -Fq \
    "Darwin coordinator-owner recovery has no exact per-command lineage evidence" \
    "$2"

  ordinary_snapshot="pid=124
uid=${current_uid}
token=fixture-owner-1-1"
  pair="$(
    gate_lock_current_user_authority_and_recovery_contract_from_snapshot \
      "$ordinary_snapshot"
  )"
  [[ "$pair" == $'"'"'fixture-owner-1-1\ndarwin-coherent-lineage-v2'"'"' ]]

  untyped_snapshot="pid=125
uid=${current_uid}
coordinator_start_utc=coordinator-start
coordinator_token=fixture-untyped-1-1
token=ordinary-owner-v1"
  pair="$(
    gate_lock_current_user_authority_and_recovery_contract_from_snapshot \
      "$untyped_snapshot"
  )"
  [[ "$pair" == $'"'"'fixture-untyped-1-1\ndarwin-coherent-lineage-v2'"'"' ]]
' coordinator-owner-contract-test "$coordinator_owner_contract_functions" \
  "$coordinator_owner_contract_fixture/error"; then
  rm -rf "$coordinator_owner_contract_fixture"
  fail "coordinator owner recovery contract classification failed"
fi
rm -rf "$coordinator_owner_contract_fixture"

if grep -n -A6 -B2 'gate_darwin_lineage_state_exists' \
  scripts/agent-quality-gate.sh |
  grep -Eq 'lifecycle_contract=.*(darwin|portable)'; then
  fail "lifecycle contract selection still depends on Darwin state-file presence"
fi
grep -Fq 'required Darwin process-lineage evidence is missing' \
  scripts/agent-quality-gate.sh ||
  fail "a Darwin lifecycle contract with missing state does not fail closed"

legacy_release_order="$(
  sed -n '/^drain_completed_command_identity() {$/,/^}$/p' \
    scripts/agent-quality-gate.sh |
    awk '
      /rm -f "\$\{condemned_dir\}\/\$\{token\}"/ && remove == 0 { remove = NR }
      /gate_darwin_lineage_discard_settled "\$token"/ && discard == 0 { discard = NR }
      END { if (remove > 0 && discard > remove) print "ok" }
    '
)"
[[ "$legacy_release_order" == ok ]] ||
  fail "active legacy cleanup must remove its obligation before discarding Darwin state"

stale_release_order="$(
  sed -n '/^drain_condemned_runs() {$/,/^}$/p' scripts/agent-quality-gate.sh |
    awk '
      /rm -f "\$claimed"/ && remove == 0 { remove = NR }
      /gate_darwin_lineage_discard_settled/ && discard == 0 { discard = NR }
      END { if (remove > 0 && discard > remove) print "ok" }
    '
)"
[[ "$stale_release_order" == ok ]] ||
  fail "stale legacy cleanup must remove its obligation before discarding Darwin state"

stale_request_release_order="$(
  sed -n '/^drain_condemned_runs() {$/,/^}$/p' scripts/agent-quality-gate.sh |
    awk '
      /rm -f "\$claimed"/ && remove == 0 { remove = NR }
      /gate_run_discard_marker_exact/ && discard == 0 { discard = NR }
      END { if (remove > 0 && discard > remove) print "ok" }
    '
)"
[[ "$stale_request_release_order" == ok ]] ||
  fail "stale request cleanup must remove its obligation before discarding marker state"

coordinator_request_release_order="$(
  sed -n '/^gate_coordinator_recover_stale_obligations() {$/,/^}$/p' \
    scripts/gate/quality-gate-coordinator-support.sh |
    awk '
      /gate_coordinator_cli ack-drain/ && acknowledge == 0 { acknowledge = NR }
      /gate_run_discard_marker_exact/ && discard == 0 { discard = NR }
      END { if (acknowledge > 0 && discard > acknowledge) print "ok" }
    '
)"
[[ "$coordinator_request_release_order" == ok ]] ||
  fail "coordinator recovery must acknowledge every command before discarding request marker state"
gate_test_outer_pid="$$"
gate_test_executor_pid="$PPID"
gate_test_signal_shell_pid="$gate_test_outer_pid"
gate_test_signal_trace_file="${GATE_TEST_SIGNAL_TRACE_FILE:-}"
gate_test_captured_shell_pid=""
gate_test_captured_start=""
gate_test_captured_parent=""

gate_test_process_start() {
  local pid="$1"
  [[ "$pid" =~ ^[0-9]+$ ]] || return 1
  TZ=UTC LC_ALL=C LANG=C ps -p "$pid" -o lstart= 2>/dev/null | head -n1 || true
}

gate_test_process_parent() {
  local pid="$1"
  [[ "$pid" =~ ^[0-9]+$ ]] || return 1
  TZ=UTC LC_ALL=C LANG=C ps -p "$pid" -o ppid= 2>/dev/null |
    awk 'NF { print $1; exit }' || true
}

gate_test_process_state() {
  local pid="$1"
  [[ "$pid" =~ ^[0-9]+$ ]] || return 1
  TZ=UTC LC_ALL=C LANG=C ps -p "$pid" -o stat= 2>/dev/null |
    awk 'NF { print $1; exit }' || true
}

gate_test_process_is_expected() {
  local pid="$1"
  local expected_start="$2"
  local expected_parent="$3"
  local current_start current_parent
  [[ "$pid" =~ ^[0-9]+$ && -n "$expected_start" && "$expected_parent" =~ ^[0-9]+$ ]] || return 1
  current_start="$(gate_test_process_start "$pid")"
  [[ -n "$current_start" && "$current_start" == "$expected_start" ]] || return 1
  current_parent="$(gate_test_process_parent "$pid")"
  [[ -n "$current_parent" && "$current_parent" == "$expected_parent" ]] || return 1
}

gate_test_process_has_start() {
  local pid="$1"
  local expected_start="$2"
  local current_start
  [[ "$pid" =~ ^[0-9]+$ && -n "$expected_start" ]] || return 1
  current_start="$(gate_test_process_start "$pid")"
  [[ -n "$current_start" && "$current_start" == "$expected_start" ]]
}

# Return success only while the recorded fixture identity can still execute. A
# zombie can retain the same PID and start time forever under a non-reaping PID
# 1, but it cannot run fixture code. An unreadable state stays live so cleanup
# fails closed instead of claiming an uncertain process absent. The production
# orphan drain applies the same rule only after it revalidates the exact PID and
# start time; lock-holder reclamation remains separate.
gate_test_process_has_live_start() {
  local pid="$1"
  local expected_start="$2"
  local current_start current_state
  [[ "$pid" =~ ^[0-9]+$ && -n "$expected_start" ]] || return 1
  current_start="$(gate_test_process_start "$pid")"
  [[ -n "$current_start" && "$current_start" == "$expected_start" ]] || return 1
  current_state="$(gate_test_process_state "$pid")"
  [[ -z "$current_state" || "$current_state" != Z* ]]
}

# Bash 3.2 has no nameref or safe command-substitution assignment to caller
# variables. Publish the exact identity through these family-scoped outputs.
gate_test_capture_identity() {
  local pid="$1"
  local expected_parent="${2:-}"
  gate_test_captured_start="$(gate_test_process_start "$pid")"
  gate_test_captured_parent="$(gate_test_process_parent "$pid")"
  [[ -n "$gate_test_captured_start" && "$gate_test_captured_parent" =~ ^[0-9]+$ ]] || return 1
  [[ -z "$expected_parent" || "$gate_test_captured_parent" == "$expected_parent" ]] || return 1
  gate_test_process_is_expected \
    "$pid" "$gate_test_captured_start" "$gate_test_captured_parent"
}

gate_test_trace_signal() {
  local event="$1"
  local label="$2"
  local signal="$3"
  local target="$4"
  local expected_start="${5:-}"
  local current_start="${6:-}"
  local expected_parent="${7:-}"
  local current_parent="${8:-}"
  [[ -n "$gate_test_signal_trace_file" ]] || return 0
  printf '%s|event=%s|label=%s|sender=%s|target=%s|signal=%s|expected_start=%s|current_start=%s|expected_ppid=%s|current_ppid=%s\n' \
    "$(date +%s)" "$event" "$label" "$gate_test_signal_shell_pid" "$target" "$signal" \
    "$expected_start" "$current_start" "$expected_parent" "$current_parent" \
    >> "$gate_test_signal_trace_file" 2>/dev/null || true
}

gate_test_pid_is_protected() {
  local pid="$1"
  [[ "$pid" == "$gate_test_outer_pid" ||
    "$pid" == "$gate_test_executor_pid" ||
    "$pid" == "$gate_test_signal_shell_pid" ]]
}

# Return 0 after sending the signal, 1 when the recorded process is already
# gone, and 2 when the target cannot be proved safe. The final identity read is
# deliberately adjacent to kill: macOS has no pidfd, so this is the narrowest
# fail-closed selector available to the Bash 3.2 test runtime.
gate_test_signal_expected() {
  local label="$1"
  local signal="$2"
  local pid="$3"
  local expected_start="$4"
  local expected_parent="$5"
  local current_start current_parent
  case "$signal" in
    TERM|KILL|STOP|CONT) ;;
    *) return 2 ;;
  esac
  [[ "$pid" =~ ^[0-9]+$ && -n "$expected_start" && "$expected_parent" =~ ^[0-9]+$ ]] || return 2
  if gate_test_pid_is_protected "$pid"; then
    gate_test_trace_signal refused-protected "$label" "$signal" "$pid" "$expected_start"
    return 2
  fi
  current_start="$(gate_test_process_start "$pid")"
  if [[ -z "$current_start" ]]; then
    gate_test_trace_signal already-gone "$label" "$signal" "$pid" "$expected_start"
    return 1
  fi
  current_parent="$(gate_test_process_parent "$pid")"
  if [[ "$current_start" != "$expected_start" ||
    "$current_parent" != "$expected_parent" ]]; then
    gate_test_trace_signal refused-mismatch "$label" "$signal" "$pid" \
      "$expected_start" "$current_start" "$expected_parent" "$current_parent"
    return 2
  fi
  gate_test_trace_signal send "$label" "$signal" "$pid" \
    "$expected_start" "$current_start" "$expected_parent" "$current_parent"
  kill "-$signal" "$pid" 2>/dev/null || return 1
}

# Use this for an exact process that was reparented after capture. Keep the
# recorded start time, then bind the signal to its current parent immediately
# before the final identity check and signal.
# shellcheck disable=SC2329 # invoked by the EXIT cleanup below
gate_test_signal_with_current_parent() {
  local label="$1"
  local signal="$2"
  local pid="$3"
  local expected_start="$4"
  local current_parent
  current_parent="$(gate_test_process_parent "$pid")"
  [[ "$current_parent" =~ ^[0-9]+$ ]] || return 2
  gate_test_signal_expected \
    "$label" "$signal" "$pid" "$expected_start" "$current_parent"
}

# Bash 3.2 has no BASHPID, while $$ and PPID keep the outer shell's values in a
# parenthesized subshell. A directly launched sh sees the real current shell as
# its parent and writes that PID through a path already owned by this fixture.
gate_test_capture_current_shell_pid() {
  local capture_file="$1"
  gate_test_captured_shell_pid=""
  /bin/sh -c 'printf "%s\n" "$PPID"' > "$capture_file" || return 1
  IFS= read -r gate_test_captured_shell_pid < "$capture_file" || return 1
  rm -f "$capture_file"
  [[ "$gate_test_captured_shell_pid" =~ ^[0-9]+$ ]]
}

# shellcheck disable=SC2329 # invoked by the opt-in TERM traps below
gate_test_on_term() {
  local label="$1"
  local shell_pid="$2"
  gate_test_trace_signal received "$label" TERM "$shell_pid"
  trap - TERM
  kill -TERM "$shell_pid"
}

if [[ -n "$gate_test_signal_trace_file" ]]; then
  trap 'gate_test_on_term outer-suite "$gate_test_outer_pid"' TERM
fi
# This family pins the legacy whole-run lock. The coordinator has separate
# protocol and integration coverage and must not change these lock fixtures.
# shellcheck disable=SC2031 # this family intentionally sets its own legacy mode
export AGENT_QUALITY_GATE_COORDINATOR=0

# Exercise the real no-lock fallback in a separate Bash process. Its children
# must have that process's $$ as PPID. A parenthesized Bash 3.2 subshell keeps
# the outer $$ value and cannot prove the direct-child boundary used here.
no_lock_fallback_fixture_dir="$(mktemp -d)"
cat > "$no_lock_fallback_fixture_dir/process-fixture.cjs" <<'NODE'
const fs = require("node:fs");
const { spawn } = require("node:child_process");

const [mode, label, tracePath, childPidPath, readyPath, memberReadyPath, lifetime] =
  process.argv.slice(2);

function trace(event) {
  fs.appendFileSync(tracePath, `${label}:${event}\n`);
}

process.on("exit", () => trace("EXIT"));

if (mode === "member") {
  process.on("SIGTERM", () => {
    trace("TERM");
    process.exit(0);
  });
  fs.writeFileSync(readyPath, "ready\n");
  setInterval(() => {}, 1000);
} else if (mode === "leaf") {
  process.on("SIGTERM", () => trace("TERM"));
  fs.writeFileSync(readyPath, "ready\n");
  setTimeout(() => process.exit(0), Number(lifetime));
} else if (mode === "parent") {
  process.on("SIGTERM", () => trace("TERM"));
  const member = spawn(
    process.execPath,
    [
      __filename,
      "member",
      `${label}-member`,
      tracePath,
      "unused",
      memberReadyPath,
      "unused",
      "unused",
    ],
    { stdio: "ignore" },
  );
  process.on("SIGUSR1", () => {
    member.kill("SIGTERM");
    setTimeout(() => process.exit(0), 100);
  });
  fs.writeFileSync(childPidPath, `${member.pid}\n`);
  fs.writeFileSync(readyPath, "ready\n");
  setInterval(() => {}, 1000);
} else {
  throw new Error(`unknown fixture mode: ${mode}`);
}
NODE

cat > "$no_lock_fallback_fixture_dir/harness.sh" <<'HARNESS'
#!/usr/bin/env bash
set -euo pipefail

gate_source="$1"
scratch="$2"
fixture="$scratch/process-fixture.cjs"
node_path="$(node -p 'process.execPath')"
[[ -x "$node_path" ]] || exit 2
root_pid=""
root_runtime=""
root_member_pid=""
root_member_runtime=""
plain_pid=""
plain_runtime=""
worker_pid=""
worker_runtime=""
worker_member_pid=""
worker_member_runtime=""

extract_gate_function() {
  local function_name="$1"
  sed -n "/^${function_name}() {$/,/^}$/p" "$gate_source"
}

extracted_functions="$scratch/extracted-functions.sh"
: > "$extracted_functions"
for function_name in \
  collect_process_tree \
  gate_lock_process_snapshot \
  gate_lock_normalize_process_start \
  gate_lock_process_start \
  gate_lock_process_runtime_start \
  gate_lock_process_signal_probe \
  teardown_no_lock_settle_known_processes; do
  extract_gate_function "$function_name" >> "$extracted_functions"
done
# shellcheck disable=SC1090 # the test extracts these functions from the gate under test
source "$extracted_functions"
gate_darwin_lineage_host_platform="$(/usr/bin/uname -s)"

test_fail() {
  printf 'no-lock fallback regression failed: %s\n' "$*" >&2
  exit 1
}

process_parent() {
  ps -o ppid= -p "$1" 2>/dev/null | awk 'NF { print $1; exit }' || true
}

process_group() {
  ps -o pgid= -p "$1" 2>/dev/null | awk 'NF { print $1; exit }' || true
}

process_state() {
  ps -o stat= -p "$1" 2>/dev/null | awk 'NF { print $1; exit }' || true
}

process_has_live_runtime() {
  local pid="$1"
  local expected_runtime="$2"
  local current_runtime state
  current_runtime="$(gate_lock_process_runtime_start "$pid")"
  [[ -n "$current_runtime" && "$current_runtime" == "$expected_runtime" ]] || return 1
  state="$(process_state "$pid")"
  [[ -z "$state" || "$state" != Z* ]]
}

wait_for_file() {
  local path="$1"
  local attempt=0
  while [[ ! -e "$path" && "$attempt" -lt 200 ]]; do
    sleep 0.05
    attempt=$((attempt + 1))
  done
  [[ -e "$path" ]] || test_fail "fixture did not create ${path}"
}

wait_until_not_live() {
  local label="$1"
  local pid="$2"
  local expected_runtime="$3"
  local attempt=0
  while process_has_live_runtime "$pid" "$expected_runtime" &&
    [[ "$attempt" -lt 80 ]]; do
    sleep 0.05
    attempt=$((attempt + 1))
  done
  ! process_has_live_runtime "$pid" "$expected_runtime" ||
    test_fail "${label} leaked its recorded process generation"
}

assert_live() {
  local label="$1"
  local pid="$2"
  local expected_runtime="$3"
  process_has_live_runtime "$pid" "$expected_runtime" ||
    test_fail "${label} lost its recorded process generation"
}

assert_trace() {
  local path="$1"
  local expected="$2"
  grep -Fxq "$expected" "$path" ||
    test_fail "${path} does not contain ${expected}"
}

assert_no_trace() {
  local path="$1"
  local unexpected="$2"
  ! grep -Fxq "$unexpected" "$path" 2>/dev/null ||
    test_fail "${path} unexpectedly contains ${unexpected}"
}

signal_exact_direct_child() {
  local signal="$1"
  local pid="$2"
  local expected_runtime="$3"
  local parent_before parent_after current_runtime
  [[ "$pid" =~ ^[1-9][0-9]*$ && -n "$expected_runtime" ]] || return 1
  parent_before="$(process_parent "$pid")"
  current_runtime="$(gate_lock_process_runtime_start "$pid")"
  parent_after="$(process_parent "$pid")"
  [[ "$current_runtime" == "$expected_runtime" &&
    "$parent_before" == "$$" && "$parent_after" == "$$" ]] || return 1
  kill "-${signal}" "$pid" 2>/dev/null
}

cleanup_pair() {
  local parent_pid="$1"
  local parent_runtime="$2"
  local member_pid="$3"
  local member_runtime="$4"
  local member_parent_before member_parent_after member_current_runtime
  [[ -n "$parent_pid" && -n "$parent_runtime" ]] || return 0
  if [[ -n "$member_pid" && -n "$member_runtime" ]] &&
    process_has_live_runtime "$parent_pid" "$parent_runtime"; then
    member_parent_before="$(process_parent "$member_pid")"
    member_current_runtime="$(gate_lock_process_runtime_start "$member_pid")"
    member_parent_after="$(process_parent "$member_pid")"
    if [[ "$member_current_runtime" == "$member_runtime" &&
      "$member_parent_before" == "$parent_pid" &&
      "$member_parent_after" == "$parent_pid" ]]; then
      kill -TERM "$member_pid" 2>/dev/null || true
    fi
  fi
  signal_exact_direct_child USR1 "$parent_pid" "$parent_runtime" || true
  for _ in {1..20}; do
    process_has_live_runtime "$parent_pid" "$parent_runtime" || break
    sleep 0.05
  done
  signal_exact_direct_child KILL "$parent_pid" "$parent_runtime" || true
  wait "$parent_pid" 2>/dev/null || true
}

cleanup_harness() {
  local status=$?
  trap - EXIT
  set +e
  cleanup_pair \
    "$root_pid" "$root_runtime" "$root_member_pid" "$root_member_runtime"
  cleanup_pair \
    "$worker_pid" "$worker_runtime" "$worker_member_pid" "$worker_member_runtime"
  signal_exact_direct_child KILL "$plain_pid" "$plain_runtime" || true
  [[ -n "$plain_pid" ]] && wait "$plain_pid" 2>/dev/null || true
  exit "$status"
}
trap cleanup_harness EXIT

for function_name in \
  collect_process_tree \
  gate_lock_process_runtime_start \
  gate_lock_process_signal_probe \
  teardown_no_lock_settle_known_processes; do
  declare -F "$function_name" >/dev/null ||
    test_fail "could not extract ${function_name}"
done

# A wrong root generation and a live non-direct descendant must remain
# untouched. The valid root then exercises the tree snapshot, TERM, KILL,
# direct-child reap, and exact-generation settlement.
root_trace="$scratch/root.trace"
root_child_pid_file="$scratch/root-child.pid"
root_ready="$scratch/root.ready"
root_member_ready="$scratch/root-member.ready"
: > "$root_trace"
"$node_path" "$fixture" parent root "$root_trace" "$root_child_pid_file" \
  "$root_ready" "$root_member_ready" unused &
root_pid=$!
wait_for_file "$root_ready"
wait_for_file "$root_member_ready"
root_member_pid="$(cat "$root_child_pid_file")"
root_runtime="$(gate_lock_process_runtime_start "$root_pid")"
root_member_runtime="$(gate_lock_process_runtime_start "$root_member_pid")"
[[ -n "$root_runtime" && -n "$root_member_runtime" ]] ||
  test_fail "could not capture the root fixture runtime identities"
root_parent="$(process_parent "$root_pid")"
root_member_parent="$(process_parent "$root_member_pid")"
[[ "$root_parent" == "$$" ]] ||
  test_fail "root fixture parent is ${root_parent:-missing}, expected $$"
[[ "$root_member_parent" == "$root_pid" ]] ||
  test_fail "root fixture member parent is ${root_member_parent:-missing}, expected $root_pid"

set +e
teardown_no_lock_settle_known_processes \
  root "$root_pid" "${root_runtime}-wrong" \
  root "$root_member_pid" "$root_member_runtime" \
  2> "$scratch/root-rejected.err"
root_rejected_status=$?
set -e
[[ "$root_rejected_status" -eq 2 ]] ||
  test_fail "runtime/direct-child rejection returned ${root_rejected_status}"
assert_live "rejected root" "$root_pid" "$root_runtime"
assert_live "rejected root member" "$root_member_pid" "$root_member_runtime"
assert_no_trace "$root_trace" "root:TERM"
assert_no_trace "$root_trace" "root-member:TERM"

if [[ "$gate_darwin_lineage_host_platform" == Darwin ]]; then
  set +e
  teardown_no_lock_settle_known_processes \
    root "$root_pid" "$root_runtime" 2> "$scratch/root-darwin.err"
  root_darwin_status=$?
  set -e
  [[ "$root_darwin_status" -eq 2 ]] ||
    test_fail "Darwin root fallback returned ${root_darwin_status}"
  grep -Fq "portable no-lock process fallback is unsafe on Darwin" \
    "$scratch/root-darwin.err" ||
    test_fail "Darwin root fallback did not explain its refusal"
  assert_live "Darwin rejected root" "$root_pid" "$root_runtime"
  assert_live \
    "Darwin rejected root member" "$root_member_pid" "$root_member_runtime"
  assert_no_trace "$root_trace" "root:TERM"
  assert_no_trace "$root_trace" "root-member:TERM"
  cleanup_pair \
    "$root_pid" "$root_runtime" "$root_member_pid" "$root_member_runtime"
  wait_until_not_live "Darwin root" "$root_pid" "$root_runtime"
  wait_until_not_live \
    "Darwin root member" "$root_member_pid" "$root_member_runtime"
  root_pid=""
  root_runtime=""
  root_member_pid=""
  root_member_runtime=""
else
  teardown_no_lock_settle_known_processes root "$root_pid" "$root_runtime"
  assert_trace "$root_trace" "root:TERM"
  assert_trace "$root_trace" "root-member:TERM"
  assert_trace "$root_trace" "root-member:EXIT"
  assert_no_trace "$root_trace" "root:EXIT"
  wait_until_not_live "root" "$root_pid" "$root_runtime"
  wait_until_not_live "root member" "$root_member_pid" "$root_member_runtime"
fi

# A direct child in the harness process group is not a worker-group leader.
# The fallback must reject it and return within its bound without waiting for
# the untouched child to exit.
plain_trace="$scratch/plain.trace"
plain_ready="$scratch/plain.ready"
: > "$plain_trace"
set +m
"$node_path" "$fixture" leaf plain "$plain_trace" unused "$plain_ready" \
  unused 30000 &
plain_pid=$!
wait_for_file "$plain_ready"
plain_runtime="$(gate_lock_process_runtime_start "$plain_pid")"
[[ -n "$plain_runtime" ]] || test_fail "could not capture the plain worker runtime"
[[ "$(process_parent "$plain_pid")" == "$$" ]] ||
  test_fail "plain worker fixture is not a direct harness child"
[[ "$(process_group "$plain_pid")" != "$plain_pid" ]] ||
  test_fail "plain worker fixture unexpectedly owns a process group"
plain_started_at="$(date +%s)"
set +e
teardown_no_lock_settle_known_processes worker "$plain_pid" "$plain_runtime" \
  2> "$scratch/plain-rejected.err"
plain_rejected_status=$?
set -e
plain_elapsed=$(($(date +%s) - plain_started_at))
[[ "$plain_rejected_status" -eq 2 ]] ||
  test_fail "worker-group rejection returned ${plain_rejected_status}"
[[ "$plain_elapsed" -le 5 ]] ||
  test_fail "worker-group rejection blocked for ${plain_elapsed}s"
assert_live "plain worker" "$plain_pid" "$plain_runtime"
assert_no_trace "$plain_trace" "plain:TERM"
signal_exact_direct_child KILL "$plain_pid" "$plain_runtime" ||
  test_fail "could not clean up the rejected plain worker"
wait "$plain_pid" 2>/dev/null || true
wait_until_not_live "plain worker" "$plain_pid" "$plain_runtime"
plain_pid=""
plain_runtime=""

# Job control gives this direct child a process group whose ID is its PID. Its
# member inherits that group. A wrong generation leaves the group untouched;
# the valid record settles both exact generations and reaps the direct leader.
worker_trace="$scratch/worker.trace"
worker_child_pid_file="$scratch/worker-child.pid"
worker_ready="$scratch/worker.ready"
worker_member_ready="$scratch/worker-member.ready"
: > "$worker_trace"
set -m
"$node_path" "$fixture" parent worker "$worker_trace" "$worker_child_pid_file" \
  "$worker_ready" "$worker_member_ready" unused &
worker_pid=$!
set +m
wait_for_file "$worker_ready"
wait_for_file "$worker_member_ready"
worker_member_pid="$(cat "$worker_child_pid_file")"
worker_runtime="$(gate_lock_process_runtime_start "$worker_pid")"
worker_member_runtime="$(gate_lock_process_runtime_start "$worker_member_pid")"
[[ -n "$worker_runtime" && -n "$worker_member_runtime" ]] ||
  test_fail "could not capture the worker fixture runtime identities"
worker_parent="$(process_parent "$worker_pid")"
worker_member_parent="$(process_parent "$worker_member_pid")"
[[ "$worker_parent" == "$$" ]] ||
  test_fail "worker fixture parent is ${worker_parent:-missing}, expected $$"
[[ "$(process_group "$worker_pid")" == "$worker_pid" ]] ||
  test_fail "worker fixture does not own its process group"
[[ "$(process_group "$worker_member_pid")" == "$worker_pid" ]] ||
  test_fail "worker fixture member is outside the recorded process group (parent ${worker_member_parent:-missing})"

set +e
teardown_no_lock_settle_known_processes \
  worker "$worker_pid" "${worker_runtime}-wrong"
worker_wrong_status=$?
set -e
if [[ "$gate_darwin_lineage_host_platform" == Darwin ]]; then
  [[ "$worker_wrong_status" -eq 2 ]] ||
    test_fail "Darwin worker fallback returned ${worker_wrong_status}"
else
  [[ "$worker_wrong_status" -eq 0 ]] ||
    test_fail "wrong-generation worker fallback returned ${worker_wrong_status}"
fi
assert_live "wrong-generation worker" "$worker_pid" "$worker_runtime"
assert_live \
  "wrong-generation worker member" "$worker_member_pid" "$worker_member_runtime"
assert_no_trace "$worker_trace" "worker:TERM"
assert_no_trace "$worker_trace" "worker-member:TERM"

if [[ "$gate_darwin_lineage_host_platform" == Darwin ]]; then
  set +e
  teardown_no_lock_settle_known_processes \
    worker "$worker_pid" "$worker_runtime" 2> "$scratch/worker-darwin.err"
  worker_darwin_status=$?
  set -e
  [[ "$worker_darwin_status" -eq 2 ]] ||
    test_fail "Darwin worker fallback returned ${worker_darwin_status}"
  grep -Fq "portable no-lock process fallback is unsafe on Darwin" \
    "$scratch/worker-darwin.err" ||
    test_fail "Darwin worker fallback did not explain its refusal"
  assert_live "Darwin rejected worker" "$worker_pid" "$worker_runtime"
  assert_live \
    "Darwin rejected worker member" "$worker_member_pid" "$worker_member_runtime"
  assert_no_trace "$worker_trace" "worker:TERM"
  assert_no_trace "$worker_trace" "worker-member:TERM"
  cleanup_pair \
    "$worker_pid" "$worker_runtime" \
    "$worker_member_pid" "$worker_member_runtime"
  wait_until_not_live "Darwin worker" "$worker_pid" "$worker_runtime"
  wait_until_not_live \
    "Darwin worker member" "$worker_member_pid" "$worker_member_runtime"
  worker_pid=""
  worker_runtime=""
  worker_member_pid=""
  worker_member_runtime=""
else
  teardown_no_lock_settle_known_processes \
    worker "$worker_pid" "$worker_runtime"
  assert_trace "$worker_trace" "worker:TERM"
  assert_trace "$worker_trace" "worker-member:TERM"
  assert_trace "$worker_trace" "worker-member:EXIT"
  assert_no_trace "$worker_trace" "worker:EXIT"
  wait_until_not_live "worker" "$worker_pid" "$worker_runtime"
  wait_until_not_live \
    "worker member" "$worker_member_pid" "$worker_member_runtime"
fi
HARNESS
chmod +x "$no_lock_fallback_fixture_dir/harness.sh"
if ! /bin/bash "$no_lock_fallback_fixture_dir/harness.sh" \
  "$repo_root/scripts/agent-quality-gate.sh" \
  "$no_lock_fallback_fixture_dir" > "$output_file" 2>&1; then
  fail "controlled no-lock fallback regressions failed"
fi
rm -rf "$no_lock_fallback_fixture_dir"
no_lock_fallback_fixture_dir=""

# --- Cross-run mutual exclusion (GitHub issue #1802) -------------------------
# Two gate runs on one machine starve each other, and the pre-push hook starts
# one of its own while a manual run is still going, so `--run` takes a
# machine-wide mkdir lock. What has to hold: a live holder makes the second run
# wait rather than race, a holder that was killed never wedges the next run,
# and both escape hatches (--no-lock, an inherited nested-run marker) still
# start immediately.
gate_test_write_inert_darwin_lineage_state() {
  local lock_root="$1"
  local token="$2"
  local lineage_root state_path now

  [[ "$(/usr/bin/uname -s)" == Darwin ]] || return 0
  lineage_root="${lock_root}/lineage-v1-u$(id -u)"
  state_path="${lineage_root}/lineage.${token}.json"
  now="$(date +%s)000"
  (umask 077 && mkdir -p "$lineage_root")
  chmod 700 "$lineage_root"
  [[ ! -e "$state_path" && ! -L "$state_path" ]] ||
    fail "the synthetic Darwin lineage state already exists: ${state_path}"
  (
    umask 077
    printf '%s\n' \
      "{\"schema\":\"agentqg-darwin-lineage-v4\",\"lifecycleContract\":\"darwin-coherent-lineage-v2\",\"token\":\"${token}\",\"bootId\":\"pid1-1-0-1\",\"baseline\":[],\"root\":null,\"launcher\":null,\"tombstones\":[],\"settledAt\":${now},\"settledReason\":\"verified-unbound-abandonment\",\"settlementProof\":null,\"createdAt\":${now},\"revision\":1}" \
      > "$state_path"
  )
  chmod 600 "$state_path"
}

gate_test_darwin_node_bin=""
gate_test_resolve_darwin_node_bin() {
  [[ "$(/usr/bin/uname -s)" == Darwin ]] || return 0
  if [[ -z "$gate_test_darwin_node_bin" ]]; then
    gate_test_darwin_node_bin="$(node -p 'process.execPath')" || return 2
  fi
  [[ "$gate_test_darwin_node_bin" == /* &&
    -f "$gate_test_darwin_node_bin" && ! -L "$gate_test_darwin_node_bin" &&
    -x "$gate_test_darwin_node_bin" ]]
}

gate_test_prepare_live_darwin_lineage_state() {
  local lock_root="$1"
  local token="$2"
  local scratch="$3"
  local lineage_root state_path

  [[ "$(/usr/bin/uname -s)" == Darwin ]] || return 0
  gate_test_resolve_darwin_node_bin || return 2
  lineage_root="${lock_root}/lineage-v1-u$(id -u)"
  state_path="${lineage_root}/lineage.${token}.json"
  (umask 077 && mkdir -p "$lineage_root" "$scratch")
  chmod 700 "$lineage_root" "$scratch"
  "$gate_test_darwin_node_bin" \
    "$repo_root/scripts/gate/darwin-process-lineage.mjs" prepare \
    --state "$state_path" --scratch "$scratch" --token "$token" \
    >/dev/null
}

gate_test_bind_live_darwin_lineage_state() {
  local lock_root="$1"
  local token="$2"
  local scratch="$3"
  local pid="$4"
  local parent_pid="$5"
  local state_path

  [[ "$(/usr/bin/uname -s)" == Darwin ]] || return 0
  gate_test_resolve_darwin_node_bin || return 2
  state_path="${lock_root}/lineage-v1-u$(id -u)/lineage.${token}.json"
  "$gate_test_darwin_node_bin" \
    "$repo_root/scripts/gate/darwin-process-lineage.mjs" bind \
    --state "$state_path" --scratch "$scratch" \
    --pid "$pid" --parent-pid "$parent_pid" >/dev/null
}

gate_test_write_portable_condemned_record() {
  local lock_root="$1"
  local token="$2"
  mkdir -p "$lock_root/condemned.d"
  printf 'agentqg-condemned-v2|%s|portable-marker-v1\n' "$token" \
    > "$lock_root/condemned.d/$token"
}

gate_lock_repo="$(mktemp -d)"
gate_lock_root="$(mktemp -d)"
(
  cd "$gate_lock_repo"
  git init -q
  git config user.email test@example.invalid
  git config user.name "Quality Gate Test"
  printf 'fixture\n' > fixture.txt
  mkdir -p tools
  cat > tools/trunk <<'STUB'
#!/usr/bin/env bash
if [ "${1:-} ${2:-}" = "daemon status" ]; then
  printf 'x Daemon stopped\n'
  exit 1
fi
exit 0
STUB
  chmod +x tools/trunk
  git add .
  git commit -qm init
  printf 'changed\n' >> fixture.txt

  run_locked_gate() {
    # AGENT_QUALITY_GATE_LOCK_HELD is cleared deliberately: when this suite runs
    # as a mapped command of a real gate it inherits the outer run's marker,
    # and every contention assertion below would pass vacuously through the
    # nested-run escape hatch.
    set +e
    AGENT_QUALITY_GATE_LOCK=1 \
      AGENT_QUALITY_GATE_LOCK_HELD='' \
      AGENT_QUALITY_GATE_LOCK_DIR="$gate_lock_root" \
      AGENT_QUALITY_GATE_LOCK_POLL_SECONDS=1 \
      "$repo_root/scripts/agent-quality-gate.sh" \
      --base HEAD --run --lock-wait 2 "$@" \
      > "$output_file" 2>&1
    local exit_code=$?
    set -e
    printf '%s\n' "$exit_code"
  }

  write_lock_owner() {
    mkdir -p "$gate_lock_root/run.lock"
    {
      printf 'pid=%s\n' "$1"
      printf 'host=%s\n' "$(uname -n)"
      printf 'started_at=%s\n' "$(date +%s)"
      printf 'worktree=%s\n' "$gate_lock_repo"
      printf 'token=fixture-holder-1-1\n'
    } > "$gate_lock_root/run.lock/owner"
  }

  # A live holder: the second run announces who it is waiting for, keeps
  # waiting, and gives up with a bounded, actionable failure instead of hanging.
  sleep 120 &
  live_holder_pid=$!
  write_lock_owner "$live_holder_pid"
  lock_exit="$(run_locked_gate)"
  kill "$live_holder_pid" 2>/dev/null || true
  [[ "$lock_exit" == "2" ]] ||
    fail "expected a contended gate run to exit 2 after --lock-wait, got $lock_exit"
  assert_contains "Waiting for the agent quality gate run lock"
  assert_contains "held by pid ${live_holder_pid}"
  assert_contains "timed out after"
  # The pre-push hook cannot pass --no-lock, so the timeout must also name the
  # recovery that works from a failed push.
  assert_contains "git fetch --quiet origin main && ./scripts/agent-quality-gate.sh --run --parallel 3 --base origin/main"
  assert_contains "before coordinator registration"
  [[ -d "$gate_lock_root/run.lock" ]] ||
    fail "a run that never acquired the lock must not delete the holder's lock"

  # GitHub issue #1894: the same expiry, read the way a piped caller reads it.
  # Every other outcome states itself on stdout — a green run ends "All mapped
  # commands passed." — but the expiry used to speak on stderr alone, leaving a
  # stdout stream that ended on the reassuring "waiting up to Ns" banner. A
  # caller that piped the gate then had two signals and both lied: that stream,
  # and a pipeline status that belongs to the READER unless the caller set
  # `pipefail`. So this asserts the shape that misled — stdout piped, stderr
  # discarded — on both halves: the gate's own status, and a stdout stream that
  # names the wait expiry and says nothing ran.
  sleep 120 &
  piped_holder_pid=$!
  write_lock_owner "$piped_holder_pid"
  set +e
  AGENT_QUALITY_GATE_LOCK=1 \
    AGENT_QUALITY_GATE_LOCK_HELD='' \
    AGENT_QUALITY_GATE_LOCK_DIR="$gate_lock_root" \
    AGENT_QUALITY_GATE_LOCK_POLL_SECONDS=1 \
    "$repo_root/scripts/agent-quality-gate.sh" \
    --base HEAD --run --lock-wait 2 \
    2>/dev/null | cat > "$output_file"
  piped_exit="${PIPESTATUS[0]}"
  set -e
  kill "$piped_holder_pid" 2>/dev/null || true
  [[ "$piped_exit" == "2" ]] ||
    fail "expected a piped contended gate run to exit 2 after --lock-wait, got $piped_exit"
  assert_raw_contains "Gate run lock wait expired after"
  assert_raw_contains "No mapped command ran; this gate exits 2."
  assert_raw_contains "read \${PIPESTATUS[0]} or set -o pipefail"
  [[ -d "$gate_lock_root/run.lock" ]] ||
    fail "a piped run that never acquired the lock must not delete the holder's lock"

  # The same expiry against a reader that closes the pipe. Whether the run
  # reaches the verdict (exit 2) or dies writing the wait banner (a SIGPIPE
  # death) is a race with the reader, so what is pinned here is the invariant
  # the whole path owes its caller rather than one of the two statuses: a run
  # that executed nothing never reports success.
  sleep 120 &
  closed_pipe_holder_pid=$!
  write_lock_owner "$closed_pipe_holder_pid"
  set +e
  AGENT_QUALITY_GATE_LOCK=1 \
    AGENT_QUALITY_GATE_LOCK_HELD='' \
    AGENT_QUALITY_GATE_LOCK_DIR="$gate_lock_root" \
    AGENT_QUALITY_GATE_LOCK_POLL_SECONDS=1 \
    "$repo_root/scripts/agent-quality-gate.sh" \
    --base HEAD --run --lock-wait 2 \
    2> "$output_file" | head -c 1 > /dev/null
  closed_pipe_exit="${PIPESTATUS[0]}"
  set -e
  kill "$closed_pipe_holder_pid" 2>/dev/null || true
  [[ "$closed_pipe_exit" != "0" ]] ||
    fail "a contended gate whose reader closed the pipe reported success without executing anything"
  [[ -d "$gate_lock_root/run.lock" ]] ||
    fail "a run killed by a closed pipe must not delete the holder's lock"

  # A dead holder whose record carries a token the gate would never generate
  # is waited out, never reclaimed: reclaiming would later drain by that
  # token, matching processes with a value another writer chose. On a shared
  # root that record can be crafted, so fail-closed here means the timeout.
  malformed_dead_pid="$(fresh_dead_pid)" ||
    fail "could not obtain a reaped PID that reads as dead for the malformed-token case"
  mkdir -p "$gate_lock_root/run.lock"
  {
    printf 'pid=%s\n' "$malformed_dead_pid"
    printf 'host=%s\n' "$(uname -n)"
    printf 'started_at=%s\n' "$(date +%s)"
    printf 'worktree=%s\n' "$gate_lock_repo"
    printf 'token=crafted.*\n'
  } > "$gate_lock_root/run.lock/owner"
  lock_exit="$(run_locked_gate)"
  [[ "$lock_exit" == "2" ]] ||
    fail "a malformed-token record must be waited out and fail closed, got $lock_exit"
  assert_contains "timed out after"
  [[ -d "$gate_lock_root/run.lock" ]] ||
    fail "a malformed-token record must never be reclaimed"
  rm -rf "$gate_lock_root/run.lock"

  # An inherited nested-run marker (the gate's own self-test runs the gate)
  # starts immediately instead of deadlocking behind its own ancestor.
  sleep 120 &
  nested_holder_pid=$!
  write_lock_owner "$nested_holder_pid"
  set +e
  AGENT_QUALITY_GATE_LOCK=1 \
    AGENT_QUALITY_GATE_LOCK_HELD=outer-run \
    AGENT_QUALITY_GATE_LOCK_DIR="$gate_lock_root" \
    "$repo_root/scripts/agent-quality-gate.sh" \
    --base HEAD --run --lock-wait 5 \
    > "$output_file" 2>&1
  nested_exit=$?
  set -e
  nested_owner_pid="$(
    sed -n 's/^pid=//p' "$gate_lock_root/run.lock/owner" 2>/dev/null |
      head -n1 || true
  )"
  nested_owner_token="$(
    sed -n 's/^token=//p' "$gate_lock_root/run.lock/owner" 2>/dev/null |
      head -n1 || true
  )"
  kill "$nested_holder_pid" 2>/dev/null || true
  [[ "$nested_exit" == "0" ]] ||
    fail "expected a nested gate run to ignore the lock, got $nested_exit"
  assert_not_contains "Waiting for the agent quality gate run lock"
  [[ "$nested_owner_pid" == "$nested_holder_pid" ]] ||
    fail "a nested gate changed its ancestor's lock owner"
  [[ "$nested_owner_token" == fixture-holder-1-1 ]] ||
    fail "a nested gate changed its ancestor's lock token"

  # --no-lock is the documented escape hatch: it starts despite a live holder
  # and leaves that holder's lock alone.
  sleep 120 &
  bypass_holder_pid=$!
  write_lock_owner "$bypass_holder_pid"
  bypass_exit="$(run_locked_gate --no-lock)"
  kill "$bypass_holder_pid" 2>/dev/null || true
  [[ "$bypass_exit" == "0" ]] ||
    fail "expected --no-lock to run despite a live holder, got $bypass_exit"
  assert_not_contains "Waiting for the agent quality gate run lock"
  [[ -d "$gate_lock_root/run.lock" ]] ||
    fail "--no-lock must not delete another run's lock"

  # A killed holder (SIGKILL leaves the directory behind, EXIT trap and all)
  # must never wedge the next run: it reclaims the lock unattended, then
  # releases its own on the way out.
  dead_holder_pid="$(fresh_dead_pid)" ||
    fail "could not obtain a reaped PID that reads as dead for the stale-lock case"
  write_lock_owner "$dead_holder_pid"
  gate_test_write_inert_darwin_lineage_state \
    "$gate_lock_root" fixture-holder-1-1
  stale_exit="$(run_locked_gate)"
  [[ "$stale_exit" == "0" ]] ||
    fail "expected a stale lock to be reclaimed without manual cleanup, got $stale_exit"
  assert_contains "is stale ("
  assert_contains "${dead_holder_pid}"
  assert_contains "reclaiming it."
  [[ ! -d "$gate_lock_root/run.lock" ]] ||
    fail "a successful run must release the lock it acquired"

  # An unreaped child still answers kill -0 and appears in ps. Its Z state
  # makes it terminal work, so it must not retain the legacy lock.
  if command -v perl >/dev/null 2>&1; then
    zombie_pid_file="$(mktemp)"
    perl -e '$| = 1; $child = fork(); if (!$child) { exit 0; } print "$child\n"; sleep 30;' \
      > "$zombie_pid_file" &
    zombie_parent_pid=$!
    for _ in {1..50}; do
      [[ -s "$zombie_pid_file" ]] && break
      sleep 0.02
    done
    zombie_holder_pid="$(head -n1 "$zombie_pid_file")"
    [[ "$zombie_holder_pid" =~ ^[0-9]+$ ]] ||
      fail "could not create a zombie lock-holder fixture"
    for _ in {1..50}; do
      zombie_state="$(ps -o stat= -p "$zombie_holder_pid" 2>/dev/null | head -n1 | sed 's/[[:blank:]]//g')"
      [[ "$zombie_state" == Z* ]] && break
      sleep 0.02
    done
    [[ "$zombie_state" == Z* ]] || fail "fixture child did not become a zombie"
    write_lock_owner "$zombie_holder_pid"
    gate_test_write_inert_darwin_lineage_state \
      "$gate_lock_root" fixture-holder-1-1
    zombie_exit="$(run_locked_gate)"
    kill "$zombie_parent_pid" 2>/dev/null || true
    wait "$zombie_parent_pid" 2>/dev/null || true
    rm -f "$zombie_pid_file"
    [[ "$zombie_exit" == "0" ]] ||
      fail "expected a zombie holder to be reclaimed, got $zombie_exit"
    assert_contains "is stale (holder pid ${zombie_holder_pid} has exited and is awaiting reap); reclaiming it."
    [[ ! -d "$gate_lock_root/run.lock" ]] ||
      fail "a zombie holder must not retain the legacy lock"
  fi
  # --- Machine identity, not hostname (GitHub issue #2055) -------------------
  # A rename used to wedge the machine: the record still named the old
  # hostname, the mismatch was read as a live holder on another host, and the
  # dead-PID reclaim below it was never reached — so every run on the machine
  # burned its whole --lock-wait and no run ever healed it. The record now
  # carries a machine identity that a rename cannot touch, and the hostname
  # decides only where no comparable identity exists on both sides.
  #
  # Both machines are simulated through the identity override, so these cases
  # assert the decision rather than the hardware probe underneath it, and run
  # the same way on a Linux runner as on the developer Mac that hit the bug.
  #
  # The locality of the lock root is declared for the same reason. In a real
  # run the gate asks the filesystem whether the root is on storage only this
  # machine reaches; this suite must keep pointing every case at its own temp
  # root, whose answer would then depend on how the runner mounts $TMPDIR.
  # Declaring it pins the decision under test instead of the runner's mount
  # table. The possibly-shared cases below set it to 0.
  export AGENT_QUALITY_GATE_LOCK_MACHINE_ID=machine-a
  export AGENT_QUALITY_GATE_LOCK_DIR_IS_PER_MACHINE=1

  write_machine_lock_owner() {
    # pid, host, machine field value (empty writes no field at all, which is
    # exactly what a gate predating this change leaves behind), started_at.
    mkdir -p "$gate_lock_root/run.lock"
    {
      printf 'pid=%s\n' "$1"
      printf 'host=%s\n' "$2"
      [[ -z "$3" ]] || printf 'machine=%s\n' "$3"
      printf 'started_at=%s\n' "$4"
      printf 'worktree=%s\n' "$gate_lock_repo"
      printf 'token=fixture-holder-1-1\n'
    } > "$gate_lock_root/run.lock/owner"
  }

  # The bug itself. Same machine, renamed host, holder long dead — reclaimed at
  # once on the strength of the machine identity, with no age gate involved and
  # nothing said about an unverifiable host.
  renamed_dead_pid="$(fresh_dead_pid)" ||
    fail "could not obtain a reaped PID that reads as dead for the renamed-host case"
  write_machine_lock_owner \
    "$renamed_dead_pid" "Workbook.local" "override:machine-a" "$(date +%s)"
  gate_test_write_inert_darwin_lineage_state \
    "$gate_lock_root" fixture-holder-1-1
  renamed_exit="$(run_locked_gate)"
  [[ "$renamed_exit" == "0" ]] ||
    fail "a dead holder recorded under this machine's old hostname must be reclaimed, got $renamed_exit"
  assert_contains "is stale (holder pid ${renamed_dead_pid} is gone); reclaiming it."
  assert_not_contains "cannot be tied to this machine"
  [[ ! -d "$gate_lock_root/run.lock" ]] ||
    fail "the run that reclaimed a renamed-host lock must release its own"

  # The safety this replaces the hostname check with. On a root that may be
  # shared, a disagreeing identity from the same source is another machine —
  # definitive, its PIDs meaning nothing here, and no local evidence able to
  # overturn it. A record two hours old whose PID reads dead locally is still
  # waited out and left where it is.
  foreign_dead_pid="$(fresh_dead_pid)" ||
    fail "could not obtain a reaped PID that reads as dead for the foreign-machine case"
  write_machine_lock_owner \
    "$foreign_dead_pid" "other-host" "override:machine-b" "$(($(date +%s) - 7200))"
  foreign_exit="$(AGENT_QUALITY_GATE_LOCK_DIR_IS_PER_MACHINE=0 run_locked_gate)"
  [[ "$foreign_exit" == "2" ]] ||
    fail "a record from another machine must be waited out, got $foreign_exit"
  assert_contains "timed out after"
  assert_not_contains "reclaiming it."
  [[ -d "$gate_lock_root/run.lock" ]] ||
    fail "another machine's lock must never be reclaimed, however old"
  rm -rf "$gate_lock_root/run.lock"

  # The same record on a root proven local. Nothing else can have written it,
  # so a disagreeing identity is not another machine — it is this machine's own
  # identity having moved, which `/etc/machine-id` does on an OS reinstall or
  # an image rebuild. Reading it as foreign here would leave the record
  # unreclaimable forever, which is the wedge this whole change removes, so it
  # lands on the aged-and-dead rule instead.
  rotated_dead_pid="$(fresh_dead_pid)" ||
    fail "could not obtain a reaped PID that reads as dead for the rotated-identity case"
  write_machine_lock_owner \
    "$rotated_dead_pid" "other-host" "override:machine-b" "$(($(date +%s) - 7200))"
  gate_test_write_inert_darwin_lineage_state \
    "$gate_lock_root" fixture-holder-1-1
  rotated_exit="$(run_locked_gate)"
  [[ "$rotated_exit" == "0" ]] ||
    fail "a rotated machine identity on local storage must not wedge the lock, got $rotated_exit"
  assert_contains "cannot be tied to this machine"
  assert_contains "is stale (holder pid ${rotated_dead_pid} is gone"
  [[ ! -d "$gate_lock_root/run.lock" ]] ||
    fail "the run that reclaimed a rotated-identity record must release its own"

  # An agreeing identity is not proof of one machine, only a disagreeing one is
  # proof of two. Containers built from a single base image carry the same
  # baked-in /etc/machine-id, so two of them mounting one lock directory agree
  # on their identity while having separate PID namespaces — the other's holder
  # PID reads "gone" here. Off proven-local storage the hostname has to agree
  # too, and where it does not this record is left alone however old it is.
  cloned_id_dead_pid="$(fresh_dead_pid)" ||
    fail "could not obtain a reaped PID that reads as dead for the cloned-identity case"
  write_machine_lock_owner \
    "$cloned_id_dead_pid" "other-container" "override:machine-a" "$(($(date +%s) - 7200))"
  cloned_id_exit="$(AGENT_QUALITY_GATE_LOCK_DIR_IS_PER_MACHINE=0 run_locked_gate)"
  [[ "$cloned_id_exit" == "2" ]] ||
    fail "a shared machine id under a different hostname must be waited out on a shared root, got $cloned_id_exit"
  assert_contains "timed out after"
  assert_not_contains "reclaiming it."
  [[ -d "$gate_lock_root/run.lock" ]] ||
    fail "a duplicated machine id must not authorise reclaiming another host's lock"
  rm -rf "$gate_lock_root/run.lock"

  # The same record on storage this machine mounts itself. Nothing else is
  # writing records there, and the hostname is exactly the field a rename
  # moved, so requiring it to agree would refuse the case this all exists for.
  renamed_local_dead_pid="$(fresh_dead_pid)" ||
    fail "could not obtain a reaped PID that reads as dead for the local renamed-host case"
  write_machine_lock_owner \
    "$renamed_local_dead_pid" "other-container" "override:machine-a" "$(($(date +%s) - 7200))"
  gate_test_write_inert_darwin_lineage_state \
    "$gate_lock_root" fixture-holder-1-1
  renamed_local_exit="$(run_locked_gate)"
  [[ "$renamed_local_exit" == "0" ]] ||
    fail "a matching identity on local storage must reclaim whatever the record calls the host, got $renamed_local_exit"
  assert_contains "is stale (holder pid ${renamed_local_dead_pid} is gone); reclaiming it."
  [[ ! -d "$gate_lock_root/run.lock" ]] ||
    fail "the run that reclaimed under a matching local identity must release its own"

  # A record written by a gate that predates the machine field, under a
  # hostname this machine no longer answers to. The root is proven local, so
  # nothing else wrote it; the reclaim still needs the dead PID and the grace,
  # and the message names what it concluded and from what.
  legacy_dead_pid="$(fresh_dead_pid)" ||
    fail "could not obtain a reaped PID that reads as dead for the legacy-record case"
  write_machine_lock_owner \
    "$legacy_dead_pid" "Workbook.local" "" "$(($(date +%s) - 7200))"
  gate_test_write_inert_darwin_lineage_state \
    "$gate_lock_root" fixture-holder-1-1
  legacy_exit="$(run_locked_gate)"
  [[ "$legacy_exit" == "0" ]] ||
    fail "an aged legacy record under a stale hostname must self-heal, got $legacy_exit"
  assert_contains "cannot be tied to this machine"
  assert_contains "This lock root is on storage this machine mounts itself"
  assert_contains "under a name or identity it has since changed, and reclaims it"
  assert_contains "its record cannot be tied to this machine and is"
  [[ ! -d "$gate_lock_root/run.lock" ]] ||
    fail "the run that reclaimed a legacy record must release its own"

  # The same legacy record, still inside the grace. Age is the leg that keeps a
  # run which really did start moments ago on another machine out of reach of
  # that inference, so this one waits instead — the pre-issue-2055 behaviour,
  # now bounded by the grace rather than permanent.
  young_dead_pid="$(fresh_dead_pid)" ||
    fail "could not obtain a reaped PID that reads as dead for the within-grace case"
  write_machine_lock_owner "$young_dead_pid" "Workbook.local" "" "$(date +%s)"
  young_exit="$(run_locked_gate)"
  [[ "$young_exit" == "2" ]] ||
    fail "a legacy foreign-host record inside the grace must be waited out, got $young_exit"
  assert_contains "timed out after"
  assert_not_contains "reclaiming it."
  [[ -d "$gate_lock_root/run.lock" ]] ||
    fail "a record still inside the grace must be left in place"

  # …and the grace is the knob that decides it. The same record, same run, a
  # grace of zero: reclaimed.
  gate_test_write_inert_darwin_lineage_state \
    "$gate_lock_root" fixture-holder-1-1
  set +e
  AGENT_QUALITY_GATE_LOCK=1 \
    AGENT_QUALITY_GATE_LOCK_HELD='' \
    AGENT_QUALITY_GATE_LOCK_DIR="$gate_lock_root" \
    AGENT_QUALITY_GATE_LOCK_POLL_SECONDS=1 \
    AGENT_QUALITY_GATE_LOCK_UNVERIFIED_MACHINE_GRACE_SECONDS=0 \
    "$repo_root/scripts/agent-quality-gate.sh" \
    --base HEAD --run --lock-wait 2 \
    > "$output_file" 2>&1
  grace_exit=$?
  set -e
  [[ "$grace_exit" == "0" ]] ||
    fail "a zero grace must let the same legacy record be reclaimed, got $grace_exit"
  assert_contains "cannot be tied to this machine"
  [[ ! -d "$gate_lock_root/run.lock" ]] ||
    fail "the run that reclaimed under a zero grace must release its own"

  # Two identities from different sources are not two machines. A run that
  # reached `ioreg` and a run that fell back to `kern.uuid` would otherwise
  # read each other as foreign and reinvent the wedge, so a source mismatch is
  # no verdict at all: it lands on the same aged-and-dead rule as a record with
  # no machine field.
  source_mismatch_pid="$(fresh_dead_pid)" ||
    fail "could not obtain a reaped PID that reads as dead for the source-mismatch case"
  write_machine_lock_owner \
    "$source_mismatch_pid" "Workbook.local" "kernuuid:machine-b" "$(($(date +%s) - 7200))"
  gate_test_write_inert_darwin_lineage_state \
    "$gate_lock_root" fixture-holder-1-1
  source_mismatch_exit="$(run_locked_gate)"
  [[ "$source_mismatch_exit" == "0" ]] ||
    fail "a machine id from another source must not read as another machine, got $source_mismatch_exit"
  assert_contains "cannot be tied to this machine"
  [[ ! -d "$gate_lock_root/run.lock" ]] ||
    fail "the run that reclaimed a source-mismatched record must release its own"

  # The limit on all of that. Every reclaim above rests on the lock root being
  # storage only this machine reaches. Where the filesystem says otherwise — a
  # network home directory, or one whose type could not be read — a PID that
  # reads dead here says nothing about a holder running on another machine.
  # However old the record is, this run waits and names the declaration that
  # would change the answer.
  shared_root_dead_pid="$(fresh_dead_pid)" ||
    fail "could not obtain a reaped PID that reads as dead for the shared-root case"
  write_machine_lock_owner \
    "$shared_root_dead_pid" "Workbook.local" "" "$(($(date +%s) - 7200))"
  shared_root_exit="$(AGENT_QUALITY_GATE_LOCK_DIR_IS_PER_MACHINE=0 run_locked_gate)"
  [[ "$shared_root_exit" == "2" ]] ||
    fail "an unverified record on a possibly shared lock root must be waited out, got $shared_root_exit"
  assert_contains "not established as storage only this machine reaches"
  assert_contains "AGENT_QUALITY_GATE_LOCK_DIR_IS_PER_MACHINE=1"
  assert_not_contains "reclaiming it."
  # This is a refusal on where the root lives, so the wait owes the same
  # answer as the guard below it: the holder PID read as gone on this pass, and
  # sending an operator to let it finish is a wait that never ends.
  assert_contains "Nothing was reclaimed:"
  assert_not_contains "is still alive; let it finish"
  [[ -d "$gate_lock_root/run.lock" ]] ||
    fail "a record on a possibly shared lock root must never be reclaimed"
  rm -rf "$gate_lock_root/run.lock"

  # An identity is validated against the record's alphabet, never rewritten to
  # fit it. Every normalisation is a many-to-one map, and a many-to-one map on
  # an identity is how two machines come to compare equal: stripping the
  # unrepresentable character in `machine/a`, or deleting the line break in
  # `machine<LF>a`, both yield `machinea` — another machine's legitimate id,
  # which then reads as `same` and authorises a reclaim on its behalf. Both
  # shapes must stop the run rather than be quietly reshaped, so both are
  # asserted: one where the offending character is ordinary, one where it is a
  # line break, because deleting line breaks is the normalisation a reader is
  # most likely to think harmless.
  for bad_machine_id in 'machine/a' 'machine:a' "$(printf 'machine\na')" "$(printf 'machine\ra')"; do
    set +e
    AGENT_QUALITY_GATE_LOCK=1 \
      AGENT_QUALITY_GATE_LOCK_HELD='' \
      AGENT_QUALITY_GATE_LOCK_DIR="$gate_lock_root" \
      AGENT_QUALITY_GATE_LOCK_MACHINE_ID="$bad_machine_id" \
      "$repo_root/scripts/agent-quality-gate.sh" \
      --base HEAD --run --lock-wait 2 \
      > "$output_file" 2>&1
    bad_machine_id_exit=$?
    set -e
    [[ "$bad_machine_id_exit" == "2" ]] ||
      fail "machine id '${bad_machine_id}' is outside the record alphabet and must stop the run, got $bad_machine_id_exit"
    assert_contains "AGENT_QUALITY_GATE_LOCK_MACHINE_ID must be 1-128 characters"
    assert_contains "so it is never rewritten to fit"
    assert_contains "Nothing has been executed."
  done

  # The probe itself, both ways, on paths whose answer is known independently
  # of it. A directory on local storage must read as local; a path on a
  # filesystem `df -l` omits — an autofs map, an NFS or SMB mount — must not,
  # or the whole rule above rests on a check that only ever says yes. The
  # non-local path is discovered from the mount table rather than assumed, and
  # the case is skipped where the runner has no such mount to point at.
  gate_lock_probe_local="$(
    NODE_ENV=test \
      AGENT_QUALITY_GATE_LOCK_PROBE_PATH="$gate_lock_root" \
      "$repo_root/scripts/agent-quality-gate.sh" 2>&1
  )" || true
  [[ "$gate_lock_probe_local" == "local" ]] ||
    fail "the locality probe must read a temp-dir lock root as local, got '$gate_lock_probe_local'"
  gate_lock_nonlocal_path="$(
    comm -23 \
      <(df 2>/dev/null | tail -n +2 | awk 'NF { print $NF }' | sort) \
      <(df -l 2>/dev/null | tail -n +2 | awk 'NF { print $NF }' | sort) |
      head -n1
  )"
  if [[ -n "$gate_lock_nonlocal_path" && -d "$gate_lock_nonlocal_path" ]]; then
    gate_lock_probe_remote="$(
      NODE_ENV=test \
        AGENT_QUALITY_GATE_LOCK_PROBE_PATH="$gate_lock_nonlocal_path" \
        "$repo_root/scripts/agent-quality-gate.sh" 2>&1
    )" || true
    [[ "$gate_lock_probe_remote" == "not-local" ]] ||
      fail "the locality probe must not read ${gate_lock_nonlocal_path} as local, got '$gate_lock_probe_remote'"
  fi

  # --- A shared lock root refuses every reclaim (GitHub issue #2061) ---------
  # The forcing hook first, because every case below rests on it. It has to
  # reach the same probe the refusal reads, or those cases would pass for some
  # other reason; the unforced reading of this very directory is asserted
  # `local` above, so the pair is two-sided.
  gate_lock_probe_forced="$(
    NODE_ENV=test \
      AGENT_QUALITY_GATE_LOCK_TEST_FORCE_NOT_LOCAL=1 \
      AGENT_QUALITY_GATE_LOCK_PROBE_PATH="$gate_lock_root" \
      "$repo_root/scripts/agent-quality-gate.sh" 2>&1
  )" || true
  [[ "$gate_lock_probe_forced" == "not-local" ]] ||
    fail "the forced locality probe must answer not-local, got '$gate_lock_probe_forced'"

  # …and it is refused outside the self-test, like every other test-only hook,
  # so it can never quietly change how a real run behaves.
  set +e
  AGENT_QUALITY_GATE_LOCK=1 \
    AGENT_QUALITY_GATE_LOCK_HELD='' \
    AGENT_QUALITY_GATE_LOCK_DIR="$gate_lock_root" \
    NODE_ENV='' \
    AGENT_QUALITY_GATE_LOCK_TEST_FORCE_NOT_LOCAL=1 \
    "$repo_root/scripts/agent-quality-gate.sh" \
    --base HEAD --run --lock-wait 2 \
    > "$output_file" 2>&1
  forced_probe_outside_test_exit=$?
  set -e
  [[ "$forced_probe_outside_test_exit" == "2" ]] ||
    fail "the locality forcing hook outside NODE_ENV=test must exit 2, got $forced_probe_outside_test_exit"
  assert_contains "AGENT_QUALITY_GATE_LOCK_TEST_FORCE_NOT_LOCAL is a test-only override and requires NODE_ENV=test"

  # The residual PR 2060 left. A machine identity and a hostname are the two
  # fields that say a record was written here, and both can be cloned: two
  # containers built from one image carry the same /etc/machine-id and the same
  # hostname. On a lock root they share, each reads the other's record as its
  # own, finds the holder's PID absent from its own PID namespace, and used to
  # reclaim a lock whose holder was running next door. Nothing available
  # locally tells those two apart, so off storage this machine mounts itself no
  # record is reclaimed at all, however old it is and however dead its PID
  # reads.
  #
  # Both containers are simulated with one identity override and this machine's
  # real hostname — the indistinguishable pair the issue describes — and the
  # only field that differs between them is the holder PID, which is exactly
  # the field that reads wrong across the boundary. So the case runs in both
  # directions: each container in turn is the one reading the other's record,
  # and neither takes it.
  for shared_storage_round in 1 2; do
    shared_storage_dead_pid="$(fresh_dead_pid)" ||
      fail "could not obtain a reaped PID that reads as dead for cloned-machine round ${shared_storage_round}"
    write_machine_lock_owner \
      "$shared_storage_dead_pid" "$(uname -n)" "override:machine-a" \
      "$(($(date +%s) - 7200))"
    shared_storage_exit="$(
      NODE_ENV=test \
        AGENT_QUALITY_GATE_LOCK_TEST_FORCE_NOT_LOCAL=1 \
        AGENT_QUALITY_GATE_LOCK_DIR_IS_PER_MACHINE='' \
        run_locked_gate
    )"
    [[ "$shared_storage_exit" == "2" ]] ||
      fail "a cloned machine must wait out the other's dead-looking record (round ${shared_storage_round}), got $shared_storage_exit"
    assert_contains "looks reclaimable (holder pid ${shared_storage_dead_pid} is gone), and this run refuses to reclaim it."
    assert_contains "Self-healing is disabled on such a root"
    assert_contains "Give each machine its own AGENT_QUALITY_GATE_LOCK_DIR"
    assert_contains "timed out after"
    # The wait ended because a reclaim was refused, not because a holder was
    # seen running. Repeating the usual line would send an operator to wait on
    # a process this very run read as gone, and that wait never ends.
    assert_contains "Nothing was reclaimed:"
    assert_not_contains "is still alive; let it finish"
    assert_not_contains "reclaiming it."
    [[ -d "$gate_lock_root/run.lock" ]] ||
      fail "a record on a shared lock root must be left where it is (round ${shared_storage_round})"
    rm -rf "$gate_lock_root/run.lock"
  done

  # The refusal covers the record with no holder at all, for the same reason:
  # "no complete record here" is as local a reading as a PID lookup. A network
  # client caches directory attributes, so a freshly written owner file can
  # stay invisible to another client for longer than the grace that would
  # otherwise authorise taking the lock away.
  mkdir -p "$gate_lock_root/run.lock"
  rm -f "$gate_lock_root/run.lock/owner"
  ownerless_shared_exit="$(
    NODE_ENV=test \
      AGENT_QUALITY_GATE_LOCK_TEST_FORCE_NOT_LOCAL=1 \
      AGENT_QUALITY_GATE_LOCK_DIR_IS_PER_MACHINE='' \
      AGENT_QUALITY_GATE_LOCK_OWNER_GRACE_SECONDS=0 \
      run_locked_gate
  )"
  [[ "$ownerless_shared_exit" == "2" ]] ||
    fail "an ownerless lock on a shared root must be waited out, got $ownerless_shared_exit"
  assert_contains "looks reclaimable (its holder never recorded a complete identity), and this run refuses to reclaim it."
  assert_not_contains "reclaiming it."
  [[ -d "$gate_lock_root/run.lock" ]] ||
    fail "an ownerless lock on a shared root must be left where it is"
  rm -rf "$gate_lock_root/run.lock"

  # A remnant from an interrupted reclaim is classified by the same local PID
  # lookup, so off local storage it cannot be called dead either. Deleting it
  # would destroy the only copy of a possibly-live holder's record and leave
  # the lock ownerless — the one state this root can no longer reclaim — so the
  # wedge would be permanent instead of healed after the owner grace. Both
  # directions are asserted, because a check that only ever preserves would
  # pass while proving nothing about the rule.
  write_remnant_record() {
    mkdir -p "$gate_lock_root/run.lock"
    rm -f "$gate_lock_root/run.lock/owner"
    {
      printf 'pid=%s\n' "$1"
      printf 'host=%s\n' "$(uname -n)"
      printf 'machine=override:machine-a\n'
      printf 'started_at=%s\n' "$(($(date +%s) - 7200))"
      printf 'worktree=%s\n' "$gate_lock_repo"
      printf 'token=fixture-holder-1-1\n'
    } > "$gate_lock_root/run.lock/owner.reclaiming.9999"
  }

  remnant_shared_pid="$(fresh_dead_pid)" ||
    fail "could not obtain a reaped PID that reads as dead for the shared-root remnant case"
  write_remnant_record "$remnant_shared_pid"
  remnant_shared_exit="$(
    NODE_ENV=test \
      AGENT_QUALITY_GATE_LOCK_TEST_FORCE_NOT_LOCAL=1 \
      AGENT_QUALITY_GATE_LOCK_DIR_IS_PER_MACHINE='' \
      AGENT_QUALITY_GATE_LOCK_OWNER_GRACE_SECONDS=0 \
      run_locked_gate
  )"
  [[ "$remnant_shared_exit" == "2" ]] ||
    fail "a remnant on a shared lock root must be waited out, got $remnant_shared_exit"
  [[ -e "$gate_lock_root/run.lock/owner.reclaiming.9999" ]] ||
    fail "a remnant on a shared lock root must not be deleted"
  assert_contains "refuses to reclaim it."
  rm -rf "$gate_lock_root/run.lock"

  # The control: the same remnant on storage this machine mounts itself is a
  # verified-dead record, and the pre-existing path deletes it and heals the
  # lock.
  remnant_local_pid="$(fresh_dead_pid)" ||
    fail "could not obtain a reaped PID that reads as dead for the local remnant case"
  write_remnant_record "$remnant_local_pid"
  gate_test_write_inert_darwin_lineage_state \
    "$gate_lock_root" fixture-holder-1-1
  remnant_local_exit="$(
    AGENT_QUALITY_GATE_LOCK_DIR_IS_PER_MACHINE='' \
      AGENT_QUALITY_GATE_LOCK_OWNER_GRACE_SECONDS=0 \
      run_locked_gate
  )"
  [[ "$remnant_local_exit" == "0" ]] ||
    fail "a dead remnant on local storage must still heal the lock, got $remnant_local_exit"
  [[ ! -e "$gate_lock_root/run.lock/owner.reclaiming.9999" ]] ||
    fail "a verified-dead remnant on local storage must still be discarded"
  rm -rf "$gate_lock_root/run.lock"

  # The refusal is re-decided every pass, so a record published after one is
  # judged on its own terms. A creator that stalls between taking the lock
  # directory and writing its record leaves the lock ownerless past the grace
  # and is refused — and then publishes a perfectly live record. The timeout
  # has to name that live holder; telling the operator to remove a lock
  # somebody is holding is the one piece of advice this diagnosis must never
  # give. The early refusal is asserted too, so the case cannot pass by never
  # reaching the branch it is about.
  mkdir -p "$gate_lock_root/run.lock"
  rm -f "$gate_lock_root/run.lock/owner"
  sleep 60 &
  late_holder_pid=$!
  # Truncated before the publisher starts watching it, because earlier cases in
  # this family wrote the same refusal line into this file and a stale match
  # would let the publisher fire before the gate had looked at anything.
  : > "$output_file"
  (
    # Published by rename, so the waiter never reads a half-written record and
    # mistakes it for the ownerless state this case starts from. Ordered
    # against the gate's own output rather than a fixed sleep: the point of the
    # case is a record published AFTER a refusal, and a slow runner that had
    # not reached the refusal yet would fail it with no defect to show for it.
    # A publisher that never sees the refusal exits non-zero and fails the case
    # rather than publishing anyway and asserting against a sequence that never
    # happened.
    late_deadline=$(($(date +%s) + 8))
    until grep -Fq "refuses to reclaim it." "$output_file"; do
      [[ "$(date +%s)" -lt "$late_deadline" ]] || exit 1
      sleep 1
    done
    {
      printf 'pid=%s\n' "$late_holder_pid"
      printf 'host=%s\n' "$(uname -n)"
      printf 'machine=override:machine-a\n'
      printf 'started_at=%s\n' "$(date +%s)"
      printf 'worktree=%s\n' "$gate_lock_repo"
      printf 'token=fixture-holder-1-1\n'
    } > "$gate_lock_root/run.lock/owner.staged"
    mv "$gate_lock_root/run.lock/owner.staged" "$gate_lock_root/run.lock/owner"
  ) &
  late_publisher_pid=$!
  set +e
  NODE_ENV=test \
    AGENT_QUALITY_GATE_LOCK_TEST_FORCE_NOT_LOCAL=1 \
    AGENT_QUALITY_GATE_LOCK_DIR_IS_PER_MACHINE='' \
    AGENT_QUALITY_GATE_LOCK_OWNER_GRACE_SECONDS=0 \
    AGENT_QUALITY_GATE_LOCK=1 \
    AGENT_QUALITY_GATE_LOCK_HELD='' \
    AGENT_QUALITY_GATE_LOCK_DIR="$gate_lock_root" \
    AGENT_QUALITY_GATE_LOCK_POLL_SECONDS=1 \
    "$repo_root/scripts/agent-quality-gate.sh" \
    --base HEAD --run --lock-wait 12 \
    > "$output_file" 2>&1
  late_publish_exit=$?
  wait "$late_publisher_pid"
  late_publisher_exit=$?
  set -e
  kill "$late_holder_pid" 2>/dev/null || true
  [[ "$late_publisher_exit" == "0" ]] ||
    fail "the gate never printed a refusal for the publisher to follow, so this case proved nothing"
  [[ "$late_publish_exit" == "2" ]] ||
    fail "a live holder published after a refusal must still be waited out, got $late_publish_exit"
  assert_contains "refuses to reclaim it."
  assert_contains "Holder pid ${late_holder_pid} is still alive; let it finish"
  assert_not_contains "Nothing was reclaimed:"
  rm -rf "$gate_lock_root/run.lock"

  # The limit of the refusal, and the reason it turns on the storage rather
  # than on who named the directory. This suite's root IS an
  # AGENT_QUALITY_GATE_LOCK_DIR, and it is on local storage. Refusing there
  # too would take self-healing away from every operator-supplied root and
  # bring back the wedge class issue #2055 removed, so the same record — same
  # cloned identity, same hostname, same dead PID — is reclaimed once the
  # storage is the machine's own.
  local_override_dead_pid="$(fresh_dead_pid)" ||
    fail "could not obtain a reaped PID that reads as dead for the local-override case"
  write_machine_lock_owner \
    "$local_override_dead_pid" "$(uname -n)" "override:machine-a" \
    "$(($(date +%s) - 7200))"
  gate_test_write_inert_darwin_lineage_state \
    "$gate_lock_root" fixture-holder-1-1
  local_override_exit="$(AGENT_QUALITY_GATE_LOCK_DIR_IS_PER_MACHINE='' run_locked_gate)"
  [[ "$local_override_exit" == "0" ]] ||
    fail "an operator lock dir on local storage must keep self-healing, got $local_override_exit"
  assert_contains "is stale (holder pid ${local_override_dead_pid} is gone); reclaiming it."
  assert_not_contains "refuses to reclaim it"
  [[ ! -d "$gate_lock_root/run.lock" ]] ||
    fail "the run that reclaimed on a local operator root must release its own"

  unset AGENT_QUALITY_GATE_LOCK_MACHINE_ID
)
rm -rf "$gate_lock_repo" "$gate_lock_root"

# Reclaiming a lock spans two decisions — "this lock is stale" and "take it" —
# and creating one spans two more: win `mkdir`, then record ownership. Both
# windows are sub-millisecond in production, which is why the gate exposes
# test-only delays that hold them open. What has to hold either way: exactly
# one run executes mapped commands at a time. The fixture's only mapped command
# is a trunk stub recording when it starts and stops, so two overlapping
# records are the failure these two cases exist to catch.
gate_race_repo="$(mktemp -d)"
gate_race_root="$(mktemp -d)"
# Logs and per-run output live outside the fixture repo on purpose: written
# inside it they become untracked changed paths, so every run would map
# commands over the suite's own artifacts and the mapped set would grow as
# the suite went on.
gate_race_out="$(mktemp -d)"
gate_race_log="$gate_race_out/race.log"
gate_race_sync="$(mktemp -d)"
# macOS can change its reported host name while this long fixture runs. Pin
# only `uname -n` inside the fixture so its records and nested gates use one
# host identity. Explicit fingerprints still exercise foreign-host recovery.
gate_race_real_uname="$(command -v uname)" ||
  fail "the lock-race fixture could not resolve uname"
[[ "$gate_race_real_uname" == /* && -x "$gate_race_real_uname" ]] ||
  fail "the lock-race fixture requires uname to resolve to an executable path"
gate_race_test_bin="$gate_race_out/test-bin"
mkdir -p "$gate_race_test_bin"
cat > "$gate_race_test_bin/uname" <<'STUB'
#!/usr/bin/env bash
if [[ "$#" -eq 1 && "$1" == "-n" ]]; then
  printf 'quality-gate-lock-fixture.local\n'
  exit 0
fi
exec "${GATE_RACE_REAL_UNAME:?}" "$@"
STUB
chmod +x "$gate_race_test_bin/uname"
(
  export GATE_RACE_REAL_UNAME="$gate_race_real_uname"
  export PATH="$gate_race_test_bin:$PATH"
  [[ "$(uname -n)" == "quality-gate-lock-fixture.local" ]] ||
    fail "the lock-race fixture could not stabilize its host identity"
  [[ "$(uname -s)" == "$("$gate_race_real_uname" -s)" ]] ||
    fail "the lock-race fixture uname shim did not delegate non-hostname queries"
  gate_test_capture_current_shell_pid "$gate_race_sync/race-shell.pid" ||
    fail "could not capture the lock-race subshell PID under Bash 3.2"
  gate_test_signal_shell_pid="$gate_test_captured_shell_pid"
  [[ "$gate_test_signal_shell_pid" != "$gate_test_outer_pid" &&
    "$gate_test_signal_shell_pid" != "$gate_test_executor_pid" ]] ||
    fail "the lock-race subshell PID aliases a protected outer identity"
  if [[ -n "$gate_test_signal_trace_file" ]]; then
    gate_test_trace_signal identity race-subshell NONE "$gate_test_signal_shell_pid" \
      "$(gate_test_process_start "$gate_test_signal_shell_pid")" \
      "$(gate_test_process_start "$gate_test_signal_shell_pid")" \
      "$gate_test_outer_pid" \
      "$(gate_test_process_parent "$gate_test_signal_shell_pid")"
    trap 'gate_test_on_term race-subshell "$gate_test_signal_shell_pid"' TERM
  fi
  gate_race_fixture_epoch="$(date +%s)"
  race_inherited_token="$(printf "fixture-inherited-%s-%s" "$gate_test_outer_pid" "$gate_race_fixture_epoch")"
  race_drained_first_token="$(printf "fixture-drained-first-%s-%s" "$gate_test_outer_pid" "$gate_race_fixture_epoch")"
  race_arrived_late_token="$(printf "fixture-arrived-late-%s-%s" "$gate_test_outer_pid" "$gate_race_fixture_epoch")"
  race_zombie_token="$(printf "fixture-zombie-%s-%s" "$gate_test_outer_pid" "$gate_race_fixture_epoch")"
  for race_fixture_token in \
    "$race_inherited_token" "$race_drained_first_token" \
    "$race_arrived_late_token" "$race_zombie_token"; do
    [[ "$race_fixture_token" =~ ^[A-Za-z0-9][A-Za-z0-9._-]{0,180}-[0-9]{1,10}-[0-9]{1,12}$ ]] ||
      fail "suite-unique live fixture token is malformed: ${race_fixture_token}"
  done
  race_drain_cleanup_active=0
  race_drain_hold_file=""
  race_drain_orphan=""
  race_drain_orphan_start=""
  race_drain_a_wrapper=""
  race_drain_a_wrapper_start=""
  race_drain_a_wrapper_parent=""
  race_drain_a_token=""
  race_drain_a_lineage_state=""
  race_drain_b_wrapper=""
  race_drain_b_wrapper_start=""
  race_drain_b_wrapper_parent=""
  race_drain_b_settler=""
  race_drain_b_settler_start=""
  race_drain_c_wrapper=""
  race_drain_c_wrapper_start=""
  race_drain_c_wrapper_parent=""
  race_drain_watchdog_identities=""
  race_drain_portable_watchdog_count=0
  race_drain_lineage_watcher_count=0
  race_fork_record=""
  race_fork_ack=""
  race_fork_wrapper=""
  race_fork_wrapper_start=""
  race_fork_wrapper_parent=""
  race_fork_bystander=""
  race_fork_bystander_start=""
  race_fork_bystander_parent=""
  race_forkexit_record=""
  race_forkexit_ack=""
  race_forkexit_wrapper=""
  race_forkexit_wrapper_start=""
  race_forkexit_wrapper_parent=""
  race_forkexit_bystander=""
  race_forkexit_bystander_start=""
  race_forkexit_bystander_parent=""
  race_fork_probe_record=""
  race_fork_unit_bystander=""
  race_fork_unit_bystander_start=""
  race_fork_unit_bystander_parent=""
  race_zombie_supervisor=""
  race_zombie_supervisor_start=""
  race_zombie_supervisor_parent=""
  race_zombie_supervisor_release=""
  race_zombie_child=""
  race_zombie_child_start=""
  race_drain_owned_survivors=""
  race_drain_owned_record_error=""
  race_drain_pair_observation_file=""
  race_drain_pair_require_change=0

  race_drain_process_is_expected() {
    local pid="$1"
    local expected_start="$2"
    local expected_parent="$3"
    gate_test_process_is_expected "$pid" "$expected_start" "$expected_parent"
  }

  race_drain_victim_is_expected() {
    [[ "$race_drain_cleanup_active" -eq 1 && -n "$race_drain_orphan" && -n "$race_drain_orphan_start" ]] || return 1
    gate_test_process_has_live_start "$race_drain_orphan" "$race_drain_orphan_start"
  }

  race_drain_process_is_stopped() {
    local pid="$1"
    local expected_start="$2"
    local expected_parent="$3"
    local current_state
    race_drain_process_is_expected "$pid" "$expected_start" "$expected_parent" || return 1
    current_state="$(ps -p "$pid" -o stat= 2>/dev/null || true)"
    [[ -n "$current_state" && "$current_state" == *T* ]]
  }

  race_drain_suspend_direct_watchdogs() {
    local label="$1"
    local gate_pid="$2"
    local watchdog_deadline watchdogs watchdog_scan_status race_wd
    local watchdog_command collect_tree_found lineage_watcher_found
    local stopped_deadline stopped_pid stopped_start stopped_parent
    race_drain_watchdog_identities=""
    race_drain_watchdog_count=0
    race_drain_portable_watchdog_count=0
    race_drain_lineage_watcher_count=0
    race_drain_watchdog_start=""
    race_drain_watchdog_parent=""
    watchdog_deadline=$(( $(date +%s) + 10 ))
    while :; do
      if watchdogs="$(pgrep -P "$gate_pid" -f "collect_tree|watch-settle" 2>/dev/null)"; then
        watchdog_scan_status=0
      else
        watchdog_scan_status=$?
      fi
      [[ "$watchdog_scan_status" -le 1 ]] || return 2
      collect_tree_found=0
      lineage_watcher_found=0
      for race_wd in $watchdogs; do
        watchdog_command="$(ps -p "$race_wd" -o command= 2>/dev/null || true)"
        case "$watchdog_command" in
          *collect_tree*) collect_tree_found=1 ;;
        esac
        case "$watchdog_command" in
          *watch-settle*) lineage_watcher_found=1 ;;
        esac
      done
      if [[ "$collect_tree_found" -eq 1 ]] && {
        [[ "$(/usr/bin/uname -s)" != Darwin ]] ||
          [[ "$lineage_watcher_found" -eq 1 ]]
      }; then
        break
      fi
      [[ "$(date +%s)" -lt "$watchdog_deadline" ]] || return 2
      sleep 1
    done
    for race_wd in $watchdogs; do
      watchdog_command="$(ps -p "$race_wd" -o command= 2>/dev/null || true)"
      gate_test_capture_identity "$race_wd" "$gate_pid" || return 2
      race_drain_watchdog_start="$gate_test_captured_start"
      race_drain_watchdog_parent="$gate_test_captured_parent"
      race_drain_watchdog_identities="${race_drain_watchdog_identities}${race_wd}|${race_drain_watchdog_start}|${race_drain_watchdog_parent}"$'\n'
      gate_test_signal_expected "$label" STOP \
        "$race_wd" "$race_drain_watchdog_start" "$race_drain_watchdog_parent" ||
        return 2
      race_drain_watchdog_count=$((race_drain_watchdog_count + 1))
      case "$watchdog_command" in
        *collect_tree*)
          race_drain_portable_watchdog_count=$((race_drain_portable_watchdog_count + 1))
          ;;
      esac
      case "$watchdog_command" in
        *watch-settle*)
          race_drain_lineage_watcher_count=$((race_drain_lineage_watcher_count + 1))
          ;;
      esac
    done
    while IFS='|' read -r stopped_pid stopped_start stopped_parent; do
      [[ -n "$stopped_pid" ]] || continue
      stopped_deadline=$(( $(date +%s) + 10 ))
      while ! race_drain_process_is_stopped \
        "$stopped_pid" "$stopped_start" "$stopped_parent" &&
        [[ "$(date +%s)" -lt "$stopped_deadline" ]]; do
        sleep 1
      done
      race_drain_process_is_stopped \
        "$stopped_pid" "$stopped_start" "$stopped_parent" || return 2
    done <<EOF
$race_drain_watchdog_identities
EOF
  }

  # Return 0 only when a direct child is confirmed gone or a zombie, so a
  # following wait cannot block. Return 1 for its exact live identity, 2 when
  # it still answers but its identity/state cannot be read, and 3 for a PID
  # that now names something else.
  race_drain_direct_wrapper_reap_state() {
    local wrapper_pid="$1"
    local wrapper_start="$2"
    local wrapper_parent="$3"
    local current_start current_parent current_state
    [[ "$wrapper_pid" =~ ^[0-9]+$ && -n "$wrapper_start" ]] || return 2
    if ! kill -0 "$wrapper_pid" 2>/dev/null; then
      return 0
    fi
    current_start="$(TZ=UTC LC_ALL=C LANG=C ps -p "$wrapper_pid" -o lstart= 2>/dev/null || true)"
    [[ -n "$current_start" ]] || return 2
    [[ "$current_start" == "$wrapper_start" ]] || return 3
    current_parent="$(gate_test_process_parent "$wrapper_pid")"
    [[ -n "$current_parent" ]] || return 2
    [[ -z "$wrapper_parent" || "$current_parent" == "$wrapper_parent" ]] || return 3
    current_state="$(ps -p "$wrapper_pid" -o stat= 2>/dev/null || true)"
    [[ -n "$current_state" ]] || return 2
    [[ "$current_state" == Z* ]] && return 0
    return 1
  }

  race_drain_direct_wrapper_is_expected() {
    local wrapper_pid="$1"
    local wrapper_start="$2"
    local wrapper_parent="$3"
    local reap_state
    if race_drain_direct_wrapper_reap_state "$wrapper_pid" "$wrapper_start" "$wrapper_parent"; then
      return 1
    else
      reap_state=$?
    fi
    [[ "$reap_state" -eq 1 ]]
  }

  race_drain_reap_direct_wrapper() {
    local label="$1"
    local wrapper_pid="$2"
    local wrapper_start="$3"
    local wrapper_parent="$4"
    local reap_state wait_status deadline current_start current_parent
    if race_drain_direct_wrapper_reap_state "$wrapper_pid" "$wrapper_start" "$wrapper_parent"; then
      # The probe confirmed a zombie or that this PID no longer answers, so a
      # wait on this direct child cannot block.
      if wait "$wrapper_pid" 2>/dev/null; then
        wait_status=0
      else
        wait_status=$?
      fi
      # `wait` can return a command's signal/non-zero status without proving
      # that this exact PID/start identity left the process table. Do not let a
      # successor inherit the stale owner record until that absence is bounded
      # and explicit. PPID is intentionally not part of this death proof: a
      # dead child can be reparented before it disappears.
      deadline=$(( $(date +%s) + 10 ))
      while gate_test_process_has_start "$wrapper_pid" "$wrapper_start" && \
        [[ "$(date +%s)" -lt "$deadline" ]]; do
        sleep 1
      done
      if gate_test_process_has_start "$wrapper_pid" "$wrapper_start"; then
        current_start="$(gate_test_process_start "$wrapper_pid")"
        current_parent="$(gate_test_process_parent "$wrapper_pid")"
        gate_test_trace_signal post-reap-timeout "$label" NONE "$wrapper_pid" \
          "$wrapper_start" "$current_start" "$wrapper_parent" "$current_parent"
        return 124
      fi
      gate_test_trace_signal post-reap-gone "$label" NONE "$wrapper_pid" \
        "$wrapper_start" "" "$wrapper_parent" ""
      return "$wait_status"
    else
      reap_state=$?
    fi
    case "$reap_state" in
      1)
        echo "interrupted-drain cleanup: ${label} wrapper ${wrapper_pid} is still live; refusing an unbounded reap" >&2
        ;;
      2)
        echo "interrupted-drain cleanup: ${label} wrapper ${wrapper_pid} still answers but its identity/state cannot be read; refusing an unbounded reap" >&2
        ;;
      3)
        echo "interrupted-drain cleanup: ${label} wrapper ${wrapper_pid} no longer has its recorded identity; refusing an unbounded reap" >&2
        ;;
      *)
        echo "interrupted-drain cleanup: ${label} wrapper ${wrapper_pid} had an unknown reap state; refusing an unbounded reap" >&2
        ;;
    esac
    return 124
  }

  race_drain_cleanup_direct_wrapper() {
    local label="$1"
    local wrapper_pid="$2"
    local wrapper_start="$3"
    local wrapper_parent="$4"
    local deadline reap_status signal_status
    [[ -n "$wrapper_pid" && -n "$wrapper_start" && -n "$wrapper_parent" ]] || return 0

    if race_drain_direct_wrapper_is_expected "$wrapper_pid" "$wrapper_start" "$wrapper_parent"; then
      if gate_test_signal_expected "$label" TERM "$wrapper_pid" "$wrapper_start" "$wrapper_parent"; then
        :
      else
        signal_status=$?
        [[ "$signal_status" -eq 1 ]] || return 124
      fi
      deadline=$(( $(date +%s) + 10 ))
      while race_drain_direct_wrapper_is_expected "$wrapper_pid" "$wrapper_start" "$wrapper_parent" && [[ "$(date +%s)" -lt "$deadline" ]]; do sleep 1; done
    fi
    if race_drain_direct_wrapper_is_expected "$wrapper_pid" "$wrapper_start" "$wrapper_parent"; then
      if gate_test_signal_expected "$label" KILL "$wrapper_pid" "$wrapper_start" "$wrapper_parent"; then
        :
      else
        signal_status=$?
        [[ "$signal_status" -eq 1 ]] || return 124
      fi
      deadline=$(( $(date +%s) + 10 ))
      while race_drain_direct_wrapper_is_expected "$wrapper_pid" "$wrapper_start" "$wrapper_parent" && [[ "$(date +%s)" -lt "$deadline" ]]; do sleep 1; done
    fi
    if race_drain_reap_direct_wrapper "$label" "$wrapper_pid" "$wrapper_start" "$wrapper_parent"; then
      return 0
    else
      reap_status=$?
    fi
    # A reaped child can report its command's signal/non-zero status. Cleanup
    # still completed in that case; 124 is reserved for an unsafe reap.
    [[ "$reap_status" -eq 124 ]] && return 124
    return 0
  }

  race_drain_wait_for_direct_wrapper() {
    local label="$1"
    local wrapper_pid="$2"
    local wrapper_start="$3"
    local wrapper_parent="$4"
    local wait_seconds="${5:-10}"
    local deadline
    [[ -n "$wrapper_pid" && -n "$wrapper_start" && -n "$wrapper_parent" ]] || return 0
    if ! [[ "$wait_seconds" =~ ^[0-9]+$ && "$wait_seconds" -ge 1 ]]; then
      echo "interrupted-drain fixture: ${label} has an invalid wait bound" >&2
      return 64
    fi

    deadline=$(( $(date +%s) + wait_seconds ))
    while race_drain_direct_wrapper_is_expected "$wrapper_pid" "$wrapper_start" "$wrapper_parent" && [[ "$(date +%s)" -lt "$deadline" ]]; do sleep 1; done
    if race_drain_direct_wrapper_is_expected "$wrapper_pid" "$wrapper_start" "$wrapper_parent"; then
      race_drain_cleanup_direct_wrapper "$label" "$wrapper_pid" "$wrapper_start" "$wrapper_parent"
      return 124
    fi
    race_drain_reap_direct_wrapper "$label" "$wrapper_pid" "$wrapper_start" "$wrapper_parent"
  }

  race_drain_kill_and_reap_direct_wrapper() {
    local label="$1"
    local wrapper_pid="$2"
    local wrapper_start="$3"
    local wrapper_parent="$4"
    local deadline reap_status signal_status
    [[ -n "$wrapper_pid" && -n "$wrapper_start" && -n "$wrapper_parent" ]] || return 0

    if race_drain_direct_wrapper_is_expected "$wrapper_pid" "$wrapper_start" "$wrapper_parent"; then
      if gate_test_signal_expected "$label" KILL "$wrapper_pid" "$wrapper_start" "$wrapper_parent"; then
        :
      else
        signal_status=$?
        [[ "$signal_status" -eq 1 ]] || return 124
      fi
    fi
    deadline=$(( $(date +%s) + 10 ))
    while race_drain_direct_wrapper_is_expected "$wrapper_pid" "$wrapper_start" "$wrapper_parent" && [[ "$(date +%s)" -lt "$deadline" ]]; do sleep 1; done
    if race_drain_reap_direct_wrapper "$label" "$wrapper_pid" "$wrapper_start" "$wrapper_parent"; then
      return 0
    else
      reap_status=$?
    fi
    [[ "$reap_status" -eq 124 ]] && return 124
    return 0
  }

  race_drain_snapshot_identity_file() {
    local label="$1"
    local source_path="$2"
    local snapshot_path="$3"
    local deadline last_byte owned_pid owned_start
    race_drain_owned_record_error=""
    case "$source_path" in
      "$gate_race_out"/*) ;;
      *)
        race_drain_owned_record_error="${label} path is outside the private fixture output directory: ${source_path}"
        return 124
        ;;
    esac
    if [[ -L "$source_path" || ! -f "$source_path" ||
      ! -O "$source_path" || ! -r "$source_path" || ! -w "$source_path" ]]; then
      race_drain_owned_record_error="${label} path must be an owned readable writable regular file, not a symlink: ${source_path}"
      return 124
    fi
    case "$snapshot_path" in
      "$gate_race_out"/*) ;;
      *)
        race_drain_owned_record_error="${label} snapshot path is outside the private fixture output directory: ${snapshot_path}"
        return 124
        ;;
    esac
    if [[ -L "$snapshot_path" ||
      ( -e "$snapshot_path" &&
        ( ! -f "$snapshot_path" || ! -O "$snapshot_path" ||
          ! -r "$snapshot_path" || ! -w "$snapshot_path" ) ) ]]; then
      race_drain_owned_record_error="${label} snapshot path must be an owned readable writable regular file, not a symlink: ${snapshot_path}"
      return 124
    fi
    : > "$snapshot_path" || {
      race_drain_owned_record_error="${label} snapshot could not be created: ${snapshot_path}"
      return 124
    }
    if [[ -L "$snapshot_path" || ! -f "$snapshot_path" ||
      ! -O "$snapshot_path" || ! -r "$snapshot_path" || ! -w "$snapshot_path" ]]; then
      race_drain_owned_record_error="${label} snapshot path changed ownership, access, or type"
      return 124
    fi
    deadline=$(( $(date +%s) + 5 ))
    while :; do
      if ! cp "$source_path" "$snapshot_path"; then
        race_drain_owned_record_error="${label} could not be copied into its private snapshot"
        return 124
      fi
      if [[ ! -L "$source_path" && -f "$source_path" &&
        -O "$source_path" && -r "$source_path" && -w "$source_path" ]] &&
        cmp -s "$source_path" "$snapshot_path"; then
        break
      fi
      if [[ "$(date +%s)" -ge "$deadline" ]]; then
        race_drain_owned_record_error="${label} did not become stable before the bounded snapshot deadline"
        return 124
      fi
      sleep 1
    done
    if [[ -s "$snapshot_path" ]]; then
      last_byte="$(tail -c 1 "$snapshot_path" 2>/dev/null || true)"
      if [[ -n "$last_byte" ]]; then
        race_drain_owned_record_error="${label} ends with an incomplete identity record"
        return 124
      fi
    fi
    if ! awk -F '|' '
      (NF != 2 && NF != 3) || $1 !~ /^[1-9][0-9]*$/ || length($1) > 10 ||
        $2 == "" || (NF == 3 && $3 !~ /^[1-9][0-9]*$/) || seen[$1]++ { exit 1 }
    ' "$snapshot_path"; then
      race_drain_owned_record_error="${label} contains a malformed or duplicate identity record"
      return 124
    fi
    while IFS='|' read -r owned_pid owned_start owned_parent; do
      [[ -n "$owned_pid" ]] || continue
      if gate_test_pid_is_protected "$owned_pid"; then
        race_drain_owned_record_error="${label} contains protected PID ${owned_pid}"
        return 124
      fi
      [[ -n "$owned_start" ]] || {
        race_drain_owned_record_error="${label} contains an empty start identity for PID ${owned_pid}"
        return 124
      }
      [[ -z "$owned_parent" || "$owned_parent" =~ ^[1-9][0-9]*$ ]] || {
        race_drain_owned_record_error="${label} contains an invalid parent identity for PID ${owned_pid}"
        return 124
      }
    done < "$snapshot_path"
  }

  race_drain_validate_identity_pair() {
    local label="$1"
    local record_path="$2"
    local ack_path="$3"
    local record_snapshot="${record_path}.snapshot"
    local ack_snapshot="${ack_path}.snapshot"
    if ! race_drain_snapshot_identity_file "${label} record" "$record_path" "$record_snapshot"; then
      return 124
    fi
    if ! race_drain_snapshot_identity_file "${label} acknowledgement" "$ack_path" "$ack_snapshot"; then
      return 124
    fi
    if ! cmp -s "$record_snapshot" "$ack_snapshot"; then
      race_drain_owned_record_error="${label} record and acknowledgement snapshots differ"
      return 124
    fi
  }

  # Call this only after every registered producer wrapper is absent. Require
  # three identical nonempty record/ack observations so a child released just
  # after one cmp cannot append an identity outside the cleanup snapshot.
  race_drain_wait_for_stable_identity_pair() {
    local label="$1"
    local record_path="$2"
    local ack_path="$3"
    local record_snapshot="${record_path}.snapshot"
    local ack_snapshot="${ack_path}.snapshot"
    local stable_dir previous_record previous_ack
    local observation_file="${race_drain_pair_observation_file:-}"
    local require_change="${race_drain_pair_require_change:-0}"
    local deadline change_observed=0 stable_observations=0
    local stable_pair_wait_seconds=30
    race_drain_pair_observation_file=""
    race_drain_pair_require_change=0
    [[ -n "$record_path" && -n "$ack_path" ]] || {
      race_drain_owned_record_error="${label} record and acknowledgement paths must both be set"
      return 124
    }
    [[ "$require_change" == "0" || "$require_change" == "1" ]] || {
      race_drain_owned_record_error="${label} has an invalid stability change requirement"
      return 124
    }
    if [[ -n "$observation_file" ]]; then
      case "$observation_file" in
        "$gate_race_out"/*) ;;
        *)
          race_drain_owned_record_error="${label} observation path is outside the private fixture output directory"
          return 124
          ;;
      esac
      if [[ -e "$observation_file" || -L "$observation_file" ]]; then
        race_drain_owned_record_error="${label} observation path must be absent before the first snapshot"
        return 124
      fi
    fi
    stable_dir="$(mktemp -d "$gate_race_out/identity-pair.XXXXXX")" || {
      race_drain_owned_record_error="${label} could not create its private stability directory"
      return 124
    }
    previous_record="$stable_dir/record"
    previous_ack="$stable_dir/ack"
    deadline=$(( $(date +%s) + stable_pair_wait_seconds ))
    while :; do
      if race_drain_validate_identity_pair "$label" "$record_path" "$ack_path" &&
        [[ -s "$record_snapshot" && -s "$ack_snapshot" ]]; then
        if [[ -f "$previous_record" && -f "$previous_ack" ]]; then
          if cmp -s "$record_snapshot" "$previous_record" &&
            cmp -s "$ack_snapshot" "$previous_ack"; then
            if [[ "$require_change" -eq 0 || "$change_observed" -eq 1 ]]; then
              stable_observations=$((stable_observations + 1))
              if [[ "$stable_observations" -ge 2 ]]; then
                rm -rf "$stable_dir"
                return 0
              fi
            fi
          else
            [[ "$require_change" -eq 0 ]] || change_observed=1
            stable_observations=0
          fi
        else
          stable_observations=0
          if [[ -n "$observation_file" ]]; then
            if ! (set -C && : > "$observation_file") 2>/dev/null; then
              race_drain_owned_record_error="${label} could not publish its first-observation marker"
              rm -rf "$stable_dir"
              return 124
            fi
          fi
        fi
        if ! cp "$record_snapshot" "$previous_record" ||
          ! cp "$ack_snapshot" "$previous_ack"; then
          race_drain_owned_record_error="${label} could not retain its stability snapshots"
          rm -rf "$stable_dir"
          return 124
        fi
      else
        stable_observations=0
      fi
      if [[ "$(date +%s)" -ge "$deadline" ]]; then
        race_drain_owned_record_error="${label} record and acknowledgement did not become repeatedly stable before the bounded deadline"
        rm -rf "$stable_dir"
        return 124
      fi
      sleep 1
    done
  }

  # Return 0 when every recorded identity was already absent, 1 when at least
  # one exact fixture-owned survivor was found and removed, and 124 when the
  # record or bounded cleanup could not be proved safe. Validate the complete
  # snapshot before the first signal so one malformed line cannot authorize a
  # partial cleanup.
  race_drain_inspect_owned_record() {
    local label="$1"
    local record_path="$2"
    local snapshot_path="${record_path}.cleanup.snapshot"
    local owned_pid owned_start owned_parent current_start current_parent current_state signal_status
    local deadline found_survivor=0 cleanup_status=0
    race_drain_owned_survivors=""
    if [[ -z "$record_path" ]]; then
      return 0
    fi
    if ! race_drain_snapshot_identity_file "${label} record" "$record_path" "$snapshot_path"; then
      return 124
    fi
    while IFS='|' read -r owned_pid owned_start owned_parent; do
      [[ -n "$owned_pid" ]] || continue
      current_start="$(gate_test_process_start "$owned_pid")"
      current_parent="$(gate_test_process_parent "$owned_pid")"
      gate_test_trace_signal identity "$label" NONE "$owned_pid" \
        "$owned_start" "$current_start" "$owned_parent" "$current_parent"
      if [[ -z "$current_start" ]]; then
        continue
      fi
      if [[ "$current_start" != "$owned_start" ]]; then
        gate_test_trace_signal refused-reused "$label" KILL "$owned_pid" \
          "$owned_start" "$current_start" "$owned_parent" "$current_parent"
        continue
      fi
      current_state="$(gate_test_process_state "$owned_pid")"
      if [[ "$current_state" == Z* ]]; then
        gate_test_trace_signal absent-zombie "$label" NONE "$owned_pid" \
          "$owned_start" "$current_start" "$owned_parent" "$current_parent"
        continue
      fi
      found_survivor=1
      race_drain_owned_survivors="${race_drain_owned_survivors}${race_drain_owned_survivors:+ }${owned_pid}"
      deadline=$(( $(date +%s) + 10 ))
      while gate_test_process_has_live_start "$owned_pid" "$owned_start"; do
        if gate_test_signal_with_current_parent \
          "${label} fixture-owned survivor" KILL "$owned_pid" "$owned_start"; then
          break
        else
          signal_status=$?
        fi
        [[ "$signal_status" -eq 1 ]] && break
        if [[ "$(date +%s)" -ge "$deadline" ]]; then
          cleanup_status=124
          break
        fi
        sleep 1
      done
      deadline=$(( $(date +%s) + 10 ))
      while gate_test_process_has_live_start "$owned_pid" "$owned_start" &&
        [[ "$(date +%s)" -lt "$deadline" ]]; do
        sleep 1
      done
      if gate_test_process_has_live_start "$owned_pid" "$owned_start"; then
        race_drain_owned_record_error="${label} exact survivor ${owned_pid} exceeded its bounded cleanup"
        cleanup_status=124
      fi
    done < "$snapshot_path"
    [[ "$cleanup_status" -eq 0 ]] || return 124
    [[ "$found_survivor" -eq 0 ]] || return 1
    return 0
  }

  # shellcheck disable=SC2329 # invoked through the EXIT cleanup tracker below
  race_drain_inspect_owned_pair() {
    local label="$1"
    local record_path="$2"
    local ack_path="$3"
    if [[ -z "$record_path" && -z "$ack_path" ]]; then
      return 0
    fi
    race_drain_wait_for_stable_identity_pair \
      "$label" "$record_path" "$ack_path" || return 124
    race_drain_inspect_owned_record "$label" "$record_path"
  }

  race_drain_cleanup_suspended_watchdogs() {
    local watchdog_pid watchdog_start watchdog_parent current_parent deadline cleanup_status=0 signal_status
    while IFS='|' read -r watchdog_pid watchdog_start watchdog_parent; do
      [[ -n "$watchdog_pid" && -n "$watchdog_start" ]] || continue
      if [[ ! "$watchdog_parent" =~ ^[0-9]+$ ]]; then
        cleanup_status=124
        continue
      fi
      if gate_test_process_has_live_start "$watchdog_pid" "$watchdog_start"; then
        # Leave a pending TERM unhandled. Resuming this stopped watchdog could
        # make it run its own stale drain path. KILL removes only this exact
        # identity without executing that deferred work.
        current_parent="$(gate_test_process_parent "$watchdog_pid")"
        if gate_test_signal_expected "stopped watchdog" KILL \
          "$watchdog_pid" "$watchdog_start" "$current_parent"; then
          :
        else
          signal_status=$?
          [[ "$signal_status" -eq 1 ]] || cleanup_status=124
        fi
        deadline=$(( $(date +%s) + 10 ))
        while gate_test_process_has_live_start "$watchdog_pid" "$watchdog_start" && [[ "$(date +%s)" -lt "$deadline" ]]; do sleep 1; done
      fi
      if gate_test_process_has_live_start "$watchdog_pid" "$watchdog_start"; then
        echo "interrupted-drain cleanup: watchdog ${watchdog_pid} survived the bounded cleanup wait" >&2
        cleanup_status=124
      fi
    done <<EOF
$race_drain_watchdog_identities
EOF
    return "$cleanup_status"
  }

  # Launch a fixture command through a directly-owned /bin/sh child. The
  # child publishes one exact identity record, then waits for the parent to
  # create a private release file with noclobber. Registration happens before
  # that release, so an EXIT trap can always find the original process.
  race_bound_registered=""
  race_bound_pid=""
  race_bound_start=""
  race_bound_parent=""
  race_bound_dir=""
  race_bound_record=""
  race_bound_release=""
  race_bound_started=""
  race_bound_nonce=""
  race_bound_failure_wait_seconds=35
  race_bound_unregistered=""
  race_bound_sequence=0
  race_bound_job_is_active() {
    local job_pid jobs_output
    jobs_output="$( { jobs -pr; jobs -ps; } 2>/dev/null || true)"
    for job_pid in $jobs_output; do
      [[ "$job_pid" == "$1" ]] && return 0
    done
    return 1
  }
  race_bound_wait_unreleased() {
    local child_pid="$1"
    local wait_seconds="${2:-35}"
    local deadline
    [[ "$wait_seconds" =~ ^[0-9]+$ && "$wait_seconds" -ge 1 ]] || return 124
    deadline=$(( $(date +%s) + wait_seconds ))
    while race_bound_job_is_active "$child_pid" &&
      [[ "$(date +%s)" -lt "$deadline" ]]; do
      sleep 1
    done
    race_bound_job_is_active "$child_pid" && return 124
    wait "$child_pid" 2>/dev/null || true
  }
  race_bound_launch_failure() {
    local message="$1"
    local child_pid="${2:-}"
    local registered=0 wait_status=0
    if [[ -n "$race_bound_dir" && "$race_bound_registered" == *"|${race_bound_dir}|"* ]]; then
      registered=1
    fi
    if [[ -n "$child_pid" && "$registered" -eq 0 ]]; then
      race_bound_wait_unreleased \
        "$child_pid" "$race_bound_failure_wait_seconds" || wait_status=$?
    fi
    if [[ "$registered" -eq 0 ]]; then
      if [[ -z "$child_pid" || "$wait_status" -eq 0 ]]; then
        [[ -z "$race_bound_dir" ]] || rm -rf "$race_bound_dir"
        race_bound_pid=""
        race_bound_start=""
        race_bound_parent=""
        race_bound_dir=""
        race_bound_record=""
        race_bound_release=""
        race_bound_started=""
        race_bound_nonce=""
      else
        race_bound_unregistered="${race_bound_unregistered}${race_bound_unregistered:+$'\n'}${child_pid}|${race_bound_dir}|${race_bound_failure_wait_seconds}"
        echo "launch-bound fixture failed: unregistered child ${child_pid} remained active after its derived wait bound" >&2
      fi
    fi
    echo "launch-bound fixture failed: $message" >&2
    return 1
  }
  race_bound_launch_command() {
    local label="$1"
    local seconds="$2"
    shift 2
    local command_name="${1:-}"
    local child_pid child_record_line child_record_last_byte child_start child_parent
    local deadline
    race_bound_pid=""
    race_bound_start=""
    race_bound_parent=""
    race_bound_dir=""
    race_bound_record=""
    race_bound_release=""
    race_bound_started=""
    race_bound_nonce=""
    if ! [[ "$seconds" =~ ^[0-9]+$ && "$seconds" -ge 1 ]]; then
      race_bound_launch_failure "$label has an invalid hard bound"
      return 1
    fi
    race_bound_failure_wait_seconds=$((seconds + 5))
    if [[ -z "$command_name" ]]; then
      race_bound_launch_failure "$label has no command"
      return 1
    fi
    if ! race_bound_dir="$(mktemp -d "$gate_race_out/launch-bound.XXXXXX")"; then
      race_bound_launch_failure "$label could not create a private launch directory"
      return 1
    fi
    race_bound_record="$race_bound_dir/identity"
    race_bound_release="$race_bound_dir/release"
    race_bound_started="$race_bound_dir/started"
    race_bound_sequence=$((race_bound_sequence + 1))
    race_bound_nonce="launch-bound-${gate_test_outer_pid}-${race_bound_sequence}"
    if ! [[ ! -e "$race_bound_record" && ! -L "$race_bound_record" &&
      ! -e "$race_bound_release" && ! -L "$race_bound_release" &&
      ! -e "$race_bound_started" && ! -L "$race_bound_started" ]]; then
      race_bound_launch_failure "$label release or record path existed before fork"
      return 1
    fi
    /bin/sh -c '
      race_bound_seconds=$1
      race_bound_record=$2
      race_bound_release=$3
      race_bound_started=$4
      shift 4
      race_bound_pid=$$
      race_bound_start=$(TZ=UTC LC_ALL=C LANG=C ps -p "$race_bound_pid" -o lstart= 2>/dev/null) || exit 64
      race_bound_parent=$PPID
      [ -n "$race_bound_start" ] || exit 64
      [ "$race_bound_parent" -eq "$PPID" ] 2>/dev/null || exit 64
      (set -C && printf "%s|%s|%s\n" "$race_bound_pid" "$race_bound_start" "$race_bound_parent" > "$race_bound_record") || exit 64
      exec 7>&-
      exec 8>&-
      race_bound_deadline=$(( $(date +%s) + race_bound_seconds ))
      while [ ! -s "$race_bound_release" ] &&
        [ "$(date +%s)" -lt "$race_bound_deadline" ]; do
        sleep 1
      done
      race_bound_release_value=""
      race_bound_release_line_count=0
      while IFS= read -r race_bound_release_line || [ -n "$race_bound_release_line" ]; do
        race_bound_release_line_count=$((race_bound_release_line_count + 1))
        if [ "$race_bound_release_line_count" -ne 1 ] || [ -z "$race_bound_release_line" ]; then
          exit 64
        fi
        race_bound_release_value=$race_bound_release_line
      done < "$race_bound_release"
      [ "$race_bound_release_line_count" -eq 1 ] || exit 64
      [ -n "$race_bound_release_value" ] || exit 64
      (set -C && printf "%s\n" "$race_bound_release_value" > "$race_bound_started") || exit 64
      exec "$@"
    ' launch-bound-child "$seconds" "$race_bound_record" "$race_bound_release" \
      "$race_bound_started" "$@" &
    child_pid=$!
    race_bound_pid="$child_pid"
    deadline=$(( $(date +%s) + 15 ))
    child_record_line=""
    while [[ -z "$child_record_line" && "$(date +%s)" -lt "$deadline" ]]; do
      if [[ -f "$race_bound_record" ]]; then
        child_record_last_byte="$(tail -c 1 "$race_bound_record" 2>/dev/null || true)"
        if [[ -z "$child_record_last_byte" ]]; then
          child_record_line="$(awk 'NF { print; count++ } END { if (NR != 1 || count != 1) exit 1 }' \
            "$race_bound_record" 2>/dev/null || true)"
        fi
      fi
      [[ -n "$child_record_line" ]] || sleep 1
    done
    if [[ -z "$child_record_line" ]]; then
      race_bound_launch_failure "$label child did not publish one identity record" "$child_pid"
      return 1
    fi
    IFS='|' read -r child_record_pid child_start child_parent <<EOF
$child_record_line
EOF
    [[ "$child_record_pid" == "$child_pid" &&
      "$child_start" != *'|'* && -n "$child_start" &&
      "$child_parent" =~ ^[0-9]+$ &&
      "$child_parent" == "$gate_test_signal_shell_pid" ]] || {
      race_bound_launch_failure "$label child identity record was malformed" "$child_pid"
      return 1
    }
    gate_test_pid_is_protected "$child_record_pid" && {
      race_bound_launch_failure "$label child identity is protected" "$child_pid"
      return 1
    }
    gate_test_process_is_expected "$child_pid" "$child_start" "$child_parent" || {
      race_bound_launch_failure "$label child identity was not exact" "$child_pid"
      return 1
    }
    [[ ! -e "$race_bound_started" && ! -L "$race_bound_started" ]] || {
      race_bound_launch_failure "$label started marker existed before registration" "$child_pid"
      return 1
    }
    race_bound_start="$child_start"
    race_bound_parent="$child_parent"
    race_bound_registered="${race_bound_registered}${race_bound_registered:+$'\n'}${child_pid}|${child_start}|${child_parent}|${race_bound_dir}|${label}|${race_bound_nonce}|${race_bound_started}"
    [[ ! -e "$race_bound_started" && ! -L "$race_bound_started" ]] || {
      race_bound_launch_failure "$label started marker appeared before release" "$child_pid"
      return 1
    }
    (set -C && printf "%s\n" "$race_bound_nonce" > "$race_bound_release") || {
      race_bound_launch_failure "$label release could not be atomically published" "$child_pid"
      return 1
    }
    deadline=$(( $(date +%s) + 15 ))
    while [[ ! -s "$race_bound_started" && "$(date +%s)" -lt "$deadline" ]]; do sleep 1; done
    if [[ ! -s "$race_bound_started" ]] || ! awk -v expected="$race_bound_nonce" '
        NR == 1 { if (NF != 1 || $0 != expected) bad = 1; found = 1 }
        NR > 1 { bad = 1 }
        END { exit(bad || !found ? 1 : 0) }
    ' "$race_bound_started"; then
      race_bound_launch_failure "$label started marker did not match the release" "$child_pid"
      return 1
    fi
    gate_test_process_is_expected "$child_pid" "$child_start" "$child_parent" || {
      race_bound_launch_failure "$label child identity changed after release" "$child_pid"
      return 1
    }
  }
  # shellcheck disable=SC2329 # invoked only through cleanup_interrupted_drain_fixture
  race_bound_cleanup_unregistered() {
    local status=0
    local pending=""
    local child_pid child_dir wait_seconds
    while IFS='|' read -r child_pid child_dir wait_seconds; do
      [[ -n "$child_pid" ]] || continue
      if ! race_bound_wait_unreleased "$child_pid" "$wait_seconds"; then
        pending="${pending}${pending:+$'\n'}${child_pid}|${child_dir}|${wait_seconds}"
        status=124
        continue
      fi
      if [[ -n "$child_dir" ]] && ! rm -rf "$child_dir"; then
        pending="${pending}${pending:+$'\n'}${child_pid}|${child_dir}|${wait_seconds}"
        status=124
      fi
    done <<EOF
$race_bound_unregistered
EOF
    race_bound_unregistered="$pending"
    return "$status"
  }
  # shellcheck disable=SC2329 # invoked only through cleanup_interrupted_drain_fixture
  race_bound_cleanup_registered() {
    local status=0
    local pending=""
    local child_pid child_start child_parent child_dir child_label child_nonce child_started
    while IFS='|' read -r child_pid child_start child_parent child_dir child_label child_nonce child_started; do
      [[ -n "$child_pid" ]] || continue
      if gate_test_process_has_start "$child_pid" "$child_start"; then
        race_drain_kill_and_reap_direct_wrapper \
          "launch-bound ${child_label}" "$child_pid" "$child_start" "$child_parent" ||
          status=124
      fi
      if gate_test_process_has_start "$child_pid" "$child_start"; then
        pending="${pending}${pending:+$'\n'}${child_pid}|${child_start}|${child_parent}|${child_dir}|${child_label}|${child_nonce}|${child_started}"
        status=124
      else
        rm -rf "$child_dir"
      fi
    done <<EOF
$race_bound_registered
EOF
    race_bound_registered="$pending"
    return "$status"
  }

  # Remove completed launch records without signalling any fixture that still
  # has its registered process identity. The EXIT trap retains every live one.
  race_bound_prune_completed() {
    local pending=""
    local child_pid child_start child_parent child_dir child_label child_nonce child_started
    while IFS='|' read -r child_pid child_start child_parent child_dir child_label child_nonce child_started; do
      [[ -n "$child_pid" ]] || continue
      if gate_test_process_has_start "$child_pid" "$child_start"; then
        pending="${pending}${pending:+$'\n'}${child_pid}|${child_start}|${child_parent}|${child_dir}|${child_label}|${child_nonce}|${child_started}"
      else
        rm -rf "$child_dir"
      fi
    done <<EOF
$race_bound_registered
EOF
    race_bound_registered="$pending"
  }

  race_zombie_release_and_reap_supervisor() {
    local release_status=0 wait_status child_deadline
    [[ -n "$race_zombie_supervisor" ]] || return 0
    case "$race_zombie_supervisor_release" in
      "$gate_race_out"/*) ;;
      *) return 124 ;;
    esac
    if [[ -L "$race_zombie_supervisor_release" ]]; then
      return 124
    elif [[ ! -e "$race_zombie_supervisor_release" ]]; then
      (set -C && : > "$race_zombie_supervisor_release") 2>/dev/null ||
        release_status=124
    elif [[ ! -f "$race_zombie_supervisor_release" ||
      ! -O "$race_zombie_supervisor_release" ||
      ! -r "$race_zombie_supervisor_release" ||
      ! -w "$race_zombie_supervisor_release" ]]; then
      release_status=124
    fi
    if [[ -n "$race_zombie_supervisor_start" &&
      -n "$race_zombie_supervisor_parent" ]]; then
      if race_drain_wait_for_direct_wrapper \
        "production zombie supervisor" "$race_zombie_supervisor" \
        "$race_zombie_supervisor_start" "$race_zombie_supervisor_parent" 35; then
        :
      else
        wait_status=$?
        [[ "$wait_status" -ne 124 ]] || release_status=124
      fi
    else
      race_bound_wait_unreleased "$race_zombie_supervisor" 35 ||
        release_status=124
    fi
    child_deadline=$(( $(date +%s) + 10 ))
    while [[ -n "$race_zombie_child" &&
      -n "$race_zombie_child_start" ]] &&
      gate_test_process_has_start \
        "$race_zombie_child" "$race_zombie_child_start" &&
      [[ "$(date +%s)" -lt "$child_deadline" ]]; do
      sleep 0.1
    done
    [[ -z "$race_zombie_child" || -z "$race_zombie_child_start" ]] ||
      ! gate_test_process_has_start \
        "$race_zombie_child" "$race_zombie_child_start" ||
      release_status=124
    [[ "$release_status" -eq 0 ]] || return "$release_status"
    race_zombie_supervisor=""
    race_zombie_supervisor_start=""
    race_zombie_supervisor_parent=""
    race_zombie_child=""
    race_zombie_child_start=""
    return 0
  }

  # shellcheck disable=SC2329 # invoked through the EXIT cleanup dispatcher
  race_drain_cleanup_b_settler() {
    local current_parent signal_status deadline
    [[ -n "$race_drain_b_settler" &&
      -n "$race_drain_b_settler_start" ]] || return 0
    if gate_test_process_has_live_start \
      "$race_drain_b_settler" "$race_drain_b_settler_start"; then
      current_parent="$(gate_test_process_parent "$race_drain_b_settler")"
      [[ "$current_parent" =~ ^[1-9][0-9]*$ ]] || return 124
      if gate_test_signal_expected \
        "interrupted-drain B native settler" KILL \
        "$race_drain_b_settler" "$race_drain_b_settler_start" \
        "$current_parent"; then
        :
      else
        signal_status=$?
        [[ "$signal_status" -eq 1 ]] || return 124
      fi
      deadline=$(( $(date +%s) + 10 ))
      while gate_test_process_has_live_start \
        "$race_drain_b_settler" "$race_drain_b_settler_start" &&
        [[ "$(date +%s)" -lt "$deadline" ]]; do
        sleep 0.1
      done
    fi
    ! gate_test_process_has_live_start \
      "$race_drain_b_settler" "$race_drain_b_settler_start" || return 124
    race_drain_b_settler=""
    race_drain_b_settler_start=""
    return 0
  }

  # shellcheck disable=SC2329 # invoked by the EXIT trap below
  cleanup_interrupted_drain_fixture() {
    local status=$?
    local deadline cleanup_status=0 final_status
    trap - EXIT
    race_cleanup_track() {
      "$@" || cleanup_status=124
    }
    race_cleanup_track_absent_ok() {
      local result
      if "$@"; then
        return 0
      else
        result=$?
      fi
      [[ "$result" -eq 1 ]] || cleanup_status=124
      return 0
    }
    if [[ -n "$race_drain_hold_file" ]]; then
      if [[ -L "$race_drain_hold_file" ]]; then
        echo "interrupted-drain cleanup: refusing to release symlink $race_drain_hold_file" >&2
        cleanup_status=124
      elif [[ ! -e "$race_drain_hold_file" ]]; then
        if ! (set -C && : > "$race_drain_hold_file") 2>/dev/null; then
          echo "interrupted-drain cleanup: could not release $race_drain_hold_file" >&2
          cleanup_status=124
        fi
      elif [[ ! -f "$race_drain_hold_file" ]]; then
        echo "interrupted-drain cleanup: refusing to release non-regular path $race_drain_hold_file" >&2
        cleanup_status=124
      fi
    fi
    if race_drain_victim_is_expected; then
      race_cleanup_track_absent_ok gate_test_signal_with_current_parent "held command" TERM \
        "$race_drain_orphan" "$race_drain_orphan_start"
      deadline=$(( $(date +%s) + 10 ))
      while race_drain_victim_is_expected && [[ "$(date +%s)" -lt "$deadline" ]]; do sleep 1; done
      if race_drain_victim_is_expected; then
        race_cleanup_track_absent_ok gate_test_signal_with_current_parent "held command" KILL \
          "$race_drain_orphan" "$race_drain_orphan_start"
        deadline=$(( $(date +%s) + 10 ))
        while race_drain_victim_is_expected && [[ "$(date +%s)" -lt "$deadline" ]]; do sleep 1; done
      fi
      if race_drain_victim_is_expected; then
        echo "interrupted-drain cleanup: victim $race_drain_orphan survived the bounded cleanup wait" >&2
        cleanup_status=124
      fi
    fi
    race_cleanup_track race_drain_cleanup_direct_wrapper \
      "A gate" "$race_drain_a_wrapper" "$race_drain_a_wrapper_start" \
      "$race_drain_a_wrapper_parent"
    race_cleanup_track race_drain_cleanup_direct_wrapper \
      "B gate" "$race_drain_b_wrapper" "$race_drain_b_wrapper_start" \
      "$race_drain_b_wrapper_parent"
    race_cleanup_track race_drain_cleanup_b_settler
    race_cleanup_track race_drain_cleanup_direct_wrapper \
      "C gate" "$race_drain_c_wrapper" "$race_drain_c_wrapper_start" \
      "$race_drain_c_wrapper_parent"
    race_cleanup_track race_drain_cleanup_direct_wrapper \
      "fork-on-TERM A gate" "$race_fork_wrapper" "$race_fork_wrapper_start" \
      "$race_fork_wrapper_parent"
    race_cleanup_track race_drain_cleanup_direct_wrapper \
      "fork-and-exit A gate" "$race_forkexit_wrapper" \
      "$race_forkexit_wrapper_start" "$race_forkexit_wrapper_parent"
    # Stop every registered publisher before freezing record/ack pairs. A
    # still-live publisher can append immediately after an otherwise clean cmp.
    race_cleanup_track race_bound_cleanup_unregistered
    race_cleanup_track race_bound_cleanup_registered
    race_cleanup_track_absent_ok race_drain_inspect_owned_pair \
      "fork-on-TERM" "$race_fork_record" "$race_fork_ack"
    race_cleanup_track_absent_ok race_drain_inspect_owned_pair \
      "fork-and-exit" "$race_forkexit_record" "$race_forkexit_ack"
    race_cleanup_track_absent_ok race_drain_inspect_owned_record \
      "publisher probe" "$race_fork_probe_record"
    race_cleanup_track race_drain_cleanup_direct_wrapper \
      "fork-on-TERM bystander" "$race_fork_bystander" \
      "$race_fork_bystander_start" "$race_fork_bystander_parent"
    race_cleanup_track race_drain_cleanup_direct_wrapper \
      "fork-and-exit bystander" "$race_forkexit_bystander" \
      "$race_forkexit_bystander_start" "$race_forkexit_bystander_parent"
    race_cleanup_track race_drain_cleanup_direct_wrapper \
      "fork-record unit bystander" "$race_fork_unit_bystander" \
      "$race_fork_unit_bystander_start" "$race_fork_unit_bystander_parent"
    race_cleanup_track race_zombie_release_and_reap_supervisor
    race_cleanup_track race_drain_cleanup_suspended_watchdogs
    final_status="$status"
    if [[ "$final_status" -eq 0 && "$cleanup_status" -ne 0 ]]; then
      final_status=124
    fi
    exit "$final_status"
  }
  trap cleanup_interrupted_drain_fixture EXIT

  cd "$gate_race_repo"
  git init -q
  git config user.email test@example.invalid
  git config user.name "Quality Gate Test"
  printf 'fixture\n' > fixture.txt
  mkdir -p tools
  # These fixed sleeps only need to outlast the bounded production drain and
  # fixture inspection. The child-published identity records own them; argv does not.
  gate_race_fork_seconds=600
  gate_race_forkexit_seconds=601
  # The two contention cases need this to outlast the stagger between their
  # waiters, or two unexcluded runs would simply miss each other and the
  # assertion would pass on broken code. Every other case only needs the gate
  # to execute something, so they run it at its cheap default.
cat > tools/trunk <<STUB
#!/usr/bin/env bash
if [ "\${1:-} \${2:-}" = "daemon status" ]; then
  printf 'x Daemon stopped\n'
  exit 1
fi
if [ -n "\${RACE_STUB_VICTIM_PID:-}" ] || [ -n "\${RACE_STUB_VICTIM_LSTART:-}" ] || [ -n "\${RACE_STUB_VIOLATION_FILE:-}" ]; then
  [ -n "\${RACE_STUB_VICTIM_PID:-}" ] && [ -n "\${RACE_STUB_VICTIM_LSTART:-}" ] && [ -n "\${RACE_STUB_VIOLATION_FILE:-}" ] || {
    echo "race stub victim identity and violation file must be set together" >&2
    exit 64
  }
  race_stub_victim_state="\$(TZ=UTC LC_ALL=C LANG=C ps -p "\$RACE_STUB_VICTIM_PID" -o stat= 2>/dev/null | awk 'NF { print \$1; exit }' || true)"
  race_stub_victim_start="\$(TZ=UTC LC_ALL=C LANG=C ps -p "\$RACE_STUB_VICTIM_PID" -o lstart= 2>/dev/null || true)"
  case "\$race_stub_victim_state" in
    Z*) race_stub_victim_can_execute=0 ;;
    *) race_stub_victim_can_execute=1 ;;
  esac
  if [ -n "\$race_stub_victim_start" ] &&
    [ "\$race_stub_victim_start" = "\$RACE_STUB_VICTIM_LSTART" ] &&
    [ "\$race_stub_victim_can_execute" -eq 1 ]; then
    if ! (set -C && printf 'victim=%s|%s\\n' "\$RACE_STUB_VICTIM_PID" "\$RACE_STUB_VICTIM_LSTART" > "\$RACE_STUB_VIOLATION_FILE") 2>/dev/null; then
      echo "race stub could not atomically publish the C-before-victim-death violation" >&2
      exit 64
    fi
  fi
fi
race_stub_private_file_is_safe() {
  local race_stub_private_path="\$1"
  [[ -n "\$race_stub_private_path" && ! -L "\$race_stub_private_path" &&
    -f "\$race_stub_private_path" && -O "\$race_stub_private_path" &&
    -r "\$race_stub_private_path" && -w "\$race_stub_private_path" ]]
}
race_stub_fork_job_is_active() {
  local race_stub_jobs_output race_stub_job_pid
  race_stub_jobs_output="\$( { jobs -pr; jobs -ps; } 2>/dev/null || true)"
  for race_stub_job_pid in \$race_stub_jobs_output; do
    [ "\$race_stub_job_pid" = "\$1" ] && return 0
  done
  return 1
}
race_stub_fork_failure() {
  local race_stub_failure_message="\$1"
  local race_stub_failure_child="\${2:-}"
  if [[ "\${race_stub_fork_record_fd_open:-0}" -eq 1 ]]; then
    exec 7>&-
    race_stub_fork_record_fd_open=0
  fi
  if [[ "\${race_stub_fork_ack_fd_open:-0}" -eq 1 ]]; then
    exec 8>&-
    race_stub_fork_ack_fd_open=0
  fi
  if [[ -n "\$race_stub_failure_child" ]]; then
    race_stub_fork_deadline=\$(( \$(date +%s) + 50 ))
    while race_stub_fork_job_is_active "\$race_stub_failure_child" &&
      [ "\$(date +%s)" -lt "\$race_stub_fork_deadline" ]; do
      sleep 1
    done
    if ! race_stub_fork_job_is_active "\$race_stub_failure_child"; then
      wait "\$race_stub_failure_child" 2>/dev/null || true
      [[ -z "\${race_stub_fork_release_dir:-}" ]] ||
        rm -rf "\$race_stub_fork_release_dir"
    fi
  elif [[ -n "\${race_stub_fork_release_dir:-}" ]]; then
    rm -rf "\$race_stub_fork_release_dir"
  fi
